def filter_file_in_dir_with_keywords(dir_folder, list_kwd_yes_or_1=[], list_kwd_no_or_2=[], print_bsn = False):
    print(f'\n[filter_file_in_dir_with_keywords] dir_folder = {dir_folder}')
    #[1] Check if directory exists
    if not os.path.isdir(dir_folder):
        raise FileNotFoundError(f'The directory {dir_folder} was not found.')
    
    #[2] Get list of files in the directory, no folders.
    list_bsns = [file for file in os.listdir(dir_folder) if os.path.isfile(os.path.join(dir_folder, file))]
    cnt_before = len(list_bsns)
    
    #[3] Filter names by keywords to select
    if list_kwd_yes_or_1 != []:
        list_bsns = [file for file in list_bsns if any(keyword in file for keyword in list_kwd_yes_or_1)]
    
    #[4] Filter names by keywords to discard
    if list_kwd_no_or_2 != []:
        list_bsns = [file for file in list_bsns if not any(keyword in file for keyword in list_kwd_no_or_2)]
        
    #[5] Generate file paths and orint
    list_paths = [os.path.join(dir_folder, file) for file in list_bsns]
    cnt_after = len(list_bsns)
    if print_bsn:
        print(f'\n--  Count (before, after) = {cnt_before}, {cnt_after}. list_bsns: \n{list_bsns}', end='\n\n')
    return list_paths, list_bsns

"""
Try to avoid using program to delete files because it's irreversible. Just name the dump_folder_name='01_delete' and then delete it mannually later.
Don't add a variable of delete=False.
"""

def batch_file_relocate(dir_folder, list_kwd_yes_or_1=[], list_kwd_no_or_2=[], dump_folder_name='01_dump', print_bsn=False):
    print('\n[batch_file_relocate]')
    
    #[1] Filter files
    list_paths, list_bsn = filter_file_in_dir_with_keywords(dir_folder, list_kwd_yes_or_1, list_kwd_no_or_2, print_bsn)
    cnt = len(list_paths)
    if cnt == 0:
        print(f'There is nothing we need to move. File count = {cnt}.')
        return [], []
    
    #[2] Create a dump folder if it does not exist
    dir_dump = os.path.join(dir_folder, dump_folder_name)
    if not os.path.exists(dir_dump):
        os.mkdir(dir_dump)
        print("--Directory didn't exist. Just created one.")
    else:
        print("--Directory already exists. Skipping directory creation.")
    
    #[4] Iterate through file list to move files
    for iter_file in list_paths:
        file_name = os.path.basename(iter_file)
        destination_path = os.path.join(dir_dump, file_name)
        
        #[5] Move the file and handle potential naming conflicts
        try: 
            shutil.move(iter_file, destination_path)
        except shutil.Error:
            bsn_ext = os.path.splitext(file_name)
            suffix = 1
            new_file_name = f'{bsn_ext[0]}_dup{suffix}{bsn_ext[1]}'
            new_destination_path = os.path.join(dir_dump, new_file_name)
            
            while os.path.exists(new_destination_path):
                suffix += 1
                new_file_name = f'{bsn_ext[0]}_dup{suffix}{bsn_ext[1]}'
                new_destination_path = os.path.join(dir_dump, new_file_name)
            
            shutil.move(iter_file, new_destination_path)
    
    #[6] Final report
    if print_bsn:
        print(f'--  Finish moving {cnt} files. list_bsn: \n{list_bsn}\n\n')
    
    return list_paths, list_bsn


def collect_files_in_dir_and_subdir_with_keywords_in_bsn(dir, list_kwd_no_or_1 = [], list_kwd_yes_or_2 = [], list_kwd_yes_or_3 = []):
      print('\n[collect_files_in_dir_and_subdir_with_keywords_in_bsn]')
      #[1] Check if directory exists
      if not os.path.isdir(dir):
            raise FileNotFoundError(f"The directory '{dir}' was not found.")
      #[2] Initialize a list to hold the full paths of the files that match the keywords
      list_path = []
      #[3] Walk through the directory and its subdirectories to get a list of files
      for dirpath, _dirnames, basenames in os.walk(dir):
            for iter_bsn in basenames:
                  # Apply the filters progressively, skipping the file as soon as one condition fails
                  if list_kwd_no_or_1 and any(keyword in iter_bsn for keyword in list_kwd_no_or_1):
                        continue  # Skip this file as it contains a keyword from list_kwd_no_or_1
                  if list_kwd_yes_or_2 and not any(keyword in iter_bsn for keyword in list_kwd_yes_or_2):
                        continue  # Skip this file as it doesn't contain any keyword from list_kwd_yes_or_2
                  if list_kwd_yes_or_3 and not any(keyword in iter_bsn for keyword in list_kwd_yes_or_3):
                        continue  # Skip this file as it doesn't contain any keyword from list_kwd_yes_or_3
                  # If the function reaches this point, the file matches all criteria
                  list_path.append(os.path.join(dirpath, iter_bsn))
      return list_path


def count_files_in_dir_and_subdir_with_keywords_in_bsn(dir, list_kwd_yes_or_1):
      print('\n[collect_files_in_dir_and_subdir_with_keywords_in_bsn]')
      print('\n--(Index from 0 to len(list_kwd_yes_or_1)-1 are the numbers that falls into these catagories.)')
      #[1] Check if directory exists
      if not os.path.isdir(dir):
            raise FileNotFoundError(f"The directory '{dir}' was not found.")
      #[2] Initialize a list to hold the full paths of the files that match the keywords
      int_total_kwd = len(list_kwd_yes_or_1)
      list_kwd_count = [0] * (int_total_kwd + 2)
      #[3] Walk through the directory and its subdirectories to get a list of files
      for cnt, output  in enumerate(os.walk(dir)):
            dirpath, _dirnames, basenames = output
            #[4] Iterate through basenames in dir and subdir.
            for iter_bsn in basenames:
                  no_match = 0
                  #[5] Iterate through kwywords. 
                  for cnt_kwd, iter_kwd in enumerate(list_kwd_yes_or_1):
                        #print(f'[{cnt}] {iter_bsn}, {iter_kwd}')
                        if iter_kwd in iter_bsn:
                              list_kwd_count[cnt_kwd] += 1
                              #print(f'--list_kwd_count[{cnt_kwd}] += 1')
                        else:
                              no_match += 1
                  if no_match == int_total_kwd:
                        list_kwd_count[int_total_kwd] += 1
                  list_kwd_count[int_total_kwd + 1] += 1
      return list_kwd_count


