def check_if_two_folders(dir_master, dir_slave, slave_replace_with, list_kwd_yes_or_1, list_kwd_no_or_2):
    # [1] List of files in two folders.
    list_paths_m, list_bsn_m = filter_file_in_dir_with_keywords(dir_master, list_kwd_yes_or_1, list_kwd_no_or_2, False)
    list_paths_s, list_bsn_s = filter_file_in_dir_with_keywords(dir_slave, list_kwd_yes_or_1, list_kwd_no_or_2, False)

    # [6] Split element with "_reduced".
    if slave_replace_with:
        str_replace, str_with = slave_replace_with
        list_bsn_s = [filename.replace(str_replace, str_with) for filename in list_bsn_s]

    # [8] Check if similar.
    if sorted(list_bsn_m) == sorted(list_bsn_s):
        print('All background sample images have a reduced version.')
    else:
        print('Does not match. Clear the reduced folder and process again.')

    # [9] Remove all the files (no folders) in the dir_slave.
    for iter_r in os.listdir(dir_slave):
        path_iter_r = os.path.join(dir_slave, iter_r)
        if os.path.isfile(path_iter_r):
            os.remove(path_iter_r)

    # [12] Copy every file from dir_master to dir_slave.
    for file_path in list_paths_m:
        shutil.copy(file_path, dir_slave)


