def consolidate_folders(new_folder_name=None):
    """
    1. Ask user to select one or more source folders (list_path_scf).
    2. Count the files in these folders (list_file_cnt_scf).
    3. Create destination folder (dir_dest).
    4. Copy everything in list_path_scf into dir_dest.
    5. Check if the sum of list_file_cnt_scf is the number of files in dir_dest, and print result.
    """
    #[1] Tkinter to select folders.
    root = tk.Tk()
    root.withdraw()  # Hide the root window
    file_paths = filedialog.askopenfilenames(title="Select folders")
    
    # Get unique folder paths
    list_path_scf = list(set(os.path.dirname(path) for path in file_paths))
    
    #[2] Count files in the selected folders.
    list_bsn_scf = [os.path.basename(folder) for folder in list_path_scf]
    list_file_cnt_scf = [len(os.listdir(folder)) for folder in list_path_scf]
    
    #[3] If new_folder_name not provided, name it with the first folder.
    path_1st_scf = list_path_scf[0]
    dir_1st_scf = os.path.dirname(path_1st_scf)
    if not new_folder_name:
        bsn_1st_folder = os.path.basename(path_1st_scf)
        new_folder_name = f'{bsn_1st_folder} (et al)'
    dir_dest = os.path.join(dir_1st_scf, new_folder_name)
    
    #[4] Make dir.
    try:
        os.mkdir(dir_dest)
        print("--Directory didn't exist. Just made one.")
    except FileExistsError:
        print("--Directory already exists. Skipping directory creation.")
    
    #[5] Copy files from source folders to destination folder.
    total_files_copied = 0
    for folder in list_path_scf:
        for item in os.listdir(folder):
            s = os.path.join(folder, item)
            d = os.path.join(dir_dest, item)
            if os.path.isdir(s):
                shutil.copytree(s, d, dirs_exist_ok=True)
            else:
                shutil.copy2(s, d)
            total_files_copied += 1
    
    #[6] Verify if the sum of list_file_cnt_scf is the number of files in dir_dest.
    total_files_in_scf = sum(list_file_cnt_scf)
    total_files_in_dest = len(os.listdir(dir_dest))
    if total_files_copied == total_files_in_dest == total_files_in_scf:
        print(f"Consolidation successful: {total_files_copied} files copied.")
    else:
        print(f"Consolidation mismatch: {total_files_in_scf} files expected, "
              f"{total_files_copied} files copied, {total_files_in_dest} files in destination.")

    return dir_dest


