import numpy as np
import matplotlib.pyplot as plt
from mpl_toolkits import mplot3d
from scipy.optimize import fsolve

SUB = str.maketrans("0123456789", "₀₁₂₃₄₅₆₇₈₉")
SUP = str.maketrans("0x23456789", "⁰x²³⁴⁵⁶⁷⁸⁹")  # SUP = str.maketrans("0123456789", "⁰¹²³⁴⁵⁶⁷⁸⁹")

r_min = 0; r_max = 1; r_num = 5
theta_num = 7; theta_min = np.pi / theta_num; theta_max = np.pi - theta_min
phi_num = 8; phi_min = 2 * np.pi / phi_num; phi_max = 2 * np.pi

R = np.round(np.linspace(r_min, r_max, r_num), 3)
Theta = np.round(np.linspace(theta_min, theta_max, theta_num), 3)
Phi = np.round(np.linspace(phi_min, phi_max, phi_num), 3)

X = [];
Y = [];
Z = []

AN = 1;
a0 = 0.0529  # Unit: nm

def PBD_surface(r):
    rho = AN * r / a0
    wf1s = 1 / np.sqrt(np.pi) * np.power(AN / a0, 3 / 2) * np.exp(-rho)
    pd1s = np.power(wf1s, 2)
    return pd1s - 0.01  # This is isosurface value.

def PBD_value(r, theta, phi):
    rho = AN * r / a0
    wf1s = 1 / np.sqrt(np.pi) * np.power(AN / a0, 3 / 2) * np.exp(-rho)
    pd1s = np.power(wf1s, 2)
    return pd1s

fig = plt.figure('Wavefunction of 1s orbit', figsize=(12, 6))
plt.subplots_adjust(left=0.05, right=0.95, bottom=0.1, top=0.9, wspace=None, hspace=None)
ax1 = fig.add_subplot(121, projection='3d')
ax1.view_init(azim=-60, elev=20)

# ax.scatter(X, Y, Z)
# https://stackoverflow.com/questions/55375515/change-marker-color-in-3d-scatter-plot-based-on-condition


for theta in Theta:
    for phi in Phi:
        r = fsolve(PBD_surface, 0.01)
        x = np.round(r * np.sin(theta) * np.cos(phi), 3)
        y = np.round(r * np.sin(theta) * np.sin(phi), 3)
        z = np.round(r * np.cos(theta), 3)
        ax1.scatter(x, y, z, c='g', marker='o', alpha=0.5)
        X = np.append(X, x);
        Y = np.append(Y, y);
