import numpy as np                          # For basic math.
import matplotlib.pyplot as plt             # For plot.
from mpl_toolkits import mplot3d            # For plot to function normally.
from scipy.optimize import fsolve           # To find the solution.
import pylab                                # To plot the surface.
from mayavi import mlab
from inspect import currentframe, getframeinfo

'''
[ Concept - Plot 1s orbit in 3D mesh with mayavi. ]
1.  Generate a set of spherical coordinates, where Theta_myv and Phi_myv are 2D arrays.
    , and R_myv is a 2D array with same size.
2.  Generate a set of 3D Cartesian coordinates, where X_myv, Y_myv, and Z_myv are 2d arrays with the same size.
3.  Calculate individual s_R_myv in R_myv at every corresponding Theta_myv and Phi_myv.
4.  Convert spherical coordinates into 3D Cartesian coordinates.
5.  Decoration and plot.
'''

# For subscript and superscript.
SUB = str.maketrans("0123456789", "₀₁₂₃₄₅₆₇₈₉")
SUP = str.maketrans("0x23x56789", "⁰x²³x⁵⁶⁷⁸⁹")  # SUP = str.maketrans("0123456789", "⁰¹²³⁴⁵⁶⁷⁸⁹")

# Setting boundary.
r_min = 0; r_max = 1; r_num = 5
theta_num = 5; theta_min = np.pi / theta_num; theta_max = np.pi - theta_min
phi_num = 8; phi_min = 2 * np.pi / phi_num; phi_max = 2 * np.pi

# For linear plot.
R_lnr = np.round(np.linspace(r_min, r_max, r_num), 3)
Theta_lnr = np.round(np.linspace(theta_min, theta_max, theta_num), 3)
Phi_lnr = np.round(np.linspace(phi_min, phi_max, phi_num), 3)

# For mayavi.
Theta_myv, Phi_myv = np.mgrid[0:np.pi: theta_num * 1j, 0:phi_max:(phi_num + 1) * 1j]
# Use the size of Theta_myv(or Phi_myv) to define R_myv as a 2D array with same dimension but full of None.
# It has to be none; otherwise, the value of individual R_myv[i, j] cannot be assigned,
R_myv = np.array([[None for i in range(int(len(Theta_myv[0])))] for j in range(int(len(Theta_myv)))])


# Define X_i, Y_i and Z_i to be a sphere, preventing: NameError: name 'X_i' is not defined.
r_myv = 1.00  # r_myv is only used in this part.
X_myv = np.round(r_myv * np.sin(Theta_myv) * np.cos(Phi_myv), 3)
Y_myv = np.round(r_myv * np.sin(Theta_myv) * np.sin(Phi_myv), 3)
Z_myv = np.round(r_myv * np.cos(Theta_myv), 3)

# Check the data during construction.
print('Check the 2D arrays. R_myv of Nones; Theta_myv and Phi_myv.')
'''print('R_myv:', R_myv.size, '\n', R_myv)
print('Theta_myv:', Theta_myv.size, '\n', Theta_myv)
print('Phi_myv:', Phi_myv.size, '\n', Phi_myv)'''

# A way to print individual elements in an 2D array.
print('\n', 'Check elements in Phi_myv:', sep="")
'''for i in range(len(Phi_myv)):
    print(i,'th row [ ', end='', sep="")
    for j in range(len(Phi_myv[i])):
        print(np.round(Phi_myv[i][j],3), end=', ')
    print('] next row.')'''


AN = 1; a0 = 0.0529  # Unit: nm

def PBD_surface(r):
    rho = AN * r / a0
    wf1s = 1 / np.sqrt(np.pi) * np.power(AN / a0, 3 / 2) * np.exp(-rho)
    pd1s = np.power(wf1s, 2)
    return pd1s - 0.01  # This is isosurface value.


# https://stackoverflow.com/questions/55375515/change-marker-color-in-3d-scatter-plot-based-on-condition
print('\n','Calculate individual R_myv', sep="")
for i in range(len(R_myv)):
    for j in range(len(R_myv[i])):
        s_R_myv = float(np.round(fsolve(PBD_surface, 0.01), 3))
        R_myv[i, j] = s_R_myv
        #print(s_R_myv, ', ', end='')
    #print(' ')
#print('\n','New R_myv (in 2D array):','\n', R_myv)
print('Solution of last r, R_myv[', i, ',', j, '] = ', s_R_myv, sep="")

print('\n','Calculate individual X_myv, Y_myv, Z_myv.', sep="")
for i in range(len(Theta_myv)):
    for j in range(len(Theta_myv[i])):
        s_X_myv = np.round(R_myv[i, j] * np.sin(Theta_myv[i, j]) * np.cos(Phi_myv[i, j]), 3)
        s_Y_myv = np.round(R_myv[i, j] * np.sin(Theta_myv[i, j]) * np.sin(Phi_myv[i, j]), 3)
        s_Z_myv = np.round(R_myv[i, j] * np.cos(Theta_myv[i, j]), 3)
        X_myv[i, j] = float(s_X_myv)
        Y_myv[i, j] = float(s_Y_myv)
        Z_myv[i, j] = float(s_Z_myv)

print('Last element (', i, ',', j, '): = [', s_X_myv, ',',s_Y_myv, ',',s_Z_myv,']', sep="")
print('[X_myv] Dimension: ', X_myv.ndim, '; size : ', X_myv.size, '; length : ', len(X_myv), '\n', X_myv)
print('[Y_myv] Dimension: ', Y_myv.ndim, '; size : ', Y_myv.size, '; length : ', len(Y_myv), '\n', Y_myv)
print('[Z_myv] Dimension: ', Z_myv.ndim, '; size : ', Z_myv.size, '; length : ', len(Z_myv), '\n', Z_myv)
frameinfo = getframeinfo(currentframe()); print('[Current line]', frameinfo.lineno) # Line indicator.
