# File path: D:\01_Floor\a_Ed\09_EECS\10_Python\02_Practice\2022-0702_Linear Approach Practice\ML-SPP-04_Linear Approach Example.py

"""
[ML-SPP-04_Linear Approach Example]
Purpose: Use an online example to understand ML.
Author: Meng-Chi Ed Chen
Date: 2022-06-12
Reference:
    1.https://hackmd.io/@lido2370/r1-0nSPYN?type=view
    3.
"""

import torch
import matplotlib.pyplot as plt
import torch.nn as nn
import torch.nn.functional as F

nn_node_1 = 5
nn_node_2 = 5
data_point = 1000

class ThisModel(nn.Module):
    def __init__(self):
        super(ThisModel, self).__init__()
        self.nn1 = nn.Linear(1, nn_node_1)
        self.nn2 = nn.Linear(nn_node_1, nn_node_2)
        self.nn3 = nn.Linear(nn_node_2, 1)

    def forward(self, x):
        x = F.relu(self.nn1(x))
        x = F.relu(self.nn2(x))
        x = self.nn3(x)
        return x


model = ThisModel()
print(model)

# Generate Data Set for learning
X = torch.unsqueeze(torch.linspace(-2, 2, data_point), dim=1)  # x data (tensor), shape=(100, 1)
Y = 2*(X+1)*X*(X-1) + 0.8*torch.rand(X.size())-0.4              # noisy y data (tensor), shape=(100, 1)
plt.scatter(X.data.numpy(), Y.data.numpy())
#plt.show()

X = torch.Tensor(X.reshape(data_point, 1))
Y = torch.Tensor(Y.reshape(data_point, 1))


optimizer = torch.optim.RMSprop(model.parameters(), lr=0.005)
loss_function = torch.nn.MSELoss()


epochs = 501
for epoch in range(epochs):
    prediction = model(X)
    loss = loss_function(prediction, Y)
    optimizer.zero_grad()
    loss.backward()
    optimizer.step()

    if epoch % 50 == 0:
        # plot and show learning process
        plt.cla()
        plt.scatter(X.data.numpy(), Y.data.numpy(), s=1)
        plt.plot(X.data.numpy(), prediction.data.numpy(), 'r-', lw=3)
        text_string = ' Loss=%.4f' % loss.data.numpy() + '\n' \
                      + 'epochs = %.0f' % epoch
        plt.text(0, 5, text_string, fontdict={'size': 10, 'color':  'green'})
        plt.savefig("D:/01_Floor/a_Ed's/16_Coding/03_Python/06_Stock Price Prediction/03_ML-SPP/ML-SPP-04_images/"
                    + 'IMG' + str(epoch) + '.jpg')
        plt.pause(0.1)



print('nn_node_1 =', nn_node_1, '\n'
      , 'nn_node_2 =', nn_node_2)
print('Final loss = %.4f' % loss + '\nTotal epoch = %.0f' % epoch)

print('\n', ThisModel, '\n')
for name, param in model.named_parameters():
    print(name)
    print(param, "\n")


plt.show(block=True)
# End of [ML-SPP-04_Linear Approach Example.py]




