def filter_file_in_dir_with_keywords(dir_folder, list_kwd_yes_or_1=[], list_kwd_no_or_2=[], print_bsn = False):
    print('\n[filter_file_in_dir_with_keywords]')
    #[1] Check if directory exists
    if not os.path.isdir(dir_folder):
        raise FileNotFoundError(f"The directory '{dir_folder}' was not found.")
    
    #[2] Get list of files in the directory, no folders.
    list_bsn = [file for file in os.listdir(dir_folder) if os.path.isfile(os.path.join(dir_folder, file))]
    cnt_before = len(list_bsn)
    
    #[3] Filter names by keywords to select
    if list_kwd_yes_or_1 != []:
        list_bsn = [file for file in list_bsn if any(keyword in file for keyword in list_kwd_yes_or_1)]
    
    #[4] Filter names by keywords to discard
    if list_kwd_no_or_2 != []:
        list_bsn = [file for file in list_bsn if not any(keyword in file for keyword in list_kwd_no_or_2)]
        
    #[5] Generate file paths and orint
    list_paths = [os.path.join(dir_folder, file) for file in list_bsn]
    cnt_after = len(list_bsn)
    if print_bsn:
        print(f'\n--  Count (before, after) = {cnt_before}, {cnt_after}. list_bsn: \n{list_bsn}', end='\n\n')
    return list_paths, list_bsn


def batch_file_relocate(dir_folder, list_kwd_yes_or_1 = [], list_kwd_no_or_1  = [], dump_folder_name = '01_dump', print_bsn = False):
    """
    [2023-12-13] 
    Replocate batch file based on keywords.
    """
    print('\n[batch_file_relocate]')

    #[1] Filter files
    filtered_files = filter_file_in_dir_with_keywords(dir_folder, list_kwd_yes_or_1, list_kwd_no_or_1, print_bsn)
    list_file_paths = [file for file in filtered_files[0] if not os.path.isdir(os.path.join(dir_folder, file))] # Don't move folders.
    path_destination = os.path.join(dir_folder, dump_folder_name)
    if len(list_file_paths) == 0:
        return # Exit the function if there is nothing we need to move. Don't even create a dump folder.
    try:
        os.mkdir(path_destination)
        print("--Directory wan't exists. Just made one.")
    except FileExistsError:
        print("--Directory already exists. Skipping directory creation.")
        
    #[5] Print file names and file list.
    if print_bsn:
        print (f'--[ {len(list_file_paths)} files to move]:', filtered_files[1])

    full_directory_list = [os.path.join(dir_folder, file) for file in list_file_paths]

    list_file_names = [file for file in os.listdir(dir_folder)
                    if os.path.isfile(os.path.join(dir_folder, file))]
    
    #[10] Iterate through file list to move files.
    for iter_file in full_directory_list:
        file_name = os.path.basename(iter_file)
        try: 
            shutil.move(iter_file, path_destination) # Move the files.
        except shutil.Error: # If file already existed in dump folder, generate a new file name with a number suffix.
            file_name_parts = os.path.splitext(file_name)
            new_file_name = file_name_parts[0] + '_dup' + file_name_parts[1]
            new_destination_path = os.path.join(path_destination, new_file_name)
            try:
                shutil.move(iter_file, new_destination_path)
            except:
                print('--[Error] Failed to move or rename the file.')
                
    print('--batch_file_relocate complete')
    if print_bsn:
        print('--list_file_names:', list_file_names, end='\n\n')
    return list_file_paths, list_file_names

def make_dir_if_not_exist(dir=None, dir_name='Test'):
    #[1] Make a name for the dir if not provided.
    if not dir:
        dir = os.path.dirname(os.path.abspath(__file__))
        timestamp = datetime.now().strftime("%Y-%m%d-%H%M%S")
        dir = os.path.join(dir, f'{timestamp}_dir_name')
        
    #[2] Make dir.
    try:
        os.mkdir(dir)
        print("--Directory wasn't exists. Just made one.")
    except FileExistsError:
        print("--Directory already exists. Skipping directory creation.")


