def crop_to_same_size(path_img_t1, path_img_t2):
    print('\n[crop_to_same_size] sometimes, sizes differ by a few pixels, causing issues.')

    # [1] Read images
    img1 = cv2.imread(path_img_t1)
    img2 = cv2.imread(path_img_t2)
    
    # [2] Check size
    img1_height, img1_width = img1.shape[:2]
    img2_height, img2_width = img2.shape[:2]
    
    # [3] Two images have the same size.
    if img1_width == img2_width and img1_height == img2_height:
        print('--Two images have the same size.', img1_width, ' x ', img1_height)
        path_img_t1_cropped = path_img_t1
        path_img_t2_cropped = path_img_t2
    
    # [4] Need to crop the image.
    else:
        print(f'--Two images have different sizes. Image_1: {img1_width}x{img1_height}; Image_2: {img2_width}x{img2_height}.')
        width_min = min(img1_width, img2_width)
        height_min = min(img1_height, img2_height)
        img1_cropped = img1[0:height_min, 0:width_min]
        img2_cropped = img2[0:height_min, 0:width_min]
        img1_height, img1_width = img1_cropped.shape[:2]
        img2_height, img2_width = img2_cropped.shape[:2]
        print(f'--After crop. Image_1: {img1_width}x{img1_height}; Image_2: {img2_width}x{img2_height}.')
        path_img_t1_cropped = path_img_t1.replace('.png', '_crop.png')
        path_img_t2_cropped = path_img_t2.replace('.png', '_crop.png')
        cv2.imwrite(path_img_t1_cropped, img1_cropped) 
        cv2.imwrite(path_img_t2_cropped, img2_cropped) 
        
    return path_img_t1_cropped, path_img_t2_cropped


def enhance_image(path_img, clipLimit, tileGridSize):
    #[1] Read image
    arrimg = cv2.imread(path_img)
    if arrimg is None:
        print(f"Error: Image at {path_img} could not be loaded.")
        
    #[2] Enhance image
    lab = cv2.cvtColor(arrimg, cv2.COLOR_BGR2LAB) # Converting to LAB color space
    l_channel, a, b = cv2.split(lab)
    clahe = cv2.createCLAHE(clipLimit=clipLimit, tileGridSize=(tileGridSize, tileGridSize)) # clipLimit = 2, tileGridSize = 8
    cl = clahe.apply(l_channel)
    limg = cv2.merge((cl, a, b)) # Merge the CLAHE enhanced L-channel with the a and b channel
    arrimg_enh = cv2.cvtColor(limg, cv2.COLOR_LAB2BGR) # Converting from LAB Color model to BGR color space
    
    #[3] Save enhanced image.
    img_ext = os.path.splitext(path_img)[1] # Find file extension so that it works with different image files.
    path_img_enhanced = path_img.replace(img_ext, '_2-enh' + img_ext)
    cv2.imwrite(path_img_enhanced, arrimg_enh)
    #print('--Image enhanced:', os.path.basename(path_img_enhanced))
    return path_img_enhanced




def extract_Z_um_from_filename(filename):
    #[1] Regular expression to find '_Z' followed by digits
    match = re.search(r'_Z(\d+)', filename)
    
    #[2] Extract and return the number if a match is found
    if match:
        Z_um = int(match.group(1))
        return Z_um
    else:
        return 0  # Return 0 if no match is found. It can't be zero.


def normalize_grayscale_image(arrimg):
    #[1] Check if arrimg is 2D.
    if len(arrimg.shape) != 2:
        raise ValueError(f'Input array image is not 2D. Please check. {arrimg.shape}')
    
    #[2] Normalize between 0 and 255
    arrimg_min = arrimg.min()
    arrimg_max = arrimg.max()
    
    #[3] Avoid division by zero if the image is completely uniform
    if arrimg_max - arrimg_min == 0:
        arrimg_norm = np.zeros_like(arrimg)
    else:
        arrimg_norm = 255 * (arrimg - arrimg_min) / (arrimg_max - arrimg_min)
    
    #[5] Ensure the result is in uint8 format
    arrimg_norm = arrimg_norm.astype(np.uint8)
    
    return arrimg_norm
    

def variance_of_laplacian(arrimg):
    #[1] Optionally, resize the image to reduce noise and computation
    """k = 0.5
    h, w, c = arrimg.shape
    arrimg = cv2.resize(arrimg, (int(w * k), int(h * k)))"""
    
    #[2] Convert to grayscale, Apply Gaussian blur, Compute the Laplacian
    arrimg_gray = cv2.cvtColor(arrimg, cv2.COLOR_BGR2GRAY)
    arrimg_blurred = cv2.GaussianBlur(arrimg_gray, (3, 3), 0)
    laplacian = cv2.Laplacian(arrimg_blurred, cv2.CV_64F)    
    
    #[4] Optionally, apply a threshold to set small values to zero
    #_, laplacian_thresh = cv2.threshold(laplacian, 0.001, 0.01, cv2.THRESH_TOZERO)
    
    #[5] Calculate the variance of the Laplacian
    sharpness = laplacian.var() * 1000
    return sharpness


def tenengrad(arrimg):
    # Convert the image to grayscale
    gray = cv2.cvtColor(arrimg, cv2.COLOR_BGR2GRAY)
    # Apply the Sobel operator
    sobel_x = cv2.Sobel(gray, cv2.CV_64F, 1, 0, ksize=3)
    sobel_y = cv2.Sobel(gray, cv2.CV_64F, 0, 1, ksize=3)
    # Compute the gradient magnitude
    gradient_magnitude = np.sqrt(sobel_x**2 + sobel_y**2)
    # Compute the sum of squares of the gradient magnitudes
    sharpness = np.sum(gradient_magnitude**2)
    return sharpness


def sum_modified_laplacian(arrimg):
    # Convert the image to grayscale
    gray = cv2.cvtColor(arrimg, cv2.COLOR_BGR2GRAY)
    # Compute the Laplacian in the x and y directions
    laplacian_x = cv2.Sobel(gray, cv2.CV_64F, 1, 0, ksize=3)
    laplacian_y = cv2.Sobel(gray, cv2.CV_64F, 0, 1, ksize=3)
    # Compute the absolute values of the Laplacian
    abs_laplacian_x = np.abs(laplacian_x)
    abs_laplacian_y = np.abs(laplacian_y)
    # Sum the absolute values of the Laplacian
    sharpness = np.sum(abs_laplacian_x + abs_laplacian_y)
    return sharpness


def calculate_MSE_color_difference(arrimg):
    """
    This function calculates the mean squared error (MSE) of the color difference from the mean color of an image.

    Steps:
    1. Resize the image to 50% of the original size.
    2. Calculate the mean color of the resized image. The mean color is a 1D array with three elements (B, G, R).
    3. For each pixel, subtract the mean color to get the pixel difference.
    4. Square the pixel difference and calculate the mean for each channel (B, G, R).
    5. Sum the mean squared errors of the three channels to get the total MSE.

    [Caution]
    This method works well for a single location. However, for locations with more features, the maximum MSE will be larger.
    Therefore, it's not comparable across different locations.
    """
    #[1] Resize image to k times the original size.
    k = 0.5
    h, w, c = arrimg.shape
    arrimg = cv2.resize(arrimg, (int(w * k), int(h * k)))
    
    #[2] Calculate mean pixel color.
    arr_mean_color = arrimg.mean(axis=(0, 1))
    
    #[3] Calculate the mean-square-error (MSE) of pixel colors from the mean color.
    pixel_diff = arrimg - arr_mean_color
    pixel_MSE = ((pixel_diff) ** 2).mean(axis=(0, 1))
    pixel_MSE_sum = pixel_MSE.sum()
    print(f'pixel_MSE = {pixel_MSE}, \t pixel_MSE_sum = {pixel_MSE_sum}.')
    return pixel_MSE_sum


def create_a_10_by_10_photo_collage(dir_image, list_kwd_no_or_1, prefix='collage', dir_collage=None, save_text_log=False):
    """
    Create a 10x10 photo collage from a list of image paths. 
    If there are more than 100 images, create a second collage. 
    If there are fewer than 100 images, leave the extra space black.
    Use the size of the first image as standard.
    Resize images if their size is not the same. Print an error and append to the error log.
    """
    print('\n[create_a_10_by_10_photo_collage]')
    #[1] Get only image files.
    acceptable_formats = ['.jpg', '.jpeg', '.png', '.bmp', '.gif']
    list_path_img = [os.path.join(dir_image, f) for f in os.listdir(dir_image) if os.path.splitext(f)[1].lower() in acceptable_formats]
    
    #[2] Remove file that contain keywords in list_kwd_no_or_2.
    list_path_img = [f for f in list_path_img if not any(kwd in f for kwd in list_kwd_no_or_1)]
    
    #[2] Create text error log.
    timestamp = datetime.now().strftime('%Y-%m%d-%H%M%S')
    text_log = f'{timestamp}\n\n'
    
    #[3] Use the size of the first image as standard to create a blank canvas for the collage.
    path_img_1st = list_path_img[0]
    arrimg_1st = cv2.imread(path_img_1st)
    h_standard, w_standard = arrimg_1st.shape[:2]
    h_collage, w_collage = h_standard * 10, w_standard * 10
    collage_canvas = np.zeros((h_collage, w_collage, 3), dtype=np.uint8)
    
    #[4] Name the saving directory if not provided.
    dir_img_1st = os.path.dirname(list_path_img[0])
    if dir_collage is None:
        dir_collage = os.path.join(os.path.dirname(dir_img_1st), f'{os.path.basename(dir_img_1st)}_3-Collage')
    
    #[5] Make saving directory if it does not exist.
    try:
        os.mkdir(dir_collage)
        text = f'--Directory did not exist. Created one: {dir_collage}'
        print(text)
        text_log += f'\n{text}\n'
    except FileExistsError:
        text = f'--Directory already exists. Skipping directory creation: {dir_collage}'
        print(text)
        text_log += f'\n{text}\n'
        
    #[6] Calculate the number of collages needed.
    num_images = len(list_path_img)
    num_collages = (num_images // 100)

    #[7] Loop through each collage.
    for idx_collage in range(num_collages):
        collage_canvas[:] = 0  # Reset the collage canvas for each new collage
        
        #[8] Place images in the collage.
        for i in range(100):
            #[9] Calculate the position of the current image.
            row = i // 10
            col = i % 10
            
            #[10] Calculate the overall index of the image in the list.
            img_index = idx_collage * 100 + i
            
            #[11] If there are still images left to add, read and resize the image.
            if img_index < num_images:
                try:
                    img = cv2.imread(list_path_img[img_index])
                    img = cv2.resize(img, (w_standard, h_standard))
                except Exception as e:
                    error_message = f'--Error processing image: {list_path_img[img_index]}, Error: {str(e)}'
                    print(error_message)
                    text_log += f'{error_message}\n'
                    img = np.zeros((h_standard, w_standard, 3), dtype=np.uint8)
            else:
                #[12] If there are no more images, use a black square.
                img = np.zeros((h_standard, w_standard, 3), dtype=np.uint8)
            
            #[13] Place the image on the collage.
            collage_canvas[row*h_standard:(row+1)*h_standard, col*w_standard:(col+1)*w_standard] = img
        
        #[14] Save the collage.
        path_collage = os.path.join(dir_collage, f'{prefix}_{idx_collage:02d}.png')
        cv2.imwrite(path_collage, collage_canvas)
        text = f'--Saved collage: {path_collage}'
        print(text)
        text_log += f'{text}\n'

    #[15] Save the error log.
    if save_text_log:
        timestamp = datetime.now().strftime('%Y-%m%d-%H%M')
        path_log = os.path.join(dir_collage, f'collage_creation_log_{timestamp}.txt')
        with open(path_log, 'w') as log_file:
            log_file.write(text_log)
        text = f'--Saved error log: {path_log}'
        print(text)
        text_log += f'{text}\n'



#[3] Image - End
 


