def get_working_cameras():
    print('\n[get_working_cameras]')
    # [1] Define the maximum number of cameras to check, and initiate list
    max_cameras = 10
    list_cam = []
    
    # [3] Loop through the potential camera indices
    for cam_idx in range(max_cameras):
        # [4] Try to open the camera
        cam_name = cv2.VideoCapture(cam_idx)
        time.sleep(1)
        
        # [5] Check if the camera is opened successfully
        if cam_name.isOpened():
            # [6] Get camera properties
            width = cam_name.get(cv2.CAP_PROP_FRAME_WIDTH)
            height = cam_name.get(cv2.CAP_PROP_FRAME_HEIGHT)
            fps = cam_name.get(cv2.CAP_PROP_FPS)
            
            list_cam.append({
                "Camera Name": cam_name,
                "Camera Index": cam_idx,
                "Status": "Working",
                "Resolution": f"{int(width)}x{int(height)}",    # Keep the format of this line.
                "FPS": fps                                      # Keep the format of this line.
            })
            
            # [7] Release the camera
            cam_name.release()
        else:
            break
    
    # [9] Create a DataFrame from the list of cameras
    df_working_cam = pd.DataFrame(list_cam)
    
    # [10] Return the DataFrame
    return df_working_cam


def simple_capture_one_image(cam_name, cam_idx, sec_wait, dir_save, bsn):
    # [1] Open camera, wait, and read.
    cam_name = cv2.VideoCapture(cam_idx)
    print(f'\n-- [{cam_idx}] Wait {int(sec_wait)} seconds for camera ({cam_name}) to open.')
    time.sleep(sec_wait)
    ret, frame = cam_name.read()
    
    # [3] Check if the frame was captured successfully
    if ret:
        
        # [4] Create the path to save the image
        path_save = os.path.join(dir_save, f'camera_{cam_idx:02d}_{bsn}.jpg')
        
        # [6] Save the captured frame as an image
        cv2.imwrite(path_save, frame)
        print(f'-- Image saved for Camera Index {cam_idx} at {path_save}')
    else:
        print(f'-- Failed to capture image for Camera Index {cam_idx}')
    
    # [8] Release the camera
    cam_name.release()


def select_the_microscope_camera(width, height, fps, df_working_cam, sec_wait, capture_image, dir_save):
    print('\n[select_the_microscope_camera]', end='')
    # [1] Iterate through the DataFrame rows to find a matching camera
    for index, row in df_working_cam.iterrows():
        
        # [2] Extract the resolution and fps of the current camera
        cam_resolution = row['Resolution']
        cam_fps = row['FPS']
        
        # [3] Parse the resolution to get width and height
        cam_width, cam_height = map(int, cam_resolution.split('x'))
        
        # [4] Check if the current camera matches the desired specifications
        if cam_width == width and cam_height == height and cam_fps == fps:
            
            #[5] Collect desired camera info.
            cam_name = row["Camera Name"]
            cam_idx = row["Camera Index"]
            print(f' cam_idx = {cam_idx}')
            
            #[6] Optionally capture one image and save.
            if capture_image:
                sec_wait = 1
                timestamp = datetime.now().strftime("%H%M%S")
                simple_capture_one_image(cam_name, cam_idx, sec_wait, dir_save, timestamp)
            
            return cam_idx
    
    # [10] Return None if no matching camera is found
    return None



def capture_one_image_at_each_working_camera(dir_save, df_working_cam, sec_wait):
    print('\n[capture_one_image_at_each_working_camera]')
    # [1] Ensure the directory where the images will be saved exists.
    os.makedirs(dir_save, exist_ok=True)
    
    # [2] Iterate through the DataFrame of working cameras
    for index, row in df_working_cam.iterrows():
        cam_name = row["Camera Name"]
        cam_idx = row["Camera Index"]
        
        # [3] Capture one image
        simple_capture_one_image(cam_name, cam_idx, sec_wait, dir_save, '0')
    
    


