import os, sys, cv2, time, serial, re
import numpy as np
from datetime import datetime
import matplotlib.pyplot as plt



import M1_Utilities as M1UTL
import M2_Devices as M2DEV





#[1] Camera - Start

def clear_camera_buffer(capture, num_frames_to_clear=5):
    for _ in range(num_frames_to_clear):
        ret, frame = capture.read()
        if not ret:
            print("Failed to grab frame")

def capture_and_save(capture, sharpness_method, dir_captured, text_capture, attempt_count, Z_coord_um , add_timestamp=False):
    #[1] Wait for the stage to settle and the camera to focus
    time.sleep(0.2)
    clear_camera_buffer(capture) 
    
    #[2] Capture new frame and calculate sharpness
    ret, frame = capture.read()
    if not ret:
        print("Failed to capture frame after moving linear stage.")
        return None
    
    #[4] Select sharpness_method
    if sharpness_method == 'variance_of_laplacian':
        sharpness = M1UTL.variance_of_laplacian(frame)
    elif sharpness_method == 'tenengrad':
        sharpness = M1UTL.tenengrad(frame)
    elif sharpness_method == 'sum_modified_laplacian':
        sharpness = M1UTL.sum_modified_laplacian(frame)
    elif sharpness_method == 'calculate_MSE_color_difference':
        sharpness = M1UTL.calculate_MSE_color_difference(frame)
    else:
        raise ValueError(f'Selected sharpness_method "{sharpness_method}" does not exist. Please check.')
    
    #[6] Save image
    if add_timestamp:
        timestamp = datetime.now().strftime("%Y-%m%d-%H%M%S")
        path_capture_image = os.path.join(dir_captured,
                                        f'{timestamp}_{text_capture}_{attempt_count:03}_Z{Z_coord_um}_Sharp{int(sharpness)}.png')
    else:
        path_capture_image = os.path.join(dir_captured,
                                        f'{text_capture}_{attempt_count:03}_Z{Z_coord_um}_Sharp{int(sharpness)}.png')
    cv2.imwrite(path_capture_image, frame)
    return sharpness

#[1] Camera - End









#[8] Auto Focus - Start


def move_down_until_collision(XYZ_coord_mm, max_attempt=30, move_up_first=True):
    print('\n[move_down_until_collision]')
    
    #[1] Unpack coordinates
    X_coord_mm, Y_coord_mm, Z_coord_mm = XYZ_coord_mm
    print(f'-- max_attempt = {max_attempt}, about {max_attempt*0.1:.2f} mm.')
    
    #[2] Open serial port to Arduino
    ser_arduino = serial.Serial('COM3', 9600, timeout=2)
    time.sleep(2) 
    print('Serial opened. Wait for 2 seconds.')
    time.sleep(2) 
    
    #[4] Move Z up by 1 mm.
    if move_up_first:
        
        #[5] Case "U" move Z up(+) for 1000 um (1 mm).
        try:
            message = 'U' + '\n'    
            ser_arduino.write(message.encode())
            Z_coord_mm -= 0.1
            print('\nMoved Z up by 1000 um (1 mm). Z_coord_mm =', "%0.4f" % Z_coord_mm)
            time.sleep(0.1)
        except KeyboardInterrupt:
            print('Serial communication with Arduino stopped.')
    
    #[6] Start taking steps
    for iter_attempt in range(max_attempt):

        #[7] Case "R" move Z down(-) for 100 um (0.1 mm).
        try:
            message = 'R' + '\n'
            ser_arduino.write(message.encode())
            Z_coord_mm -= 0.1
            print(f'\n[{iter_attempt:02d}] Moved Z down by 100 um (0.1 mm). Z_coord_mm =', "%0.4f" % Z_coord_mm)
            time.sleep(0.3)
        except KeyboardInterrupt:
            print('Serial communication with Arduino stopped.')
        
        #[8] Request status report from Arduino
        list_XYZP = M2DEV.send_message_to_arduino_and_wait_for_reply(ser_arduino, '3', timeout=5)
        
        #[9] Check for collision
        if list_XYZP[3] == '0':
            print(f'\nCollision detected at attempt {iter_attempt}. Resetting Z_coord_mm to 0.')
            Z_coord_mm = 0
            XYZ_coord_mm = [X_coord_mm, Y_coord_mm, Z_coord_mm]
            return XYZ_coord_mm

    #[10] Return the final coordinates if no collision detected
    text = f'\nFinish {iter_attempt} attempts, but still no collision.\n'\
            f'Please visually check if everything is fine.\n'\
            f'System exit.'
    print(text)
    sys.exit()
    return [X_coord_mm, Y_coord_mm, Z_coord_mm]
             


def stepwise_sharpness_recording(capture, ser, sharpness_method, dir_save, text_capture, Z_direction, total_attempts, Z_coord_um, move_to_sharpest):
    print('\n[autofocus_routine_real]')
    
    #[1] Last Z_coord_um
    list_sharpness = []
    list_Z_coord_um = []
    #Z_coord_um = list_Z_coord_um[-1]
    
    #[2] Start moving
    pass_sharpness = False
    for attempt in range(total_attempts):
        
        #[5] Capture image and calculate sharpness.
        current_sharpness = capture_and_save(capture, sharpness_method, dir_save, text_capture, len(list_sharpness), Z_coord_um)
        
        #[8] Record sharpness
        print(f'\n[Attempt {attempt}] sharpness: {round(current_sharpness, 3)}')
        list_sharpness.append(current_sharpness)
        list_Z_coord_um.append(Z_coord_um)
        
        #[10] Move Z-axis according to four different conditions.
        if Z_direction == 'O_up_100um':
            ser.write('O\n'.encode())
            Z_coord_um += 100
        elif Z_direction == 'R_down_100um':
            ser.write('R\n'.encode())
            Z_coord_um -= 100
        elif Z_direction == 'I_up_10um':
            ser.write('I\n'.encode())
            Z_coord_um += 10
        elif Z_direction == 'L_down_10um':
            ser.write('L\n'.encode())
            Z_coord_um -= 10
        elif Z_direction == 'C_up_2.5um':
            ser.write('C\n'.encode())
            Z_coord_um += 10
        elif Z_direction == 'F_down_2.5um':
            ser.write('F\n'.encode())
            Z_coord_um -= 10
        else:
            raise ValueError('Invalide Z_direction setting: {Z_direction}. Please check.')
        
        #[13] Report Z_coord_um.
        print(f'--(Z_coord_um, current_sharpness) = \t{Z_coord_um:.2f} um, \t{current_sharpness:.4f}.')
        time.sleep(0.1)
        
        #[15] Check if point of maximum sharpness has been found.
        if attempt >= 2:
            print(f'--(current_sharpness, last_sharpness) = \t{current_sharpness:.4f}, \t{last_sharpness:.4f}')
            if current_sharpness < last_sharpness * 0.95 and pass_sharpness:
                print(f'--We might passed z position with maximum sharpness at attempt {attempt - 1}.')
                pass_sharpness = Ture
            else:
                attempt_sharpnest = attempt
                print(f'--Update attempt_sharpnest to {attempt}')
        last_sharpness = current_sharpness # Update the last sharpness.
        
    #[20] Return the z position with maximum sharpness.
    idx_sharpnest = np.argmax(list_sharpness)
    max_sharpnest = list_sharpness[idx_sharpnest]
    print(f'\nMaximum sharpness happened at {idx_sharpnest} attempt with max_sharpness of {max_sharpnest}.\n')
    
    #[22] Move to max after
    if move_to_sharpest:
        print('--Move back to sharpest z coordinate.')
        #[23] Calculate steps to take.
        steps_to_sharpnest = total_attempts - idx_sharpnest
        
        #[24] Start taking steps back to sharpnest.
        for step in range(steps_to_sharpnest):
            if Z_direction == 'O_up_100um':
                ser.write('R\n'.encode())
                Z_coord_um -= 100
            elif Z_direction == 'R_down_100um':
                ser.write('O\n'.encode())
                Z_coord_um += 100
            elif Z_direction == 'I_up_10um':
                ser.write('L\n'.encode())
                Z_coord_um -= 10
            elif Z_direction == 'L_down_10um':
                ser.write('I\n'.encode())
                Z_coord_um += 10
            elif Z_direction == 'C_up_2.5um':
                ser.write('F\n'.encode())
                Z_coord_um -= 10
            elif Z_direction == 'F_down_2.5um':
                ser.write('C\n'.encode())
                Z_coord_um += 10
            else:
                raise ValueError(f'Invalide Z_direction setting: {Z_direction}. Please check.')
            #[13] Report Z_coord_um.
            print(f'--Z_coord_um = {Z_coord_um} um.')
            time.sleep(0.5)
            
        #[26] Last sharpness test.
        time.sleep(2)   # Keep 2 seconds.
        current_sharpness = capture_and_save(capture, sharpness_method, dir_save, text_capture, len(list_sharpness), Z_coord_um)
        
        #[8] Record sharpness
        print(f'\n[Attempt {attempt}] sharpness: {round(current_sharpness, 3)}')
        list_sharpness.append(current_sharpness)
        list_Z_coord_um.append(Z_coord_um)
    
    
    return (Z_coord_um, list_Z_coord_um, list_sharpness)



def move_to_starting_point(ser_arduino, z_scan_start_um, Z_coord_um):
    print('\n[move_to_starting_point]')
    #[1] 1000 range
    if z_scan_start_um >= 1000:
        print(f'z_scan_start_um {z_scan_start_um} >= 1000')
        step_Z_up = round(z_scan_start_um/1000) # Remember to divided by 1000.
        for i in range(step_Z_up):
            ser_arduino.write('U\n'.encode())
            Z_coord_um += 1000
            print(f'--Z_coord_um = {Z_coord_um} um.')
            time.sleep(0.5)
          
    elif z_scan_start_um <= -1000:
        print(f'z_scan_start_um {z_scan_start_um} <= -1000')
        step_Z_up = round(abs(z_scan_start_um)/1000)
        for i in range(step_Z_up):
            ser_arduino.write('X\n'.encode())
            Z_coord_um -= 1000
            print(f'--Z_coord_um = {Z_coord_um} um.')
            time.sleep(0.5)
    
    #[2] 100 range
    elif z_scan_start_um >= 100:
        print(f'z_scan_start_um {z_scan_start_um} >= 100')
        step_Z_up = round(z_scan_start_um)/100
        for i in range(step_Z_up):
            ser_arduino.write('O\n'.encode())
            Z_coord_um += 100
            print(f'--Z_coord_um = {Z_coord_um} um.')
            time.sleep(0.5)
          
    elif z_scan_start_um <= -100:
        print(f'z_scan_start_um {z_scan_start_um} <= -100')
        step_Z_up = round(abs(z_scan_start_um)/100)
        for i in range(step_Z_up):
            ser_arduino.write('R\n'.encode())
            Z_coord_um -= 100
            print(f'--Z_coord_um = {Z_coord_um} um.')
            time.sleep(0.5)
    
    #[3] 10 range
    elif z_scan_start_um >= 10:
        print(f'z_scan_start_um {z_scan_start_um} >= 10')
        step_Z_up = round(z_scan_start_um)/10
        for i in range(step_Z_up):
            ser_arduino.write('I\n'.encode())
            Z_coord_um += 10
            print(f'--Z_coord_um = {Z_coord_um} um.')
            time.sleep(0.5)
          
    elif z_scan_start_um <= -10:
        print(f'z_scan_start_um {z_scan_start_um} <= -10')
        step_Z_up = round(abs(z_scan_start_um)/10)
        for i in range(step_Z_up):
            ser_arduino.write('L\n'.encode())
            Z_coord_um -= 10
            print(f'--Z_coord_um = {Z_coord_um} um.')
            time.sleep(0.5)   
    return Z_coord_um



def start_streaming_for_auto_focus_move_up_only(XYZ_coord_um, 
                                                z_scan_start_um, 
                                                sharpness_method, 
                                                dir_save, 
                                                text_capture, 
                                                Z_direction, 
                                                cam_idx,
                                                total_attempts):
    
    #[1] Initialization
    X_coord_um, Y_coord_um, Z_coord_um = XYZ_coord_um
    move_to_sharpest = True
    
    #[2] Check if directory exist.
    try:
        os.mkdir(dir_save)
        print(f'--Directory was not exists. Just made one. {dir_save}')
    except FileExistsError:
        print('--Directory already exists. Skipping directory creation.')
    
    #[3] Set up serial communication.
    ser_arduino = serial.Serial('COM3', 9600, timeout=2)
    time.sleep(2)
    capture = cv2.VideoCapture(cam_idx)
    if not capture.isOpened():
        print("Error: Couldn't open the camera.")
        return
    
    #[5] Move to starting point.
    Z_coord_um = move_to_starting_point(ser_arduino, z_scan_start_um, Z_coord_um)

    #[6] Main stepwise_sharpness_recording
    (Z_coord_um, list_Z_coord_um, list_sharpness) = stepwise_sharpness_recording(capture, ser_arduino, sharpness_method, dir_save, text_capture, Z_direction, total_attempts, Z_coord_um, move_to_sharpest)
    XYZ_coord_um = X_coord_um, Y_coord_um, Z_coord_um
    
    return XYZ_coord_um, list_sharpness, list_Z_coord_um



def plot_auto_focus_result(list_at_X, list_Z_um_at_Y, list_title_x_y, path_save):
    #[1] Plot settings
    plt.figure(figsize=(10, 8))
    fs_title = 22
    fs_axis = 18
    fs_tick = 16
    
    #[3] Normalize epoch from 0 to 1 for viridis color bar.
