def capture_image(dir_captured_images, image_name):
    path_capture_image = os.path.join(dir_captured_images, image_name + '.png')
    
    # Open the second camera. 0 means first, usually is the front camera; 1 means second, usually the external camera.
    cap = cv2.VideoCapture(1)
    
    if not cap.isOpened():
        print("Error: Couldn't open the camera.")
        return

    # Read a frame from the camera. 
    # ret will be True if the frame was successfully captured, otherwise False.
    ret, frame = cap.read()

    if not ret:
        print("Error: Couldn't capture an image.")
        return

    # Save the captured frame to a file
    cv2.imwrite(path_capture_image, frame)

    # Release the camera device
    cap.release()
    
