import cv2, os, datetime


def stream_camera(camera_number, dir_captured):
    print('\n[stream_camera]')
    capture = cv2.VideoCapture(camera_number)
    if not capture.isOpened():
        print("Error: Couldn't open the camera.")
        return
    while True:
        ret, frame = capture.read()
        if not ret:
            print("Error: Couldn't capture a frame.")
            break
        # Call cv2.waitKey(1) every time after cv2.imshow to give the window a chance to refresh and display the image.
        cv2.imshow('Camera Stream', frame)
        cv2.waitKey(1)
        if cv2.waitKey(1) & 0xFF in (ord('C'), ord('c')):
            path_capture_image = os.path.join(dir_captured, datetime_tag() + '.png')
            cv2.imwrite(path_capture_image, frame)
            print(f'Captured image saved at {path_capture_image}')
        if cv2.waitKey(1) & 0xFF in (ord('Q'), ord('q')):
            break
    capture.release()
    cv2.destroyAllWindows()

def datetime_tag():
    # Get current date and time.
    now = datetime.datetime.now()
    current_date = now.strftime("%Y-%m-%d")
    current_time = now.strftime("%H-%M-%S")
    current_datetime = current_date + '_' + current_time
    return current_datetime


