def comm_check_if(message):
    global X_coord, Y_coord, Z_coord, serial_status
    if serial_status == 0:
        ser = serial.Serial('COM3', 9600, timeout=2)
        time.sleep(2) 
        print('Serial opened.')
        serial_status = 1
        time.sleep(2)      # 1s is too short. 2s is good.
    elif serial_status == 1:
        print('Serial already opened.')
    else:
        print('Serial status unknown.')
    
    try:
        message = message + '\n'
        ser.write(message.encode())
    
    except KeyboardInterrupt:
        print("Serial communication stopped.")
        
    """finally:
        ser.close()  # Close the serial connection when done"""
    
    if response == '':
        print('No message received.')
    else: 
        XYZ_coordinate = response.split(' ')[1]
        X_coord = XYZ_coordinate.split(',')[0]
        Y_coord = XYZ_coordinate.split(',')[1]
        Z_coord = XYZ_coordinate.split(',')[2]
        print('X_coord: ', X_coord, '; Y_coord: ', Y_coord, '; Z_coord: ', Z_coord, sep='')



def serial_to_Arduino(message):
    global X_coord, Y_coord, Z_coord
    ser = serial.Serial('COM3', 9600, timeout=2)
    time.sleep(2) 
    print('Serial opened. Wait for 2 seconds.')
    time.sleep(2)      # 1s is too short. 2s is good.
    try:
        # Send the value "3" to the Arduino
        message = message + '\n' # Add new line symbol to mark the end of the message. 
        ser.write(message.encode())
        print('Sent message "', message, '" to Arduino through', 'COM3')
        # Wait for Arduino's response
        response = ser.readline().decode().strip()  # Read the response until a newline character
        # Print the received response
        print("Received response from Arduino:", response)  
    except KeyboardInterrupt:
        print("Serial communication stopped.")
    finally:
        ser.close()  # Close the serial connection when done
    if response == '':
        print('No message received.')
    else: # Organize respond coordinate update string into values for XYZ.
        XYZ_coordinate = response.split(' ')[1]
        X_coord = XYZ_coordinate.split(',')[0]
        Y_coord = XYZ_coordinate.split(',')[1]
        Z_coord = XYZ_coordinate.split(',')[2]
        print('X_coord: ', X_coord, '; Y_coord: ', Y_coord, '; Z_coord: ', Z_coord, sep='')


