def capture_image(frame, dir_captured_images): 
    # Get current date and time.
    now = datetime.datetime.now()
    current_date = now.strftime("%Y-%m-%d")
    current_time = now.strftime("%H%M%S")
    current_datetime = current_date + '_' + current_time
    filename = f"{current_datetime}.png"  # This will generate names like '2023-09-01_101530.jpg'
    path = f"{dir_captured_images}\\{filename}"
    
    cv2.imwrite(path, frame)
    print(f"Saved frame as {path}")



def calculate_blur_metric(frame):
    #frame = np.asarray(frame)
    gray_image = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    blur_metric = round(cv2.Laplacian(gray_image, cv2.CV_64F).var(),0)
    print('blur_metric_1:', blur_metric)
    return blur_metric



def stream_movement_capture(dir_captured_images):
    global X_coord_mm, Y_coord_mm, Z_coord_mm
    #[] Open serial port
    ser = serial.Serial('COM3', 9600, timeout=2)
    time.sleep(2) 
    print('Serial opened. Wait for 2 seconds.')
    time.sleep(2)  
    
    print('Opening VideoCapture. Wait for about 10 seconds.')
    capture = cv2.VideoCapture(1) # Open the first camera device

    if not capture.isOpened():
        print("Error: Couldn't open the camera.")
        return

    while True:
        ret, frame = capture.read() # Capture frame-by-frame
        if not ret:
            print("Error: Couldn't capture a frame.")
            break

        cv2.imshow('Camera Stream', frame) # Display the resulting frame
        key = cv2.waitKey(1) & 0xFF
        
        if key == ord('='): #[] Capture the frame if '=' is pressed
            capture_image(frame, dir_captured_images)
            calculate_blur_metric(frame)

        elif key == ord('A'):
            try: #[] Move X right(+) for 2.5 um.
                message = 'A' + '\n'
                ser.write(message.encode())
                X_coord_mm = X_coord_mm + 0.0025
                print('Moved X right(+) for 2.5 um. X_coord_mm =', "%0.4f" %X_coord_mm)
            except KeyboardInterrupt:
                print("Serial communication stopped.")
        
        elif key == ord('B'):
            try: #[] Move Y forward(+) for 2.5 um.
                message = 'B' + '\n'
                ser.write(message.encode())
                Y_coord_mm = Y_coord_mm + 0.0025
                print('Moved Y right(+) for 2.5 um. Y_coord_mm =', "%0.4f" %Y_coord_mm)
            except KeyboardInterrupt:
                print("Serial communication stopped.")
        
        elif key == ord('C'):
            try: #[] Move Z up(+) for 2.5 um.
                message = 'C' + '\n'
                ser.write(message.encode())
                Z_coord_mm = Z_coord_mm + 0.0025
                print('Moved Z down(+) for 2.5 um. Z_coord_mm =', "%0.4f" %Z_coord_mm)
            except KeyboardInterrupt:
                print("Serial communication stopped.")
        
        elif key == ord('D'):
            try: #[] Move X left(-) for 2.5 um.
                message = 'D' + '\n'
                ser.write(message.encode())
                X_coord_mm = X_coord_mm - 0.0025
                print('Moved X left(-) for 2.5 um. X_coord_mm =', "%0.4f" %X_coord_mm)
            except KeyboardInterrupt:
                print("Serial communication stopped.")
        
        elif key == ord('E'):
            try: #[] Move Y back(-) for 2.5 um.
                message = 'E' + '\n'
                ser.write(message.encode())
                Y_coord_mm = Y_coord_mm - 0.0025
                print('Moved Y back(-) for 2.5 um. Y_coord_mm =', "%0.4f" %Y_coord_mm)
            except KeyboardInterrupt:
                print("Serial communication stopped.")
        
        elif key == ord('F'):
            try: #[] Move Z down(-) for 2.5 um.
                message = 'F' + '\n'
                ser.write(message.encode())
                Z_coord_mm = Z_coord_mm - 0.0025
                print('Moved Z down(-) for 2.5 um. Z_coord_mm =', "%0.4f" %Z_coord_mm)
            except KeyboardInterrupt:
                print("Serial communication stopped.")
        
        
        
        elif key == ord('G'):
            try: #[] Move X right(+) for 25 um.
                message = 'G' + '\n'
                ser.write(message.encode())
                X_coord_mm = X_coord_mm + 0.025
                print('Moved X right(+) for 25 um. X_coord_mm =', "%0.4f" %X_coord_mm)
            except KeyboardInterrupt:
                print("Serial communication stopped.")
        
        elif key == ord('H'):
            try: #[] Move Y forward(+) for 25 um.
                message = 'H' + '\n'
                ser.write(message.encode())
                Y_coord_mm = Y_coord_mm + 0.025
                print('Moved Y right(+) for 25 um. Y_coord_mm =', "%0.4f" %Y_coord_mm)
            except KeyboardInterrupt:
                print("Serial communication stopped.")
        
        elif key == ord('I'):
            try: #[] Move Z up(+) for 25 um.
                message = 'I' + '\n'
                ser.write(message.encode())
                Z_coord_mm = Z_coord_mm + 0.025
                print('Moved Z down(+) for 25 um. Z_coord_mm =', "%0.4f" %Z_coord_mm)
            except KeyboardInterrupt:
                print("Serial communication stopped.")
        
        elif key == ord('J'):
            try: #[] Move X left(-) for 25 um.
                message = 'J' + '\n'
                ser.write(message.encode())
                X_coord_mm = X_coord_mm - 0.025
                print('Moved X left(-) for 25 um. X_coord_mm =', "%0.4f" %X_coord_mm)
            except KeyboardInterrupt:
                print("Serial communication stopped.")
        
        elif key == ord('K'):
            try: #[] Move Y back(-) for 25 um.
                message = 'K' + '\n'
                ser.write(message.encode())
                Y_coord_mm = Y_coord_mm - 0.025
                print('Moved Y back(-) for 25 um. Y_coord_mm =', "%0.4f" %Y_coord_mm)
            except KeyboardInterrupt:
                print("Serial communication stopped.")
        
        elif key == ord('L'):
            try: #[] Move Z down(-) for 25 um.
                message = 'L' + '\n'
                ser.write(message.encode())
                Z_coord_mm = Z_coord_mm - 0.025
                print('Moved Z down(-) for 25 um. Z_coord_mm =', "%0.4f" %Z_coord_mm)
            except KeyboardInterrupt:
                print("Serial communication stopped.")

        
        

        
  
        
        
        
        
        
        
        
        # Break the loop if 'q' is pressed
        elif key == ord('-'):
            ser.close()  # Close the serial connection when done
            break









    # Release the camera and close all windows
    capture.release()
    cv2.destroyAllWindows()




    

def auto_focus(trail, capture):
    global X_coord, Y_coord, Z_coord
    #[] Capture first image and calculate blur metric.
    ret, frame = capture.read()
    blur_metric_1 = calculate_blur_metric(frame)
    #[] Move up by 2.5 um.
    ser = serial.Serial('COM3', 9600, timeout=1)
    serial_to_Arduino('C') # "C" is the switch-case commend for Arduino to move the linear stage up by 2.5 um.
    print('Serial Sent: Move up by 2.5 um..')
    time.sleep(2)  
    #[] Capture second image and calculate blur metric.
    ret, frame = capture.read()
    blur_metric_2 = calculate_blur_metric(frame)
    if blur_metric_1 < blur_metric_2: # Move up gets more blur.
        for trail in (1, trail):
            #[] Move down by 2.5 um.
            serial_to_Arduino('D')
            #[] Capture  image and calculate blur metric.
            ret, frame = capture.read()
            blur_metric_1 = calculate_blur_metric(frame)
            print('blur_metric_1: ', blur_metric_1)
            
    elif blur_metric_1 > blur_metric_2:
        for trail in (1, trail):
            #[] Move up by 2.5 um.
            ser = serial.Serial('COM3', 9600, timeout=1)
            serial_to_Arduino('C')
            #[] Capture  image and calculate blur metric.
            ret, frame = capture.read()
            blur_metric_1 = calculate_blur_metric(frame)
            print('blur_metric_1: ', blur_metric_1)
    else:
        print('Perfect focus!')
            
    

















