import numpy as np
import sys
import matplotlib.pyplot as plt
import random
sys.path.append(r'D:\01_Floor\a_Ed\16_Coding\03_Python\00_Classes and Functions')
# Classes and functions are stored in this directory.
import F02_File as F02_File #type: ignore

sys.path.append(r'D:\01_Floor\a_Ed\16_Coding\03_Python\00_Classes and Functions')
# Classes and functions are stored in this directory.
import C04_PixelStatistics as C04_PixelStatistics #type: ignore


def points_on_sphere(center_xyz, r, theta_180deg_space, phi_360deg_space):
    list_sphere_x = []
    list_sphere_y = []
    list_sphere_z = []
    list_sphere_theta_deg = []
    list_sphere_phi_deg = []
    
    list_sphere_theta_deg = np.linspace(0, 180, theta_180deg_space)
    list_sphere_phi_deg = np.linspace(0, 360, phi_360deg_space)
    for iter_theta in list_sphere_theta_deg:
        for iter_phi in list_sphere_phi_deg:
            list_sphere_x.append(center_xyz[0] + r*np.sin(iter_theta)*np.cos(iter_phi))
            list_sphere_y.append(center_xyz[1] + r*np.sin(iter_theta)*np.sin(iter_phi))
            list_sphere_z.append(center_xyz[2] + r*np.cos(iter_theta))
    return list_sphere_x, list_sphere_y, list_sphere_z
            


# ['max', 'min', 'mean', 'std', 'mean-2std', 'mean+2std']
array_color_stat = np.array([[231, 183, 205,  15, 175, 235],
                            [175, 137, 155,  12, 131, 179],
                            [133,  93, 112,  12,  88, 136]])


mean_point = np.array([205.2795858,  154.75690335, 112.13461538])
line_vector = np.array([0.64965352,  0.54124749,  0.53385528])
dist_to_line = 6 
dist_to_mean = 40
test_mode = 0 # If test_mode = 1, time comsuming steps will be skiped.




#[Cube] Create data points for Cube method.
R_h, R_l = array_color_stat[0][4], array_color_stat[0][5]
G_h, G_l = array_color_stat[1][4], array_color_stat[1][5]
B_h, B_l = array_color_stat[2][4], array_color_stat[2][5]

# Directly convert ranges to lists
list_R = list(range(R_h, R_l + 1))
list_G = list(range(G_h, G_l + 1))
list_B = list(range(B_h, B_l + 1))
print('list_R[:10]:', list_R[:10])
print('list_G[:10]:', list_G[:10])
print('list_B[:10]:', list_B[:10])

# Use list comprehension for cleaner and faster combination of RGB values
list_cube_RGB = []

for iter_B in list_B:
    list_cube_RGB_new = [R_h, G_h, iter_B]
    list_cube_RGB.append(list_cube_RGB_new)
    list_cube_RGB_new = [R_h, G_l, iter_B]
    list_cube_RGB.append(list_cube_RGB_new)
    list_cube_RGB_new = [R_l, G_h, iter_B]
    list_cube_RGB.append(list_cube_RGB_new)
    list_cube_RGB_new = [R_l, G_l, iter_B]
    list_cube_RGB.append(list_cube_RGB_new)
    
for iter_G in list_G:
    list_cube_RGB_new = [R_h, iter_G, B_h]
    list_cube_RGB.append(list_cube_RGB_new)
    list_cube_RGB_new = [R_h, iter_G, B_l]
    list_cube_RGB.append(list_cube_RGB_new)
    list_cube_RGB_new = [R_l, iter_G, B_h]
    list_cube_RGB.append(list_cube_RGB_new)
    list_cube_RGB_new = [R_l, iter_G, B_l]
    list_cube_RGB.append(list_cube_RGB_new)
    
for iter_R in list_R:
    list_cube_RGB_new = [iter_R, G_h, B_h]
    list_cube_RGB.append(list_cube_RGB_new)
    list_cube_RGB_new = [iter_R, G_h, B_l]
    list_cube_RGB.append(list_cube_RGB_new)
    list_cube_RGB_new = [iter_R, G_l, B_h]
    list_cube_RGB.append(list_cube_RGB_new)
    list_cube_RGB_new = [iter_R, G_l, B_l]
    list_cube_RGB.append(list_cube_RGB_new)

list_cube_RGB = np.array(list_cube_RGB)

print('list_cube_RGB[:10]:\n', list_cube_RGB[:10], end='\n')
print()


cube_Rs, cube_Gs, cube_Bs = zip(*list_cube_RGB)     #[CoolCode]
# The line cube_Rs, cube_Gs, cube_Bs = zip(*list_cube_RGB) is 
# unpacking the values from the list_cube_RGB list of list 
# into three separate lists: cube_Rs, cube_Gs, and cube_Bs.






#[Line] 
# Normalize the line vector if it's not already a unit vector
line_vector = line_vector / np.linalg.norm(line_vector)

# Create two vectors perpendicular to line_vector and to each other.
# We can start with any random vector and find a perpendicular vector in the plane.
random_vector = np.random.rand(3)
while np.allclose(random_vector, line_vector) or np.allclose(random_vector, -line_vector):
    random_vector = np.random.rand(3)  # ensure it's not collinear with line_vector

# Use cross product to get a vector perpendicular to both line_vector and random_vector.
perp_vector = np.cross(line_vector, random_vector)
perp_vector /= np.linalg.norm(perp_vector)  # normalize the vector

# Get another perpendicular vector in the plane, perpendicular to both line_vector and perp_vector.
perp_vector2 = np.cross(line_vector, perp_vector)
perp_vector2 /= np.linalg.norm(perp_vector2)  # normalize the vector

# Now, we have a basis for the plane {perp_vector, perp_vector2}.
# We can find points on the circle using these vectors.
num_points = 10
theta = np.linspace(0, 2 * np.pi, num_points)

# Points on the circle
circle_points = np.array([mean_point + dist_to_line * (np.cos(t) * perp_vector + np.sin(t) * perp_vector2) for t in theta])
print('circle_points:\n', circle_points, end='\n')
print()
#[] Generate points along the line defined by line_vector
linepts = line_vector * np.mgrid[0:256:255][:, np.newaxis]
list_line_RGB = []
for iter_circle_points in circle_points:
    #[] Shift by the mean to get the line in the right place
    linepts = np.outer(np.linspace(-50, 50, 50), line_vector)
    linepts += iter_circle_points
    list_line_RGB.append(linepts)
list_line_RGB = np.concatenate(list_line_RGB, axis=0)
print('list_line_RGB.shape', list_line_RGB.shape)
#print('list_line_RGB[:3]\n', list_line_RGB[:3], end='\n')


#[] Remove points on the lines that are too far away.
to_remove = []
for index, iter_RGB_point in enumerate(list_line_RGB):
    test_dist_to_mean = np.linalg.norm(np.array(iter_RGB_point) - mean_point)
    if test_dist_to_mean > dist_to_mean:
        to_remove.append(index)

        
filtered_line_RGB = [point for index, point in enumerate(list_line_RGB) if index not in to_remove]

print('Length after removal:', len(filtered_line_RGB))
line_Rs, line_Gs, line_Bs = np.array(filtered_line_RGB).T
"""print('line_Rs[:10]:', line_Rs[:10])
print('line_Gs[:10]:', line_Gs[:10])
print('line_Bs[:10]:', line_Bs[:10])"""


#[] End cap for the line
list_sphere_x, list_sphere_y, list_sphere_z = points_on_sphere(mean_point, dist_to_mean, 90, 180)
list_sphere_xyz = np.array(list(zip(list_sphere_x, list_sphere_y, list_sphere_z)))
to_remove = []
for index, iter_list_sphere_xyz in enumerate(list_sphere_xyz):
    test_dist_to_line = C04_PixelStatistics.distance_to_line(iter_list_sphere_xyz, mean_point, line_vector)
    if test_dist_to_line > dist_to_line:
        to_remove.append(index)
filtered_list_sphere_xyz = [point for index, point in enumerate(list_sphere_xyz) if index not in to_remove]
print('list_sphere_xyz.shape:', list_sphere_xyz.shape)
print('filtered_list_sphere_xyz.shape:', len(filtered_list_sphere_xyz))
line_cap_Rs, line_cap_Gs, line_cap_Bs = np.array(filtered_list_sphere_xyz).T
    
#[] Generate points along the line defined by line_vector
array_linepts = line_vector * np.mgrid[0:256:255][:, np.newaxis]

#[] Shift by the mean to get the line in the right place
array_linepts = np.outer(np.linspace(-500, 500, 1000), line_vector)
array_linepts += mean_point
centerline_Rs, centerline_Gs, centerline_Bs = np.array(array_linepts).T





#[] Read some data from excel so that we can plot it.
path_excel = r'D:\01_Floor\a_Ed\16_Coding\03_Python\04_OngoingTools\2023-1006_Pixel Statistics\df_color_counts.xlsx'
sheet_name = 'color_counts'
df_pixels = F02_File.read_excel_into_df(path_excel, sheet_name)
df_pixels = df_pixels.sample(frac =0.1) # Only take a fraction of data
pixels_Rs = df_pixels['Red'].values.tolist()
pixels_Gs = df_pixels['Green'].values.tolist()
pixels_Bs = df_pixels['Blue'].values.tolist()



#[Plot] Visulize result
fig = plt.figure(figsize=(8, 5))
alpha_value = 0.5

#[] Figure-1
ax1 = fig.add_subplot(121, projection='3d')
ax1.set_xlim(160, 250)
ax1.set_ylim(110, 200)
ax1.set_zlim(90, 160)
ax1.set_xlabel('red channel')
ax1.set_ylabel('green channel')
ax1.set_zlabel('blue channel')
if test_mode == 1:
    ax1.scatter(cube_Rs, cube_Gs, cube_Bs, color='turquoise', alpha=alpha_value, s=2)
else:
    for i in range(len(cube_Rs)):
        ax1.scatter(cube_Rs[i], cube_Gs[i], cube_Bs[i], 
                    color=(cube_Rs[i]/255., cube_Gs[i]/255., cube_Bs[i]/255.), alpha=alpha_value, s=2)
ax1.scatter(pixels_Rs, pixels_Gs, pixels_Bs, color = "dimgray", alpha=alpha_value, s=2)





#[] Figure-2
ax2 = fig.add_subplot(122, projection='3d')
ax2.set_xlim(160, 250)
ax2.set_ylim(110, 200)
ax2.set_zlim(90, 160)
ax2.set_xlabel('red channel')
ax2.set_ylabel('green channel')
ax2.set_zlabel('blue channel')
if test_mode == 1:
    ax2.scatter(line_Rs, line_Gs, line_Bs, color='turquoise', alpha = alpha_value, s=2)
    ax2.scatter(line_cap_Rs, line_cap_Gs, line_cap_Bs, color='teal', alpha = alpha_value, s=2)
else:
    line_Rs = np.concatenate((line_Rs, line_cap_Rs))
    line_Gs = np.concatenate((line_Gs, line_cap_Gs))
    line_Bs = np.concatenate((line_Bs, line_cap_Bs))
    for i in range(len(line_Rs)):
        ax2.scatter(line_Rs[i], line_Gs[i], line_Bs[i], 
                    color=(line_Rs[i]/255., line_Gs[i]/255., line_Bs[i]/255.), alpha=alpha_value, s=2)
        
ax2.scatter(pixels_Rs, pixels_Gs, pixels_Bs, color = "dimgray", alpha=alpha_value, s=2)
ax2.scatter(centerline_Rs, centerline_Gs, centerline_Bs, color='firebrick', alpha = alpha_value/4, s=2)



plt.show()

