from datetime import datetime

sys.path.insert(1, r'D:\01_Floor\a_Ed\09_EECS\10_Python\00_Classes and Functions')
import F02_File as F02_File # type: ignore
import F09_OMcam as F09_OMcam # type: ignore


def clear_camera_buffer(capture, num_frames_to_clear=5):
    for _ in range(num_frames_to_clear):
        ret, frame = capture.read()
        if not ret:
            print("Failed to grab frame")



    

def check_displacement(capture, ser, frame, direction):
    print('\n[check_displacement]')
    time.sleep(1)  
    #[3] Capture camera image
    print('--[Start camera angle correction]')
    #[3-1] Capture first image.
    timestamp = datetime.now().strftime("%Y-%m%d-%H%M")
    path_capture_image = os.path.join(dir_captured,  f'{timestamp}_{direction}-0.png')
    cv2.imwrite(path_capture_image, frame)
    print(f'--First image captured, saved at {path_capture_image}')
    time.sleep(1)
    #[3-2] Move +X or +Y by 100 um.
    if direction == 'X':
        ser.write('M\n'.encode())
        time.sleep(2)
        clear_camera_buffer(capture)
        print('--Sent "M" to Arduino through serial, moving linear stage toward +X for 100 um.')
    elif direction == 'Y':
        ser.write('N\n'.encode())
        time.sleep(2)
        clear_camera_buffer(capture)
        print('--Sent "N" to Arduino through serial, moving linear stage toward +Y for 100 um.')
    ret, frame = capture.read()
    time.sleep(2)
    #[3-3] Capture second image.
    clear_camera_buffer(capture)
    path_capture_image = os.path.join(dir_captured, f'{timestamp}_{direction}-1.png')
    cv2.imwrite(path_capture_image, frame)
    print(f'--Second image captured, saved at {path_capture_image}')
    #[3-4] Move back.
    if direction == 'X':
        ser.write('P\n'.encode())
        time.sleep(2)
        clear_camera_buffer(capture)
        print('--Sent "P" to Arduino through serial, moving linear stage toward -X for 100 um.')
    elif direction == 'Y':
        ser.write('Q\n'.encode())
        time.sleep(2)
        clear_camera_buffer(capture)
        print('--Sent "Q" to Arduino through serial, moving linear stage toward -Y for 100 um.')
    time.sleep(2)
    #print('--Take a breath for 2 seconds.', end='\n\n')
        

        
def calculate_displacement(dir_img_folder, direction):
    print('\n[calculate_displacement]')
    list_keywords_discard = ['crop', 'enh']
    list_image_name = F02_File.filter_file_with_keywords(dir_img_folder, 
                                                         list_keywords_discard=list_keywords_discard)[1]
    #[2] Sort file with time and get the two most recently created files
    list_image_name.sort(key=lambda file: os.path.getctime(os.path.join(dir_img_folder, file)), reverse=True)
    latest_two_images = list_image_name[:2]
    print(f'\n[latest_two_images]: \n{latest_two_images}\n')
    path_img_t1 = os.path.join(dir_img_folder, latest_two_images[1])
    path_img_t2 = os.path.join(dir_img_folder, latest_two_images[0])

    #[3] Create dataframe
    df_ImgTable = pd.DataFrame()
    table_formate = 'orgtbl'
    df_ImgTable['Image Name'] = latest_two_images
    df_ImgTable['Image Number'] = ('t2', 't1')

    #[4] Size correction and image enhancement.
    path_img_t1, path_img_t2 = F09_OMcam.crop_to_same_size(path_img_t1, path_img_t2)
    clipLimit, tileGridSize = 2, 8
    path_img_t1, path_img_t2 =  F09_OMcam.enhance_image(path_img_t1, clipLimit, tileGridSize, 1),\
                                F09_OMcam.enhance_image(path_img_t2, clipLimit, tileGridSize, 1)
    img_t1, img_t2 = cv2.imread(path_img_t1, 1), cv2.imread(path_img_t2, 1)

    #[5] Detect displacment.
    displacements, key_point_info = F09_OMcam.calculate_displacement_sift(img_t1, img_t2)
    print(f'Displacements (Raster Coordinate): \t{np.ndarray.tolist(displacements)}')

    #[6] Calculate camera correction angle.
    dx, dy = displacements[0], -displacements[1]  # In computer image, +x is right and +y is down.
    print(f'Displacements (Cartesian Coordinate): \t{[dx, dy]}')

    if dx == 0 and dy == 0:         
        print('[Error] I think the stage did not move.')
        return
    elif dx == 0:
        arctan_dy_dx = 90
    else:
        arctan_dy_dx = round(np.rad2deg(np.arctan(dy/dx)))
        """
        Be careful for the math in this part.
        1. All clockwise has been counter-clockwise because microscope is inveted image.
        """
        if direction == 'X':
            if dx >= 0 and dy >= 0 :    # Quadrant I
                print(f'[Quadrant I] Please trun the camera counter-clockwise by { arctan_dy_dx} degrees.')                     #[Case B] (dx,dy) = (1.7, 1), arctan(1/1.7) = 30
                shift_to = 'Q-I'
            elif dx < 0 and dy >= 0 :   # Quadrant II
                print(f'[Quadrant II] Please trun the camera counter-clockwise by {180 + arctan_dy_dx} degrees.')               #[Case C] (dx,dy) = (-1, 1.7), arctan(1.7/-1) = -60
                shift_to = 'Q-II'
            elif dx < 0 and dy < 0 :    # Quadrant III
                print(f'[Quadrant III] Please trun the camera clockwise by {90 + arctan_dy_dx} degrees.')       #[Case D] (dx,dy) = (-1.7, -1), arctan(-1/-1.7) = 30
                shift_to = 'Q-III'
            elif dx >= 0 and dy < 0 :    # Quadrant IV
                print(f'[Quadrant IV] Please trun the camera clockwise by {-arctan_dy_dx} degrees.')            #[Case A] (dx,dy) = (1.7, -1), arctan(-1/1.7) = -30
                shift_to = 'Q-IV'
                
        elif direction == 'Y':
            if dx >= 0 and dy >= 0 :    # Quadrant I
                print(f'[Quadrant I] Please trun the camera clockwise by {90 - arctan_dy_dx} degrees.')         #[Case A] (dx,dy) = (1, 1.7), arctan(1.7/1) = 60
                shift_to = 'Q-I'
            elif dx < 0 and dy >= 0 :   # Quadrant II
                print(f'[Quadrant II] Please trun the camera counter-clockwise by {90 + arctan_dy_dx} degrees.')                #[Case B] (dx,dy) = (-1, 1.7), arctan(1.7/-1) = -60
                shift_to = 'Q-II'
            elif dx < 0 and dy < 0 :    # Quadrant III
                print(f'[Quadrant III] Please trun the camera counter-clockwise by {90 + arctan_dy_dx} degrees.')               #[Case C] (dx,dy) = (-1.7, -1), arctan(-1/-1.7) = 30
                shift_to = 'Q-III'
            elif dx >= 0 and dy < 0 :    # Quadrant IV
                print(f'[Quadrant IV] Please trun the camera clockwise by {90 - arctan_dy_dx} degrees.')        #[Case D] (dx,dy) = (1.7, -1), arctan(-1/1.7) = -30
                shift_to = 'Q-IV'
                
    print(f'--(direction, shift_to, arctan_dy_dx): {direction}, {shift_to}, {arctan_dy_dx}.')
    os.rename(path_img_t2, path_img_t2.replace('-1_', f'-1_{shift_to}_{arctan_dy_dx}deg_'))
    time.sleep(5)
    
    list_keywords_discard = ['enh']
    F02_File.batch_file_relocate(dir_img_folder, list_keywords_discard=list_keywords_discard)
    print('--Take a break for 5 seconds.', end='\n\n')


def start_camera_streaming_for_cam_angle_corr(camera_number, dir_img_folder):
    print('\n[start_camera_streaming]')
    #[1] Open serial port for Arduino first.
    ser = serial.Serial('COM3', 9600, timeout=2)
    time.sleep(2) 
    print('--Serial opened. Wait for 2 seconds.')
    time.sleep(2)  
    print('--Opening VideoCapture. Wait for about 10 seconds.')
    capture = cv2.VideoCapture(camera_number) # Open the first camera device
    if not capture.isOpened():
        print("Error: Couldn't open the camera.")
        return
    while True:
        ret, frame = capture.read()
        if not ret:
            print("Error: Couldn't capture a frame.")
            break
        # Call cv2.waitKey(1) every time after cv2.imshow to give the window a chance to refresh and display the image.
        cv2.imshow('Camera Stream', frame)
        cv2.waitKey(1)
        
        check_displacement(capture, ser, frame, 'X')
        calculate_displacement(dir_img_folder, 'X')
        check_displacement(capture, ser, frame, 'Y')
        calculate_displacement(dir_img_folder, 'Y')
        break

    #[] Release the capture and close windows at the end.
    capture.release()
    cv2.destroyAllWindows()
    ser.close()
    print('--Camera and serial port closed.')
    




