from docx import Document
from docx.shared import Mm, Pt
from datetime import datetime
from bs4 import BeautifulSoup
from urllib.request import Request, urlopen



now = datetime.now()
current_date = now.strftime("%Y-%m-%d")
current_time = now.strftime("%H%M%S")

print("Date =", current_date)
print("Time =", current_time)

# Create Word document, adjust paper size and margin.
document = Document()
section = document.sections[0]
section.page_height = Mm(297)
section.page_width = Mm(210)
section.left_margin = Mm(15)
section.right_margin = Mm(15)
section.top_margin = Mm(15)
section.bottom_margin = Mm(15)
section.header_distance = Mm(10)
section.footer_distance = Mm(10)

# Write cover.
style = document.styles['Normal']
font = style.font
font.name = 'Arial'
font.size = Pt(12)

for i in range(0, 9):
    document.add_paragraph('')

document.add_paragraph('APICS - CPIM Certification Questions').alignment = 1
document.add_paragraph('from test-questions.com').alignment = 1
document.add_paragraph(now.strftime('%Y-%m-%d, %H:%M:%S')).alignment = 1
document.add_page_break()

# Content

# Reset variables.
question_count = 0
answer_count = 0
last_test_num = 62  # Last number should be 62.

# Target url.
for test_num in range(1, last_test_num+1):
    main_url = 'https://www.test-questions.com/apics-cpim-exam-questions-'+str(test_num).zfill(2)+'.php'

    # Let servers identify us.
    hdr = {'User-Agent': 'Mozilla/5.0'}

    # Making the request wuth BeaitifulSoup module
    req_1 = Request(main_url, headers=hdr)
    page_1 = urlopen(req_1)
    soup_1 = BeautifulSoup(page_1, features="html.parser")

    # This prints the whole html text file: print(soup_1)

    # Display the title.
    print('Title:', end = '')
    for titles in soup_1.find_all('title'):
        individual_title = '[' + str(test_num).zfill(2) + '] ' + titles.get_text()
        print(individual_title, end='')
    print(main_url)

    document.add_paragraph(individual_title + '\n' + main_url).alignment = 0

    # Display question list and count.
    for p_elements in soup_1.find_all('p'):
        #print(p_elements)
        for b_elements in p_elements.find_all('b'):
            print('')
            document.add_paragraph('').alignment = 0
            for questions in b_elements.find_all('span', {'class': 'blue'}):
                question_count = question_count + 1
                individual_question = questions.get_text().split('-', 1)[1]
                print(individual_question)
                document.add_paragraph(individual_question).alignment = 0

        # for answers in p_elements.find_all('input', {'type': 'checkbox'}):
        answer_count = 0

        for answers in p_elements.find_all('input', {'type': 'checkbox'}):
            answer_count = answer_count + 1
            question_head = answers.get('name') + '_' + chr(int(answers.get('value')) + 64) + ':'
            print(question_head, end='')
            individual_answer = answers.next_sibling.split(' ', 1)[1]
            print(individual_answer)
            #document.add_paragraph(question_head + individual_answer).alignment = 0
            document.add_paragraph(individual_answer).alignment = 0


    print(question_count, end='\n\n')
    document.add_paragraph('').alignment = 0
    document.add_page_break()







document.save(current_date + '-' + current_time + '_CPIM.docx')
exit()

