# File path: D:\01_Floor\a_Ed\09_EECS\10_Python\03_MatureTools\2020-1212_Web Scrapping\2021-1210_CPIM-Test-Questions\CPIM-6_Webpage-Checkbox.py

"""
CPIM-6_Webpage-Checkbox.py
Purpose: Find questions and choices.
Author: Ed Chen
Date: 2021-1210
"""   

# Import modules.
from bs4 import BeautifulSoup
from urllib.request import Request, urlopen

import time
from selenium import webdriver
from selenium.webdriver.chrome.options import Options  # Maximize window.
from selenium.webdriver.common.action_chains import ActionChains
from selenium.common.exceptions import NoSuchElementException

from random import random
from tabulate import tabulate
import inflect
p = inflect.engine()




# Reset variables.
question_count = 0
answer_count = 0
test_num = 1
last_test_num = 1 # Last number should be 62.
question_num = 1
last_question_num = 10
try_count = 0

# Creates answer matrix and set answers.
w, h = last_question_num + 1, last_test_num + 1
answer_matrix = [[1 for x in range(w)] for y in range(h)]
for i in range(h):
    answer_matrix[i][0] = i
print('\n[Tabulate answer_matrix.]')
print(tabulate(answer_matrix))


# [Loop of Different test_num]
for test_num in range(1, last_test_num + 1):
    test_url = 'https://www.test-questions.com/apics-cpim-exam-questions-'+str(test_num).zfill(2)+'.php'
    print(test_url)

    print('Initial answers for row ' + str(test_num) + ': ' + str(answer_matrix[test_num]))

    options = Options()
    options.add_argument("--start-maximized")
    driver = webdriver.Chrome(executable_path="C:\Python37\Lib\chromedriver", options=options)
    driver.get(test_url)
    time.sleep(1)  # Wait for Chrome to open.

    # [Loop of Different question_num]
    for question_num in range(1, last_question_num + 1):
        html_quest_name = 'quest' + str(question_num)

        print('\nInitial answer (test = ' + str(test_num) +
              ', question = ' + str(html_quest_name) + '): ' + str(answer_matrix[test_num][question_num]))

        try_count = 0
        for i in range(10):
            try_count = try_count + 1
            try:
                # driver.find_element_by_xpath(".//input[@type='checkbox'][@name='quest1'][@value=1]").click()
                # [Find element] This method has 'Not Clickable' issue.
                element = driver.find_element_by_xpath(
                    ".//input[@type='checkbox'][@name='" + html_quest_name +
                    "'][@value='" + str(answer_matrix[test_num][question_num]) + "']")
                # [Scroll]
                time.sleep(0.1 + random())
                location = element.location
                actions = ActionChains(driver)
                actions.move_to_element(element).perform()
                add_scroll = location['y'] - 120 - random() * 10
                driver.execute_script('window.scroll(0, ' + str(add_scroll) + ')')
                # [Click]
                time.sleep(0.1 + random())
                driver.execute_script("arguments[0].click();", element)
                time.sleep(0.1 + random())
                break
            except NoSuchElementException:
                print(p.ordinal(try_count) + ' try missed.')
                time.sleep(1)
        else:
            print(p.ordinal(try_count) + ' try missed.')

    # [Submit test result after finishing all questions.]
    driver.execute_script("window.scrollTo(0, document.body.scrollHeight);")
    element = driver.find_element_by_name('submit')
    driver.execute_script("arguments[0].click();", element)
exit()












