    max_search_date = (date_to_search - timedelta(days=0)).strftime("%#m/%#d/%Y")
    min_search_date = (date_to_search - timedelta(days=30)).strftime("%#m/%#d/%Y")

    print('max_search_date = ', max_search_date, ', min_search_date = ', min_search_date, '.')
    date_range_appendex = ':1,cd_min:' + min_search_date + ',cd_max:' + max_search_date
    date_range_appendex_UTF_8 = '&tbs=cdr' + urllib.parse.quote(date_range_appendex, safe='')
    print(date_range_appendex_UTF_8)
