    # driver = webdriver.Chrome('C:\Python37\Lib\chromedriver', options = option_headless)

    news_count = 0
    page_count = 1
    for page_count in range(1, 3 + 1):
        print("page_count = ", page_count)

        # Print website title.
        driver.get(main_url)
        web_title = driver.title
        web_page = driver.find_element_by_class_name("YyVfkd").text
        print("Website Title: ", web_title)
        print("Website Page: ", web_page)

        # Gathering news titles.
        print("News title list: ")
        #for news_titles in soup_1.find_all('div[class*="mCBkyc y355M"]'):

        for news_titles in driver.find_elements_by_xpath("//div[@role ='heading'][@aria-level = '3']"):
            news_count = news_count + 1
            individual_news_title = str(news_titles.text)
            print("[Title_", str(news_count).zfill(2) + ': ' + individual_news_title, "]")

            # Append datum to dateframe
            datum = {'News Count': news_count
                , 'Max search date': datetime.strptime(max_search_date, "%m/%d/%Y")
                , 'News Title': individual_news_title
                , 'Good-Bad':''}
