"""
SPP-2_Stock-price-to-excel.py
Purpose: Fetch stock price and save to excel
Author: Ed Chen
Date: 2021-1202
"""

import pandas
import pandas_datareader as pdr
import matplotlib.pyplot as plt
from datetime import datetime
import xlsxwriter
import sys


now = datetime.now()
current_date = now.strftime("%Y-%m-%d")
current_time = now.strftime("%H:%M:%S")

print('Date =', current_date, ' | Time =', current_time)

# Determine stock name to retrieve.
taiwan_stock_symbol = '2330.TW' #AAPL, 2330.TW
stock_name = taiwan_stock_symbol.replace('.', '_')
excel_path = sys.path[0] + '\\Stock-Price-Dataframe\\' + stock_name + '.xlsx'
df_stock = pandas.read_excel(excel_path, engine='openpyxl', sheet_name='Sheet1')

start_date = df_stock['Date'].min().strftime("%Y-%m-%d")
end_date = df_stock['Date'].max().strftime("%Y-%m-%d")

print('Stock Name: ' + stock_name)
print('Data Range: from ' + str(start_date) + ' to ' + str(end_date))
print('Data Type: ' + str(type(df_stock)))
print('Excel Path: ' + excel_path)


# Get close price and trade volume.
fig, ax1 = plt.subplots()
ax2 = ax1.twinx()
ax1.plot(df_stock['Close'], color='C0')
ax2.plot(df_stock['Volume'], color='m')

ax1.set_xlabel('Date')
ax1.set_ylabel('Close Price', color='C0')
ax2.set_ylabel('Volume', color='m')

ax1.set_ylim([min(df_stock['Close']*0.8), max(df_stock['Close'])*1.1])
ax2.set_ylim([0, max(df_stock['Volume'])*4])


chart_title = taiwan_stock_symbol + ' Price \n(from ' \
              + start_date \
              + ' to ' + start_date + ')'
plt.title(chart_title)
plt.show()

# End of [SPP-09_Read-datafram-from-excel.py]




