import_IJKLMN = ['illustrate', 'important', 'including', 'indicated', 'information', 'internal', 'intersystem', 'involf', 'involve', 'isbn', 'isolated', 'italiano', 'item', 'jablonski', 'jump', 'labeled', 'language', 'large', 'last', 'learn', 'level', 'license', 'light', 'line', 'link', 'linksedit', 'logged', 'lower', 'lowest', 'magyar', 'main', 'mechanism', 'medium', 'menu', 'mobile', 'molecular', 'molecule', 'more', 'much', 'multiplicity', 'named', 'namespace', 'nature', 'navigation', 'nederland', 'nonprofit', 'nonradiative']
import_OPQRS = ['occur', 'only', 'organization', 'other', 'oxford', 'page', 'paula', 'permanent', 'personal', 'phosphorescence', 'photochemistry', 'photon', 'physic', 'physical', 'physicist', 'policy', 'polish', 'polski', 'portal', 'powered', 'press', 'primer', 'principle', 'printable', 'printexport', 'privacy', 'process', 'project', 'radiative', 'random', 'read', 'recent', 'reference', 'referencesedit', 'registered', 'related', 'relax', 'relaxation', 'representing', 'resonance', 'retrieved', 'search', 'second', 'several', 'short', 'showing', 'singlet', 'site', 'small', 'special', 'spectroscopy', 'spin', 'spinorbit', 'squiggly', 'state', 'statement', 'statistic', 'straight', 'surrounding']
