def pick_blank_filelist (dir_image_folder):
      print('\n[pick_blank_filelist]')
      
      list_images = os.listdir(dir_image_folder)
      list_blank_image_basename = [file for file in list_images if 'blank' in file]
      list_blank_image_fullpath = [os.path.join(dir_image_folder, file) for file in list_blkIMG_basename]

      #[] Count 10X of blank and 50X of blank.
      cnt_10X, cnt_50X = 0, 0
      for iter_basename in list_blank_image_basename:
            if '10X' in iter_basename:
                  cnt_10X +=1
            elif '50X' in iter_basename:
                  cnt_50X +=1
      print('cnt_10X = ', cnt_10X, ', cnt_50X = ', cnt_50X, '.', sep ='')
      #[] Check the count of blanks
      if (cnt_50X == 1 and cnt_10X == 1):
            print('Both blank-50X and blank-10X exist.')
      elif (cnt_50X > 1 or cnt_10X > 1):
            print('More than one 10X or 50X blank detected. Please remove extra blank image. (Program exit.)')
            sys.exit()
      else:
            if (cnt_50X == 1 and cnt_10X == 0):
                  print('Missing blank-10X.')
            elif (cnt_50X == 0 and cnt_10X == 1):
                  print('Missing blank-50X.')
            elif (cnt_50X == 0 and cnt_10X == 0):
                  print('Missing both blank-10X and blank-50X.')
                  print(' If you only have one blank, just duplicate and name it blank_10X and blank_50X. (Program exit.)')
                  sys.exit()
      
      return list_blank_image_fullpath #, cnt_10X, cnt_50X, list_blank_image_basename
      
    

def generate_corrector_mask (path_blank_image, ratio_extend):
      global image_corrector_10X_3D
      global image_corrector_50X_3D
      
     #[] Calculate dimension of blank image.
      image_blank = cv2.imread(path_blank_image)
      blkIMG_basename = os.path.basename(path_blank_image)
      print('blkIMG_basename: ', blkIMG_basename)
      print('Dimension (width, height, channel) =', image_blank.shape)
      h, w, c = image_blank.shape
      h_center = round(h/2)
      h_upper = round(h_center + h*ratio_extend)
      h_lower = round(h_center - h*ratio_extend)
      w_center = round(w/2)
      w_upper = round(w_center + w*ratio_extend)
      w_lower = round(w_center - w*ratio_extend)
      # For example, if Re = 0.05, it means averaging from 0.45 to 0.55 along width and leangth.

      #[] Average the center area of the blank image.
      array1D_center_averaged = (image_blank[h_lower:h_upper,w_lower:w_upper].mean(axis=0).mean(axis=0)).astype(int)
      avg_color_ard_ctr = np.around(array1D_center_averaged)
      print('Averaged color around center (B, G, R) =', avg_color_ard_ctr, end='\n')
      
      #[] Use sampled color to tile a ndarray of unicolor image.
      image_unicolor = np.tile(array1D_center_averaged, (h, w, 1))
      basename_unicolor = 'unicolor.png'
      path_unicolor = os.path.join(dir_image_folder, basename_unicolor)
      cv2.imwrite(path_unicolor, image_unicolor)

      #[] Generate image modifier for color correction.
      image_corrector = image_blank - image_unicolor
      basename_corrector = 'corrector.png'
      path_corrector = os.path.join(dir_image_folder, basename_corrector)
      cv2.imwrite(path_corrector, image_corrector)
      
      #[] Check for type of blank
      if '10X' in blkIMG_basename:
            type_of_blank = '10X'
            image_corrector_10X_3D = image_corrector
            image_corrector_10X_1D = avg_color_ard_ctr
            print('image_corrector_10X:', avg_color_ard_ctr)
      elif '50X' in blkIMG_basename:
            type_of_blank = '50X'
            image_corrector_50X_3D = image_corrector
            image_corrector_50X_1D = avg_color_ard_ctr
            print('image_corrector_50X:', avg_color_ard_ctr)
      else:
            type_of_blank = '??X'
            image_corrector_XX_3D = image_corrector
            image_corrector_XX_1D = avg_color_ard_ctr
            print('image_corrector_XX:', avg_color_ard_ctr)

      print('type_of_blank:', type_of_blank)

      #[] Generate corrected blank image and save
      corrected_blank = image_blank - image_corrector
      filename_corrected_blank = 'corrected-blk-' + type_of_blank + '.png'
      path_corrected_blank = os.path.join(dir_image_folder, filename_corrected_blank)
      cv2.imwrite(path_corrected_blank, corrected_blank)




