"""
[IMT-8_(3D Color Space)]
Purpose: Understant Computer Graphics Coordinate System.
Author: Meng-Chi Ed Chen
Date: 2023-06-06
Reference:
    1.
    2.

Status: Complete.
"""

import sys
import numpy as np
import plotly.graph_objects as go

# Create a grid of RGB values
devide = 64
R, G, B = np.mgrid[0:257:devide, 0:257:devide, 0:257:devide]


R[R == 256] = 255
G[G == 256] = 255
B[B == 256] = 255


#print('R:', R, end='\n\n')
print('R.shape:', R.shape, end='\n\n')
print('G.shape:', G.shape, end='\n\n')
print('B.shape:', B.shape, end='\n\n')


# Normalize to [0, 1] range for color scale
R_norm = R / 255.
G_norm = G / 255.
B_norm = B / 255.

# Create a colors array for plotly
colors = np.zeros(R.shape + (3,))
colors[..., 0] = R_norm
colors[..., 1] = G_norm
colors[..., 2] = B_norm

print('colors: ', colors, end='\n\n')

colors = colors.reshape(-1, 3)

#sys.exit()

#print('\ncolors\n: ', colors)

# Convert to hex colors for plotly
colors_hex = ['#%02x%02x%02x' % (int(r), int(g), int(b)) for r,g,b in 255*colors]

# Prepare the data
data = go.Scatter3d(
    x=R.ravel(),  # Red on X-axis
    y=G.ravel(),  # Green on Y-axis
    z=B.ravel(),  # Blue on Z-axis
    mode='markers',
    marker=dict(
        size = 10,
        color=colors_hex,  # set color to RGB values
        opacity = 1,
    )
)

# Create layout
layout = go.Layout(
    title='RGB Color Space',
    scene=dict(
        xaxis=dict(title='Red'),
        yaxis=dict(title='Green'),
        zaxis=dict(title='Blue'),
    )
)

# Create the figure and add data
fig = go.Figure(data=data, layout=layout)

# Show the figure
fig.show()
