def list_all_file_and_folders_in_dir(dir_folder, first_cnt_files=20):
    try:
        #[1] Check if the directory exists
        if not os.path.isdir(dir_folder):
            raise FileNotFoundError(f"The directory '{dir_folder}' does not exist.")
        
        #[2] List all files and folders in the directory
        list_folder_and_files = os.listdir(dir_folder)
        
        #[3] Limit the number of entries to the first `first_cnt_files`
        limited_list = list_folder_and_files[:first_cnt_files]
        
        #[4] Print each entry on a new line
        cnt = len(limited_list)
        for i, entry in enumerate(limited_list):
            print(f'[{i+1:03d}/{cnt:03d}] \t{entry}')
        
        return limited_list
    
    except Exception as e:
        print(f"Error: {e}")
        

def replace_folders_in_dir_with_complete_string(dir_path, str_old, str_new):
    print(f'\n[replace_folders_with_complete_string] replacing "{str_old}" with "{str_new}".')
    
    #[1] Check if the given directory exists
    if not os.path.exists(dir_path):
        print('--Given dir_path doesn\'t exist. Exit program.')
        sys.exit(1)

    #[2] Iterate over all items in the directory
    for item in os.listdir(dir_path):
        
        #[5] Construct full path
        path_item = os.path.join(dir_path, item)
        
        #[6] Check if it's a directory and contains str_old in its name
        if os.path.isdir(path_item) and str_old in item:
            
            #[7] Construct new folder name
            new_name = item.replace(str_old, str_new)
            new_path = os.path.join(dir_path, new_name)
            
            #[8] Rename the folder
            os.rename(path_item, new_path)
            print(f'Renamed folder {item} to {new_name}')

        
