def replace_file_with_complete_string(list_file_paths, str_old, str_new):
    print(f'\n[replace_with_complete_string] replacing "{str_old}" with "{str_new}".')
    
    #[1] Check if the given directory exists
    for i, iter_path_file in enumerate(list_file_paths):
        dir_name, base_name = os.path.split(iter_path_file)
        new_base_name = base_name.replace(str_old, str_new)
        new_iter_path_file = os.path.join(dir_name, new_base_name)
        
        #[2] Check if the file names are different and if the original file exists
        if base_name != new_base_name and os.path.exists(iter_path_file):
            os.rename(iter_path_file, new_iter_path_file)
            print(f'[{i}] {new_base_name}')


def ask_to_check(str_to_check, message_1, message_2):
    print('\n[ask_to_check_dir]')
    string_ques = input(message_1)
    if ('yes' in string_ques) or ('ye' in string_ques) or ('y' in string_ques) or ('ok' in string_ques) \
        or ('sure' in string_ques) or ('go' in string_ques):
        print('User said yes.', string_ques)
        return str_to_check
    elif ('no' in string_ques) or ('n' in string_ques):
        print('User said no.', string_ques)
        str_to_check_new = ask_for_input(message_2)
        return str_to_check_new
    else:
        print('[Invalid Input] System exit.\n', string_ques)
        sys.exit(1)


