def replace_file_with_start_end(list_file_paths, str_old_start, str_old_end, str_new):
    print('\n[replace_with_start_end]')
    for i, iter_path_file in enumerate(list_file_paths):
        # Escape the special characters in the start and end strings
        str_old_start_escaped = re.escape(str_old_start)  # re.escape can convert '[' into '\['
        str_old_end_escaped = re.escape(str_old_end)
        # Build the regex pattern
        pattern = f'({str_old_start_escaped}.+?{str_old_end_escaped})'
        match = re.search(pattern, iter_path_file)
        if match:
            # Replace the entire matched pattern
            new_iter_path_file = re.sub(pattern, str_new, iter_path_file)
            os.rename(iter_path_file, new_iter_path_file)
            print(f'[{i}] {os.path.basename(new_iter_path_file)}')




# End of [BFR_00_module.py]




