def create_avg_color_for_patches(list_image_paths):
    print('\n[create_avg_color_for_patches]')
    for index, iter_path_image in enumerate(list_image_paths):
        arrimg_patch = cv2.imread(iter_path_image)
        array1D_avg_color = (arrimg_patch.mean(axis=0).mean(axis=0))
        avg_color = np.around(array1D_avg_color, decimals=2)
        str_avg_color = f'[{avg_color[0]},{avg_color[1]},{avg_color[2]}]'
        basename_image = os.path.basename(iter_path_image)
        print(f'\n{index} Averaged color (BGR) of {basename_image} is {str_avg_color}')
        #[] Rename image with it's color value
        new_path_image = iter_path_image.replace('.png', f'_ac{str_avg_color}.png')
        os.rename(iter_path_image, new_path_image)
    return



def extract_BGR_from_filename(str_filename):
    # Escape the special characters in the start and end strings
    str_start, str_end = '_ac[', '].png'
    start_escaped, end_escaped = re.escape(str_start), re.escape(str_end) 
    pattern = f'({start_escaped}.+?{end_escaped})' # Build the regex pattern
    match = re.search(pattern, str_filename)
    array1D_avg_color = None
    if match:
        matched_string = match.group(1)
        matched_string = matched_string.replace('_ac[','').replace('].png','')
        array1D_avg_color = np.array([float(val) for val in matched_string.split(',')])
    return array1D_avg_color


def extract_avg_color_from_list_of_file(list_image_paths):
    print('\n[extract_avg_color_from_filename]')
    list2D_avg_color = []
    list1D_sample_name = []
    array2D_avg_color = None
    for index, iter_path_image in enumerate(list_image_paths):
        iter_sample_name = os.path.basename(iter_path_image).split('_',1)[0]
        list1D_sample_name.append(iter_sample_name)
        array1D_avg_color = extract_BGR_from_filename(iter_path_image)
        list2D_avg_color.append(array1D_avg_color)
        array2D_avg_color = np.array(list2D_avg_color)
        
    print('list1D_sample_name:', list1D_sample_name, end='\n\n')
    return array2D_avg_color, list1D_sample_name


