def extract_BGR_from_filename(str_filename):
    # Escape the special characters in the start and end strings
    str_start, str_end = '_ac[', '].png'
    start_escaped, end_escaped = re.escape(str_start), re.escape(str_end) 
    pattern = f'({start_escaped}.+?{end_escaped})' # Build the regex pattern
    match = re.search(pattern, str_filename)
    array1D_avg_color = None
    if match:
        matched_string = match.group(1)
        matched_string = matched_string.replace('_ac[','').replace('].png','')
        array1D_avg_color = np.array([float(val) for val in matched_string.split(',')])
    return array1D_avg_color


