def df_two_col_of_list_subtract(list2D_col_big, list2D_col_small, decimals=2):
    list2D_result = []  # Initialize an empty 2D list for the result
    # Iterate over pairs of sublists from list2D_col_big and list2D_col_small
    for list1D_big, list1D_small in zip(list2D_col_big, list2D_col_small):
        list1D_temp = []  # Temporary 1D list to store the result of subtraction for each pair of sublists
        # Iterate over pairs of elements from the current pair of 1D sublists
        for m, c in zip(list1D_big, list1D_small):
            diff = round(m - c, decimals)  # Perform the subtraction and round it
            list1D_temp.append(diff)  # Append the result to the temporary 1D list
        list2D_result.append(list1D_temp)  # Append the temporary 1D list to the final 2D result list
    return list2D_result


