def extract_sample_temp_from_basename(basename):
    """
    Extracts temperature from the filename.
    For example, "02_176-Deg-C.png" to "176", and "03_204-Deg-C.png" to "204".
    """
    # Simplified pattern matching for the temperature
    pattern = r'_(\d+)-Deg-C'
    match = re.search(pattern, basename)
    if match:
        return int(match.group(1))
    else:
        return None



