import os, sys, cv2, re
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from datetime import datetime


def generate_square_wave(period, amplitude, start, end, sample_density):
    num_samples = sample_density * int(end - start)
    t = np.linspace(start, end, num_samples, endpoint=False)
    square_wave = np.sign(np.sin(2 * np.pi * t / period)) * amplitude
    df = pd.DataFrame({'X': t, 'Y': square_wave})
    return df

def fourier_transform(df_signal):
    signal = df_signal['Y'].values
    ft = np.fft.fft(signal)
    freq = np.fft.fftfreq(len(signal))
    df_ft = pd.DataFrame({'X': freq, 'Y': ft})
    return df_ft

def plot_results(df_signal, df_ft, text, dir, basename):
    fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(15, 6))
    
    ax1.plot(df_signal['X'], df_signal['Y'])
    ax1.set_xlabel('Time')
    ax1.set_ylabel('Amplitude')
    ax1.set_title('Square Wave')

    ax2.plot(df_ft['X'], np.abs(df_ft['Y']))
    ax2.set_xlabel('Frequency')
    ax2.set_xlim([0, 0.1])
    ax2.set_ylabel('Magnitude')
    ax2.set_title('Fourier Transform')

    add_text_to_matplotlib_figure(fig, text, start_x=0.1, start_y=0.9, line_spacing=0.05,
                                    font_scale=12, font_color=(13/255, 130/255, 240/255), thickness=2)

    plt.tight_layout()
    path_fig = os.path.join(dir, basename)
    plt.savefig(path_fig)


def add_text_to_matplotlib_figure(fig, text, start_x, start_y, line_spacing, font_scale, font_color, thickness):
    list_text = text.split('\n')
    for i, line in enumerate(list_text):
        fig.text(start_x, start_y - i * line_spacing, line, fontsize=font_scale, color=font_color, fontweight='bold')




