import os, sys, cv2, re
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from datetime import datetime


def generate_siz_pulse_reflected_wave(period, amplitude, start, end, sample_density):
    num_samples = sample_density * int(end - start)
    t = np.linspace(start, end, num_samples, endpoint=False)
    freq = 1/period
    sin_1 = np.sin(np.pi * freq * t)
    sin_2 = np.sin(np.pi * freq * t - 2*np.pi/3)
    sin_3 = np.sin(np.pi * freq * t - 4*np.pi/3)
    reflected_wave = amplitude * (abs(sin_1) + abs(sin_2) + abs(sin_3))
    df = pd.DataFrame({'X': t, 'Y': reflected_wave})
    return df

def fourier_transform(df_signal, sampling_rate):
    signal = df_signal['Y'].values
    ft = np.fft.fft(signal)
    n = len(signal)
    # Assuming sampling_rate is passed correctly to reflect the actual sampling rate of the signal
    freq = np.fft.fftfreq(n, d=1./sampling_rate)
    df_ft = pd.DataFrame({'X': freq, 'Y': ft})
    return df_ft



