import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from datetime import datetime
from sklearn.linear_model import LinearRegression
from tabulate import tabulate
from scipy.optimize import minimize




def generate_signal(period, delta, gamma, start, end, sample_density):
    num_samples = sample_density * int(end - start)
    t = np.linspace(start, end, num_samples, endpoint=False)
    freq = 1/period
    omega_t = 2 * np.pi * freq * t  # Calculate ωt for the entire array
    
    # Apply the condition to each element using numpy.where
    condition = ((delta             < omega_t % (2*np.pi))      & (omega_t % (2*np.pi)      < np.pi/2 - gamma))     | \
                ((np.pi/2 + gamma   < omega_t % (2*np.pi))      & (omega_t % (2*np.pi)      < np.pi - delta))       | \
                ((np.pi + delta     < omega_t % (2*np.pi))      & (omega_t % (2*np.pi)      < 3*np.pi/2 - gamma))   | \
                ((3*np.pi/2 + gamma < omega_t % (2*np.pi))      & (omega_t % (2*np.pi)      < 2*np.pi-delta))
    
    reflected_wave = np.where(condition, np.sign(np.sin(omega_t)), 0)
    #reflected_wave = np.sin(omega_t)   # Use the sine wave to check the 1, \pi, or 2\pi problem.
    df = pd.DataFrame({'X': t, 'Y': reflected_wave})
    return df

def fourier_transform(df_signal, sampling_rate):
    signal = df_signal['Y'].values
    ft = np.fft.fft(signal)
    n = len(signal)
    freq = np.fft.fftfreq(n, d=1./sampling_rate)
    amp = np.abs(ft)
    df_ft = pd.DataFrame({'Freq': freq, 'FT': ft, 'Amp': amp})
    return df_ft

def save_df_as_excel_overwrite(df, dir_excel, bsn_excel, sheet_name):
    print('\n[save_df_as_excel_overwrite]')
    if not os.path.exists(dir_excel):
        os.makedirs(dir_excel)
    path_excel = os.path.join(dir_excel, bsn_excel)
    # Use ExcelWriter in a context manager (with statement)
    with pd.ExcelWriter(path_excel, engine='xlsxwriter') as writer:
        df.to_excel(writer, sheet_name=sheet_name, index=True)
    print(f'--Dataframe saved to {path_excel} in sheet {sheet_name}', end='\n\n')

def plot_results(df_signal, df_ft, text, dir, basename):
    fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(10, 6))
    
    ax1.plot(df_signal['X'], df_signal['Y'])
    ax1.set_xlabel('Time')
    ax1.set_xticks(range(int(min(df_signal['X'])), int(max(df_signal['X'])) + 1))
    ax1.set_ylabel('Amplitude')
    ax1.set_ylim([-1.5, 1.5])
    ax1.set_title('Square Wave')
    # Draw reference lines
    ax1.axhline(y=0, color='black', linestyle='-', linewidth=0.5)
    ax1.axvline(x=0, color='red', linestyle='--', linewidth=0.5)
    ax1.axvline(x=1, color='red', linestyle='--', linewidth=0.5)
    
    ax2.plot(df_ft['Freq'], df_ft['Amp'])
    ax2.set_xlabel('Frequency')
    x2_min, x2_max = 0, 10
    ax2.set_xlim([x2_min, x2_max])
    y_max = int(max(df_ft['Amp']))*1.2
    ax2.set_ylim([0, y_max])
    ax2.set_xticks(np.arange(x2_min, x2_max + 1 , 1))
    ax2.set_ylabel('Magnitude')
    ax2.set_title('Fourier Transform')
    # Draw vertical line
    ax2.axvline(x=1, color='red', linestyle='--', linewidth=0.5)

    add_text_to_matplotlib_figure(fig, text, start_x=0.65, start_y=0.42, line_spacing=0.035,
                                    font_scale=10, font_color=(13/255, 130/255, 240/255), thickness=2)

    plt.tight_layout()
    path_fig = os.path.join(dir, basename)
    plt.savefig(path_fig)


def add_text_to_matplotlib_figure(fig, text, start_x, start_y, line_spacing, font_scale, font_color, thickness):
    list_text = text.split('\n')
    for i, line in enumerate(list_text):
        fig.text(start_x, start_y - i * line_spacing, line, fontsize=font_scale, color=font_color, fontfamily='monospace', fontweight='bold')


def pick_data_with_col2_larger_than_value(df, column_name, v_min, v_max):
    max_a, avg_a, min_a = int(df[column_name].max()), int(df[column_name].mean()), int(df[column_name].min())
    print(f'(max_a, avg_a, min_a) = {max_a:.2f}, {avg_a:.2f}, {min_a:.2f}')
    df_filtered = df.loc[(df[column_name] < v_min) | (df[column_name] > v_max)]
    return df_filtered

def objective_function(params):
    delta, gamma = params
    # Generate the signal and perform Fourier transform for the given delta and gamma
    df_signal = generate_signal(period, delta, gamma, start, end, sample_density)
    df_ft = fourier_transform(df_signal, sampling_rate=sample_density)
    df_ft = df_ft.iloc[1:].reset_index(drop=True)
    
    # Get the amplitudes of the 3rd and 5th harmonics
    amp_3rd_harmonic = df_ft[df_ft['Freq'] == 3]['Amp'].values[0]
    amp_5th_harmonic = df_ft[df_ft['Freq'] == 5]['Amp'].values[0]
    
    # Return the sum of the amplitudes (you can adjust this based on your optimization criteria)
    return amp_3rd_harmonic + amp_5th_harmonic



dir = r'D:\01_Floor\a_Ed\09_EECS\10_Python\04_OngoingTools\2024-0320_Fourier Transform'


#[1] Set the range of delta and gamma values to explore
arr_delta_values = np.linspace(0, np.pi/2-0.02, 20)    # 0.01 rad x 180/pi = 0.573 degree
arr_gamma_values = np.linspace(0, np.pi/2-0.02, 20)
print(f'[arr_delta_values]:\n{arr_delta_values}')
print(f'[arr_gamma_values]:\n{arr_gamma_values}')


#[2] Set valuse
period = 1
start, end = -3 * period , 3 * period
sample_density = 1000


#[2] Create empty lists to store the results
results = []

#[3] Iterate over different combinations of delta and gamma
for cnt_delta, iter_delta in enumerate(arr_delta_values):
    print(f'[{cnt_delta}] delta: {iter_delta}')
    for cnt_gamma, iter_gamma in  enumerate(arr_gamma_values):
        if iter_delta + iter_gamma >= np.pi/2:
            continue
        print(f'--[{cnt_gamma}] gamma: {iter_gamma}')
        # Generate the signal and perform Fourier transform
        df_signal = generate_signal(period, iter_delta, iter_gamma, start, end, sample_density)
        df_ft = fourier_transform(df_signal, sampling_rate = sample_density)
        df_ft = df_ft.iloc[1:].reset_index(drop=True)

        # Filter the data to get the amplitudes of the 3rd and 5th harmonics

        amp_3rd_harmonic = df_ft[df_ft['Freq'] == 3]['Amp'].values[0]
        amp_5th_harmonic = df_ft[df_ft['Freq'] == 5]['Amp'].values[0]
        print(f'----[{cnt_gamma}] delta, 3rd_harmonic, 5th_harmonic: {iter_gamma}, {amp_3rd_harmonic}, {amp_5th_harmonic}')

        # Append the results to the list
        results.append([iter_delta, iter_gamma, amp_3rd_harmonic, amp_5th_harmonic])
    

# Convert the results to a DataFrame
df_results = pd.DataFrame(results, columns=['delta', 'gamma', 'amp_3rd_harmonic', 'amp_5th_harmonic'])
bsn_excel = f'3_Result.xlsx'
save_df_as_excel_overwrite(df_results, dir, bsn_excel, 'OPT')


# Define the bounds for delta and gamma (between 0 and np.pi/2)
bounds = [(0, np.pi/2), (0, np.pi/2)]

# Perform the optimization
result = minimize(objective_function, x0=[0, 0], bounds=bounds)

# Extract the optimal delta and gamma values
optimal_delta, optimal_gamma = result.x

print(f'Optimal delta: {optimal_delta}')
