class TruncatedTriangleDataset(Dataset):
    def __init__(self, image_dir, transform=None):
        self.image_dir = image_dir
        self.transform = transform
        self.image_files = [f for f in os.listdir(image_dir) if f.endswith('.png')]
        self.truncate_ratios = [M1SG.recover_generation_info_from_filename(f)[0] for f in self.image_files]

    def __len__(self):
        return len(self.image_files)

    def __getitem__(self, idx):
        img_name = os.path.join(self.image_dir, self.image_files[idx])
        image = Image.open(img_name).convert('L')  # Convert to grayscale
        if self.transform:
            image = self.transform(image)
        truncate_ratio = self.truncate_ratios[idx]
        return image, torch.tensor(truncate_ratio, dtype=torch.float32)

# Define transformations for the images
