import os, sys, re
from PIL import Image

import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms



#[1] Training precheck - start
def check_CUDA_or_ROCm():
    if torch.cuda.is_available():
        print(f'CUDA is available. Device count: {torch.cuda.device_count()}')
        print(f'CUDA Device Name: {torch.cuda.get_device_name(0)}')
    elif torch.backends.mps.is_available() and torch.backends.mps.is_built():
        print('ROCm is available.')
    else:
        print('Neither CUDA nor ROCm is available.')
        sys.exit()


#[1] Training precheck - end





#[3] Dataset and Dataloader - start

class TruncatedTriangleDataset(Dataset):
    def __init__(self, image_dir, transform=None):
        self.image_dir = image_dir
        self.transform = transform
        self.image_files = [f for f in os.listdir(image_dir) if f.endswith('.png')]
        self.truncate_ratios = [recover_generation_info_from_filename(f)[0] for f in self.image_files]

    def __len__(self):
        return len(self.image_files)

    def __getitem__(self, idx):
        img_name = os.path.join(self.image_dir, self.image_files[idx])
        image = Image.open(img_name).convert('L')  # Convert to grayscale
        if self.transform:
            image = self.transform(image)
        truncate_ratio = self.truncate_ratios[idx]
        return image, torch.tensor(truncate_ratio, dtype=torch.float32)

# Define transformations for the images
transform = transforms.Compose([
    transforms.Resize((256, 256)),
    transforms.ToTensor(),])


#[3] Dataset and Dataloader - end



#[5] Model construction - start
"""
This is a truncated triangle CNN model that is used to identify the
truncated ratio of triangles in images. 0 means it's a triangle and 1 means
it's a hexagon.
The input image size is 256 x 256.
"""
class TruncatedTriangleCNN(nn.Module):
    def __init__(self):
        super(TruncatedTriangleCNN, self).__init__()
        self.conv1 = nn.Conv2d(1, 32, kernel_size=3, padding=1)  # Input: 1x256x256, Output: 32x256x256
        self.conv2 = nn.Conv2d(32, 64, kernel_size=3, padding=1) # Input: 32x128x128, Output: 64x128x128
        self.conv3 = nn.Conv2d(64, 128, kernel_size=3, padding=1) # Input: 64x64x64, Output: 128x64x64
        self.conv4 = nn.Conv2d(128, 256, kernel_size=3, padding=1) # Input: 128x32x32, Output: 256x32x32
        self.conv5 = nn.Conv2d(256, 512, kernel_size=3, padding=1) # Input: 256x16x16, Output: 512x16x16
        self.pool = nn.MaxPool2d(kernel_size=2, stride=2)
        self.fc1 = nn.Linear(512 * 8 * 8, 1024)  # Flattened from 512x8x8
        self.fc2 = nn.Linear(1024, 1)

    def forward(self, x):
        x = self.pool(F.relu(self.conv1(x)))  # After pool: 32x128x128
        #print("After conv1:", x.shape)
        x = self.pool(F.relu(self.conv2(x)))  # After pool: 64x64x64
        #print("After conv2:", x.shape)
        x = self.pool(F.relu(self.conv3(x)))  # After pool: 128x32x32
        #print("After conv3:", x.shape)
        x = self.pool(F.relu(self.conv4(x)))  # After pool: 256x16x16
        #print("After conv4:", x.shape)
        x = self.pool(F.relu(self.conv5(x)))  # After pool: 512x8x8
        #print("After conv5:", x.shape)
        x = x.view(-1, 512 * 8 * 8)           # Flatten to 512*8*8
        x = F.relu(self.fc1(x))
        x = self.fc2(x)
        return x

#[5] Model construction - end
