def enhance(image_path, clipLimit=2.0, tileGridSize=(8,8), ):
    img = cv2.imread(image_path, 1)
    #[1] converting to LAB color space
    lab= cv2.cvtColor(img, cv2.COLOR_BGR2LAB)
    l_channel, a, b = cv2.split(lab)

    #[2] Applying CLAHE to L-channel
    clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8,8))
    cl = clahe.apply(l_channel)

    #[3] merge the CLAHE enhanced L-channel with the a and b channel
    limg = cv2.merge((cl,a,b))

    #[4] Converting image from LAB Color model to BGR color spcae
    enhanced_img = cv2.cvtColor(limg, cv2.COLOR_LAB2BGR)
    path_enhanced_img = image_path.replace('.png','_1-enh.png')
    path_enhanced_img = f'{os.path.splitext(path_enhanced_img)[0]}_1-enh{os.path.splitext(path_enhanced_img)[1]}'
    print(path_enhanced_img)
    cv2.imwrite(path_enhanced_img, enhanced_img)
    
    return path_enhanced_img
  
