"""
[NLR-01_Nonlinear Regression.py]
Purpose: Check new words for learning.
Author: Meng-Chi Ed Chen
Date: 2023-05-02
Reference:
    1.https://github.com/MichaelAllen1966/thursday_coding_club_2020/blob/master/02_non_linear_regression.ipynb
    2.

Status: Ongoing.
"""
import torch.nn as nn
import torch.nn.functional as F
import numpy as np
import matplotlib.pyplot as plt

class ThisModel(nn.Module):
    def __init__(self):
        super(ThisModel, self).__init__()
        self.nn1 = nn.Linear(1, 5)
        self.nn2 = nn.Linear(5, 5)
        self.nn3 = nn.Linear(5, 1)

    def forward(self, x):
        x = F.relu(self.nn1(x))
        x = F.relu(self.nn2(x))
        x = self.nn3(x)
        return x


#[02] Create non-linear data (a sine wave with noise)
X = np.linspace(1, 17, 1000).reshape(-1,1)
error = np.random.randint(-10, 10, (1000,1))
y = np.sin(X)*50 + error

#[03] Show data
plt.scatter(X, y)
plt.ylabel('y')
plt.xlabel('x')
#plt.show()


