from scapy.all import ARP, Ether, srp

def scan(ip):
    """
    This function will take IP as an argument and will scan all devices on the network
    """
    arp_request = ARP(pdst=ip)
    broadcast = Ether(dst="ff:ff:ff:ff:ff:ff")
    arp_request_broadcast = broadcast/arp_request
    answered_list = srp(arp_request_broadcast, timeout=1, verbose=False)[0]

    clients_list = []
    for sent, received in answered_list:
        clients_list.append({'ip': received.psrc, 'mac': received.hwsrc})

    return clients_list

def print_result(results_list):
    """
    This function will print the result of the scanning
    """
    print("IP \t \t \t MAC Address")
    print("----------------------------------------------------")
    for client in results_list:
        print(f"{client['ip']}\t\t{client['mac']}")

