from scapy.all import ARP, Ether, srp
import socket

def get_hostname(ip):
    try:
        hostname = socket.gethostbyaddr(ip)[0]
        return hostname
    except socket.herror:
        return "Unknown"

def discover_devices(interface):
    #arp = ARP(pdst='10.29.47.0/24')  #This is the IP address through wifi.
    #arp = ARP(pdst='192.168.1.0/24')
    arp = ARP(pdst='0.0.0.0/24')
    #arp = ARP(pdst='169.254.79.0/24')
    #arp = ARP(pdst='10.82.5.0/24')

    ether = Ether(dst='ff:ff:ff:ff:ff:ff')
    packet = ether/arp
    result = srp(packet, timeout=3, iface=interface, verbose=0)[0]
    devices = []
    for sent, received in result:
        devices.append({'ip': received.psrc, 'mac': received.hwsrc, 'hostname': get_hostname(received.psrc)})
    return devices

devices = discover_devices('Ethernet')

print('Devices found:', len(devices))

for device in devices:
    print(f"IP: {device['ip']}\tMAC: {device['mac']}\tHostname: {device['hostname']}")
