import socket

def send_udp_command(ip_address, port, command):
    # Create a UDP socket
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)

    try:
        # Send the command to the relay
        sock.sendto(command.encode(), (ip_address, port))
        print("UDP command sent successfully.")
    except socket.error as e:
        print(f"Error sending UDP command: {e}")
    finally:
        # Close the socket
        sock.close()

# Specify the IP address and port of the Ethernet relay
