import socket
import subprocess
import os

def get_ip():
    """Get the local IP address of the machine running the script"""
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        #s.connect(('10.255.255.255', 1))
        s.connect(('192.168.0.0', 1))
        local_ip = s.getsockname()[0]
    except Exception:
        local_ip = '127.0.0.1'
    finally:
        s.close()
    return local_ip

def find_device_ip(device_port=80):
    """Scan the local network for a device on a given port"""
    local_ip = get_ip()
    ip_base = '.'.join(local_ip.split('.')[:-1]) # Get the first three parts of the IP

    # Scan the entire subnet range
    for i in range(1, 256):
        ip_to_test = f"{ip_base}.{i}"
        print(f"Scanning {ip_to_test}", end="\r", flush=True)

        try:
            # Try to open a socket to the IP address
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(0.05) # Don't wait too long, we have many IPs to scan
            result = sock.connect_ex((ip_to_test, device_port))

            if result == 0: # Success, something is open on the port
                print(f"\nFound potential device at {ip_to_test}")
                sock.close()

        except socket.error as ex:
            pass # We can't connect, likely nothing there
    print("\nScan completed.")

find_device_ip()
# End of [WEC-01_(IP scanner cGPT4).py]




