def ping_ip(ip_address):
    try:
        output = subprocess.check_output("ping -{} 0 {}".format('n' 
        if platform.system().lower()=="windows" else 'c', ip_address), 
        shell=True)

        if 'unreachable' in output.decode('utf-8'):
            return False
        else:
            return True
    except subprocess.TimeoutExpired:
        return False
    except Exception:
        return False


# Default IP address
