def image_color_channel_extract(path_image, dir_excel, save_excel):
    global image_basename
    global blue_channel
    global green_channel
    global red_channel
    image_basename = os.path.basename(path_image)
    array_image = cv2.imread(path_image)     #print('image (BGR):\n', array_image)
    print('[image_color_channel_extract] shape (H, W, C):', array_image.shape)
    blue_channel = array_image[:,:,0]
    green_channel = array_image[:,:,1]
    red_channel = array_image[:,:,2]
    #[] Save a copy as excel or not.
    if save_excel == 1:
        #[] Convert array to dataframe.
        df_blue_channel = pd.DataFrame (blue_channel)
        df_green_channel = pd.DataFrame (green_channel)
        df_red_channel = pd.DataFrame (red_channel)
        #[] Save the dataframe to excel sheet.
        path_excel = dir_excel + '\\' + image_basename + '.xlsx'
        writer = pd.ExcelWriter(path_excel, engine='xlsxwriter')
        df_blue_channel.to_excel(writer, sheet_name = 'blue')
        df_green_channel.to_excel(writer, sheet_name = 'green')
        df_red_channel.to_excel(writer, sheet_name = 'red')
        #[] Save the dataframe to excel.
        writer.close()

def single_channel_average(single_color_channel, k, s):
    kernel = torch.ones((1, 1, k, k)) / (k * k)
    print('Kernel:', kernel.shape, type(kernel))
    single_color_channel = torch.tensor(single_color_channel).unsqueeze(0).unsqueeze(1).float()
    print('color_channel:', single_color_channel.shape)

    conv = nn.Conv2d(in_channels=1, out_channels=1, kernel_size = k, stride = s, bias=False)
    conv.weight = nn.Parameter(kernel)
    averaged_channel = conv(single_color_channel)
    #[] Convert the tensor (averaged_channel) to numpy array, and squeeze to remove any singleton dimensions.
    numpy_img = averaged_channel.detach().numpy().squeeze()
    print('averaged_channel:', numpy_img.shape, end='\n\n')
    #[] Normalize the values between 0 and 255, and convert to uint8
    numpy_img = (numpy_img - np.min(numpy_img)) / (np.max(numpy_img) - np.min(numpy_img)) * 255
    numpy_img = numpy_img.astype(np.uint8)
    return numpy_img
    


def single_channel_std(single_color_channel, k, s):
    global numpy_img_array_std
    single_color_channel = torch.tensor(single_color_channel).unsqueeze(0).unsqueeze(3).float()
    print('color_channel:', single_color_channel.shape, type(single_color_channel))
    
    patches  = tf.image.extract_patches(images=single_color_channel,
                                            sizes=[1, k, k, 1], # kernal: The size of the extracted patches.
                                            strides=[1, s, s, 1], # strides:  How far the centers of two consecutive patches are in the images.
                                            rates=[1, 1, 1, 1],
                                            padding='VALID')    
    
    numpy_img = tf.math.reduce_std(patches , axis=-1)
    numpy_img = numpy_img.numpy().squeeze()
    print('std_channel:', numpy_img.shape, type(numpy_img))
    #[] Normalization
    max_std = np.max(numpy_img)
    print('max_std: ', max_std, end='\n\n')
    numpy_img = (numpy_img * 255/max_std).astype(np.uint8)
    return numpy_img

def save_PIL_image(numpy_img, dir_save_image, basename, new_discription):
    image_PIL = Image.fromarray(numpy_img)
    basename = basename.replace('.png', new_discription + '.png')
    path_save_image = dir_save_image + '//' + basename
    image_PIL.save(path_save_image)



