def RANSAC_filtering_xyz(df_xyz, ind_xyz = [0, 1, 2]):
    """
    arr_z have linear correlation with arr_x, or arr_y, or both. 
    Use RANSAC to remove outliers. Add a threshold handle if possible.
    """
    #[1] Check if the DataFrame has at least three columns
    if df_xyz.shape[1] < 3:
        raise ValueError("The DataFrame does not have enough columns. It needs at least three columns.")

    #[2] Extract the first three columns into numpy arrays
    [idx_x, idx_y, idx_z] = ind_xyz
    arr_x = df_xyz.iloc[:, idx_x].values
    arr_y = df_xyz.iloc[:, idx_y].values
    arr_z = df_xyz.iloc[:, idx_z].values
    
    # [3] Prepare the features matrix 'X' and target vector 'z'
    X = np.column_stack((arr_x, arr_y))
    z = arr_z

    # [5] Fit the RANSAC regressor
    ransac = RANSACRegressor()
    ransac.fit(X, z)

    # [6] Identify inliers and outliers
    inlier_mask = ransac.inlier_mask_

    # [7] Filter the DataFrame to include only inliers
    df_xyz_filtered = df_xyz[inlier_mask]

    return df_xyz_filtered

