#[1] Fit the invert cone - Start


















def find_gradient_and_distance_to_z0_1(list_XY, list_z_coor):
    print('\n[find_gradient_and_angle]')
        
    #[1] Prepare data
    list_XY = np.array(list_XY)
    list_x_coor, list_y_coor = list_XY[:, 0], list_XY[:, 1]
    combined_data = np.column_stack((list_x_coor, list_y_coor, list_z_coor))

    #[2-1] Fit a 2D normal distribution to the data
    weights = np.exp(-np.array(list_z_coor) / np.std(list_z_coor))
    weighted_mean = np.average(list_XY, axis=0, weights=weights)
    # Estimate the covariance matrix weighted by displacement values
    covariances = np.cov(list_XY.T, aweights=weights)
    print(f'(weights.shape, weighted_mean, covariances) = {weights.shape}, {weighted_mean}, {covariances}')
    
    #[2-2] Extract major axis (direction of greatest spread) from covariance matrix
    eigenvalues, eigenvectors = np.linalg.eig(covariances)
    major_axis = eigenvectors[:, np.argmax(eigenvalues)]
    
    #[3] Calculate gradient direction based on major axis
    # Invert major axis if displacement decreases along the positive direction
    if np.mean(list_z_coor) < list_z_coor[0]:  # Check if displacement decreases positively
        major_axis *= -1

    # Normalize the major axis to represent direction
    grad_dir_rst = major_axis / np.linalg.norm(major_axis)
    print(f'--Gradient direction (raster): {grad_dir_rst}')
    
    #[4] Calculate the magnitude of the gradient (slope)
    # Perform linear regression on all data points to calculate the best fit line's slope and intercept
    slope, intercept = np.polyfit(list_x_coor, list_z_coor, 1, full=True)[:2]
    gradient = slope
    print(f'--Gradient: {gradient}; Intercept: {intercept}')

    
    #[5] Calculate statistics for z values
    sorted_data = combined_data[combined_data[:, 2].argsort()]
    num_points = int(len(sorted_data) * 0.1)
    bottom_pct_data = sorted_data[:num_points]
    top_pct_data = sorted_data[-num_points:]
    bot_pct_x_coor, bot_pct_y_coor, bot_pct_z_coor = np.mean(bottom_pct_data, axis=0)
    top_pct_x_coor, top_pct_y_coor, top_pct_z_coor = np.mean(top_pct_data, axis=0)
    print(f'--Bottom 10% (bot_pct_x_coor, bot_pct_y_coor, bot_pct_z_coor) = ({bot_pct_x_coor}, {bot_pct_y_coor}, {bot_pct_z_coor})')
    print(f'--Top 10% (top_pct_x_coor, top_pct_y_coor, top_pct_z_coor) = ({top_pct_x_coor}, {top_pct_y_coor}, {top_pct_z_coor})')

    #[6] Determine angle of gradient using mean positions
    dx = top_pct_x_coor - bot_pct_x_coor
    dy = top_pct_y_coor - bot_pct_y_coor
    theta_rad = np.arctan2(dy, dx)  # Angle in radians
    theta_deg = np.degrees(theta_rad)  # Convert to degrees
    print(f'--Theta of gradient: {theta_deg}')
    
    #[7] Calculate distance to z=0
    dist_to_Z0 = -intercept / gradient
    print(f'--Distance to Origin: {dist_to_Z0}')
    return grad_dir_rst, dist_to_Z0



def train_to_fit_the_invert_cone(list_coor2_x, list_coor2_y, list_d_l, initial_ctr_rot_x, initial_ctr_rot_y, initial_cone_slope, initial_lr, num_epochs, text_log):
    """
    [Goal]
        Optimizes the parameters x_ctr_rot, y_ctr_rot, and cone_slope to minimize the loss using linear regression.
    [Args]
        list_coor2: list of coordinates in (x, y)
        list_d_l: list of displacement, a single value. Just regard as the elevation of invert cone.
        ctr_rot: center of rotation (x, y) in raster coordinate.
        cone_slope: the ratio the invert cone rises for every one unit away from the center of rotation.
        learning_rate: the learning rate for gradient descent
        num_epochs: the number of epochs to train the model
    [Note]
        1. Define the origin as the upper left corner of the image.
        2. Use raster coordinate system where x-axis increases to the right and the y-axis increases downward.
    """
    print('\n[train_to_fit_the_invert_cone]')
    #[1] Initialize parameters
    assert len(list_coor2_x) == len(list_coor2_y) == len(list_d_l), "Input arrays must have the same length"
    x_ctr_rot, y_ctr_rot = initial_ctr_rot_x, initial_ctr_rot_y
    cone_slope = initial_cone_slope
    learning_rate = initial_lr

    #[2] Convert input lists to numpy arrays
    X = np.column_stack((np.array(list_coor2_x), np.array(list_coor2_y)))
    Y = np.array(list_d_l)
    # the rest of the code ... 
    
    low_loss_cnt = 0
    dont_set_cone_slope_yet = 0
    list_loss, list_loss_dr = [], []
    list_lr = []
    list_ctr_rot_x = [x_ctr_rot]
    list_ctr_rot_y = [y_ctr_rot]
    list_cone_slope = [cone_slope]
    list_grad_x, list_grad_y, list_grad_cone_slope = [], [], []
    text_in_for = ''
    allow_lower_lr = max(num_epochs * 0.1, 3)

    #[3] Train the model for the specified number of epochs
    for epoch in range(num_epochs):
        #[4] Start appending from the second iteration to keep list in the same length during dataframe construction.
        if epoch >= 1:
            list_ctr_rot_x.append(x_ctr_rot)
            list_ctr_rot_y.append(y_ctr_rot)
            list_cone_slope.append(cone_slope)
        
        
        #[4] Forward pass
        #print(f'(X[:, 0], X[:, 1]): {X[:, 0]}, {X[:, 1]}')
        x_CR2P = x_ctr_rot + X[:, 0] # CR2P = Center of rotation to point
        y_CR2P = y_ctr_rot + X[:, 1]
        cone_elev = cone_slope * np.sqrt(x_CR2P**2 + y_CR2P**2)
        y_pred = cone_elev

        #[5] Calculate loss and update learning rate
        loss = np.mean((y_pred - Y)**2)
        list_loss.append(loss)
        text = ''
        
        #[10] Update learning rate
        if len(list_loss) >= 2 and loss/list_loss[-1] < 2:
            loss_decrease_ratio = loss/list_loss[-1]
            list_loss_dr.append(loss_decrease_ratio)
            text = f'loss_decrease_ratio: {loss_decrease_ratio}'
            if epoch >= int(num_epochs * 0.3) and list_loss_dr[-1] > 0.9999 and len(list_loss) > allow_lower_lr:
                learning_rate = initial_lr * 1e-1
            elif epoch >= int(num_epochs * 0.6) and list_loss_dr[-1] > 0.99999 and len(list_loss) > allow_lower_lr:
                learning_rate = initial_lr * 1e-2
            elif epoch >= int(num_epochs * 0.9) and list_loss_dr[-1] > 0.999999 and len(list_loss) > allow_lower_lr:
                learning_rate = initial_lr * 1e-3
            elif list_loss_dr[-1] > 0.9999999999 and epoch >=10:
                low_loss_cnt += 1
                if low_loss_cnt > 3:
                    #[10-1] Early stop
                    text = f'[{epoch+1}]--[Good enough] Early stop triggered by low_loss_cnt ({low_loss_cnt}) and loss_decrease_ratio ({loss_decrease_ratio}).\n'
                    text_in_for += text
                    print(text)
                    #[10-2] Make lengths of the lists in the dataframe the same.
                    list_lr.append(learning_rate)
                    grad_x = np.mean(2 * (y_pred - Y) * cone_slope * x_CR2P / np.sqrt(x_CR2P**2 + y_CR2P**2))
                    grad_y = np.mean(2 * (y_pred - Y) * cone_slope * y_CR2P / np.sqrt(x_CR2P**2 + y_CR2P**2))
                    grad_cone_slope = np.mean(2 * (y_pred - Y) * np.sqrt(x_CR2P**2 + y_CR2P**2))
                    list_grad_x.append(grad_x)
                    list_grad_y.append(grad_y)
                    list_grad_cone_slope.append(grad_cone_slope)
                    break
                learning_rate = initial_lr * 1e-4
        else:
            list_loss_dr.append(None)
        list_lr.append(learning_rate)        

        #[11] Backward pass (gradient calculation)
        grad_x = np.mean(2 * (y_pred - Y) * cone_slope * x_CR2P / np.sqrt(x_CR2P**2 + y_CR2P**2))
        grad_y = np.mean(2 * (y_pred - Y) * cone_slope * y_CR2P / np.sqrt(x_CR2P**2 + y_CR2P**2))
        grad_cone_slope = np.mean(2 * (y_pred - Y) * np.sqrt(x_CR2P**2 + y_CR2P**2))

        #[12] Update parameters
        x_ctr_rot -= learning_rate * grad_x
        y_ctr_rot -= learning_rate * grad_y
        cone_slope -= learning_rate * grad_cone_slope * 1e-10
        list_grad_x.append(grad_x)
        list_grad_y.append(grad_y)
        list_grad_cone_slope.append(grad_cone_slope)
        # The loss is very sensitive to the cone_slope, 0.005 is too big, 1e-5 might be too slow. 1e-4 too fast.

        #[13] Print progress
        text = f'  Epoch [{epoch+1}/{num_epochs}]  Loss: {loss:.6f}. Learning rate: {learning_rate:.2e}\n'\
                f'    (grad_x, grad_y, grad_cone_slope) = {grad_x:.6f}, {grad_y:.6f}, {grad_cone_slope:.6f}\n'\
                f'    (x_ctr_rot, y_ctr_rot, cone_slope) = {x_ctr_rot}, {y_ctr_rot}, {cone_slope}\n'
        print(text)

        #[14] Check if cone_slope becomes negative
        dont_set_cone_slope_yet -=1
        if cone_slope < 0 and dont_set_cone_slope_yet <= 0:
            cone_slope = initial_cone_slope * 100
            x_ctr_rot = x_ctr_rot + np.random.rand()*initial_lr*200-100
            y_ctr_rot = y_ctr_rot + np.random.rand()*initial_lr*200-100
            text = f'[{epoch+1}]\n--[cone_slope < 0] set cone_slope to {cone_slope} and randomize ctr_rot.\n'
            text_in_for += text
            print(text)
            dont_set_cone_slope_yet = 3

    
    #[18] Dataframe length check.
    df_length_check = False
    if df_length_check:
        print(f'[list_lr] {len(list_lr)}')
        print(f'[list_ctr_rot_x] {len(list_ctr_rot_x)}')
        print(f'[list_ctr_rot_y] {len(list_ctr_rot_y)}')
        print(f'[list_cone_slope] {len(list_cone_slope)}')
        print(f'[list_grad_x] {len(list_grad_x)}')
        print(f'[list_grad_y] {len(list_grad_y)}')
        print(f'[list_grad_cone_slope] {len(list_grad_cone_slope)}')
        print(f'[list_loss] {len(list_loss)}')
        print(f'[list_loss_dr] {len(list_loss_dr)}')
    
    #[20] Create dataframe for the training process.
    df = pd.DataFrame({'list_lr': list_lr,
                        'list_ctr_rot_x': list_ctr_rot_x,
                        'list_ctr_rot_y': list_ctr_rot_y,
                        'list_cone_slope': list_cone_slope,
                        'list_grad_x': list_grad_x,
                        'list_grad_y': list_grad_y,
                        'list_grad_cone_slope': list_grad_cone_slope,
                        'list_loss': list_loss,
                        'list_loss_dr': list_loss_dr})
    df.index.name = 'epoch'
    
    
    # floatfmt helps keep the decimal places in the dataframe.
    text_log += f'\n{tabulate(df, headers="keys", tablefmt="orgtbl", floatfmt=".10f")}\n\n{text_in_for}\n\n'

    print()
    #[22] Return optimized parameters and final loss
    return (list_ctr_rot_x, list_ctr_rot_y, list_cone_slope, list_loss, list_lr, text_log)





def grid_search_to_find_min_loss(list_coor2_x, list_coor2_y, list_d_l
                              , list_ctr_rot_x, list_ctr_rot_y, list_cone_slope):
    #[1] Convert input lists to numpy arrays
    X = np.column_stack((np.array(list_coor2_x), np.array(list_coor2_y)))
    Y = np.array(list_d_l)
    
    #[2] Create meshgrid
    X_mesh, Y_mesh, Z_mesh = np.meshgrid(list_ctr_rot_x, list_ctr_rot_y, list_cone_slope)
    
    #[3] Calculate losses for each position
    list_loss = []
    for x, y, z in zip(np.ravel(X_mesh), np.ravel(Y_mesh), np.ravel(Z_mesh)):
        x_CR2P = x + X[:, 0]   # Center of rotation to point
        y_CR2P = y + X[:, 1]
        cone_elev = z * np.sqrt(x_CR2P**2 + y_CR2P**2)
        y_pred = cone_elev
        loss = np.mean((y_pred - Y)**2)
        list_loss.append(loss)
    arr_loss = np.array(list_loss).reshape(X_mesh.shape)
    
    #[6] Get the position of the minimum loss
    min_loss_idx = np.unravel_index(np.argmin(arr_loss, axis=None), arr_loss.shape)
    min_loss_value = arr_loss[min_loss_idx]

    #[7] Return the index of point with minimum loss
    text = f'min_loss_idx = {min_loss_idx}'
    #print(text)
    return arr_loss, X_mesh, Y_mesh, Z_mesh, min_loss_idx, min_loss_value







    
    
def plot_3D_universal_mapping(arr_loss, X_mesh, Y_mesh, Z_mesh, min_loss_idx
                                ,text_title, text_note
                                , elev=30, azim=-60, path_save=None):

    #[4] Create figure
    fig = plt.figure(figsize=(8, 8))
    ax = plt.axes(projection='3d')
    ax.view_init(elev=elev, azim=azim)
    
    #[6] Normalize loss values for size scaling
    min_loss, max_loss = arr_loss.min(), arr_loss.max()
    arr_norm_loss = (arr_loss - min_loss) / (max_loss - min_loss) * 50 + 10
    
    #[5] Create scatter plot
    sc = ax.scatter(X_mesh, Y_mesh, Z_mesh, c=arr_loss, cmap='spring_r', s=arr_norm_loss, alpha=0.2, depthshade=False)
    
    #[9] Mark the position of the minimum loss
    min_x, min_y, min_z = X_mesh[min_loss_idx], Y_mesh[min_loss_idx], Z_mesh[min_loss_idx]
    ax.scatter(min_x, min_y, min_z, c='red', marker='*', s=100)  
    
    #[12] Labels and title.
    ax.set_xlabel('X coor')
    ax.set_ylabel('Y coor (raster)')
    ax.set_zlabel('Z (cone Slope)')
    ax.set_title(f'3D Optimization Record of {text_title}')
    
    #[13] Axes appearance adjustments.
    ax.xaxis.set_major_formatter(ScalarFormatter(useMathText=True))
    ax.yaxis.set_major_formatter(ScalarFormatter(useMathText=True))
    ax.zaxis.set_major_formatter(ScalarFormatter(useMathText=True))
    ax.ticklabel_format(style='sci', axis='x', scilimits=(0,0))
    ax.ticklabel_format(style='sci', axis='y', scilimits=(0,0))
    ax.ticklabel_format(style='sci', axis='z', scilimits=(0,0))
    
    #[14] Flip the y-axis to simulate raster coordinates.
    ax.set_ylim(ax.get_ylim()[::-1])
    
    #[15] Adding the additional text.
    plt.subplots_adjust(bottom=0.30, right=0.85)
    plt.figtext(0.05, 0.27, text_note, fontsize=10, va="top", ha="left")
    
    #[16] Adding color bar to indicate the scale of loss.
    cbar_ax = fig.add_axes([0.90, 0.15, 0.02, 0.7])  # [left, bottom, width, height]
    cbar = plt.colorbar(sc, cax=cbar_ax, aspect=10)
    cbar.set_label('Loss')
    
    #[17] Save or show plot.
    if path_save:
        plt.savefig(path_save)
        print(f'--Plot saved at {path_save}')
    else:
        plt.show()

    return fig, ax











def map_the_invert_cone(list_coor2, list_d_l, list_test_coor, initial_cone_slope):
    #[1] Initialize parameters
    cone_slope = initial_cone_slope
    #[2] Convert input lists to numpy arrays
    X = np.array(list_coor2)
    y = np.array(list_d_l)
    list_loss = []
    list_ctr_rot = []
    #[3] Train the model for the specified number of epochs
    for cnt, iter_test_coor in enumerate(list_test_coor):
        #[4] Forward pass
        #print(f'(X[:, 0], X[:, 1]): {X[:, 0]}, {X[:, 1]}')
        x_ctr_rot, y_ctr_rot = iter_test_coor
        x_CR2P = x_ctr_rot + X[:, 0]
        y_CR2P = y_ctr_rot + X[:, 1]
        cone_elev = cone_slope * np.sqrt(x_CR2P**2 + y_CR2P**2)
        y_pred = cone_elev
        #[5] Record
        list_ctr_rot.append([x_ctr_rot, y_ctr_rot])
        #[6] Calculate loss and update learning rate
        loss = np.mean((y_pred - y)**2)
        list_loss.append(loss)
    print()
    #[9] Return optimized parameters and final loss
    return list_ctr_rot, list_loss










