def truncate_df_at_first_all_nan(df):
    print('\n[truncate_df_at_first_all_nan]')
    #[1] Identify rows with all NaN values
    all_nan_rows = df[df.isnull().all(axis=1)]
    
    #[2] Check if there are any all-NaN rows
    if not all_nan_rows.empty:
        #[3] Get the index of the first all-NaN row
        idx_first_all_nan = all_nan_rows.index[0]
        
        #[4] Truncate the DataFrame up to that row
        df_truncated = df.loc[:idx_first_all_nan-1]
    else:
        #[5] If there are no all-NaN rows, return the original DataFrame
        df_truncated = df.copy()
    
    return df_truncated


def check_if_bsn_dir_is_in_gen_setting(bsn_dir, df_gen_setting):
    """
    df_gen_setting has four columns: Trail, x_GT, y_GT, r_GT.
    If bsn_dir matches one in the Trail column,
    return x_GT, y_GT, r_GT
    else: return None
    """
    #[1] Check if the bsn_dir matches any entry in the Trail column
    match = df_gen_setting[df_gen_setting['Trail'] == bsn_dir]
    
    #[2] If there is a match, return the corresponding x_GT, y_GT, and r_GT values
    if not match.empty:
        idx = match.index[0]
        x_GT = int(match['x_GT'].values[0])
        y_GT = int(match['y_GT'].values[0])
        r_GT = float(match['r_GT'].values[0])
        print(f'Found {bsn_dir} at index {idx}.')
        return x_GT, y_GT, r_GT
    
    #[3] If no match is found, return None
    return None
    



