sheet_name = '01_opt'
list_column = []

df_trails = MRD.read_specific_columns_in_excel_sheet_into_dataframe(path_xlsx, sheet_name, 'J', 'W', 50)

print(f'\n\n{tabulate(df_trails, headers="keys", tablefmt="orgtbl")}')

(list_x_opt, list_y_opt, list_r_opt,
    list_x_GTset, list_y_GTset, list_r_GTset,
    list_x_GTcorr, list_y_GTcorr, list_r_GTcorr,
    list_err_x, list_err_y, list_err_r, list_e_abs_avg) = recover_lists_from_df_trails(df_trails)


#[4] Time stamp
timestamp = datetime.now().strftime("%Y-%m%d-%H%M%S")





#[5] Average three error list into a mean error.
path_save = os.path.join(dir_save, f'{timestamp}_01_Error trend_set.png')
plot_2D_error_trend(list_x_opt, list_y_opt, list_e_abs_avg, 'x_opt', 'y_opt', 'err_mean', 'Error Trend using Set Value', path_save)


path_save = os.path.join(dir_save, f'{timestamp}_02_Error trend_corr.png')
plot_2D_error_trend(list_x_opt, list_y_opt, list_e_abs_avg, 'x_opt', 'y_opt', 'err_mean', 'Error Trend using Corrected Value', path_save)




