print(text)
text_log += text

#[76] Save log report
timestamp = datetime.now().strftime("%Y-%m%d-%H%M%S")
path_txt = os.path.join(dir_img_folder, f'{timestamp}_{dir_bsn}_1-match log.txt')
M1PCS.create_txt_and_save_text(path_txt, text_log)



