    AO_optimizer = dic_hyperp['AO_optimizer']
    AO_beta1 = dic_hyperp['AO_beta1']
    AO_beta2 = dic_hyperp['AO_beta2']
    AO_eps = dic_hyperp['AO_eps']
    generate_3D_optimization_process = dic_hyperp['generate_3D_optimization_process']
