def generate_rotated_example_images_1(path_img, x_ctr_rot, y_ctr_rot, rot_degree, steps):
    """
    This function rotate the original image by 1 step, 2 steps, and 3 steps to create step-01, step-02, and step-03.
    """
    #[2] Read the base image.
    h, w = check_image_ang_if_total_rotation_distance_too_long(path_img, x_ctr_rot, y_ctr_rot, rot_degree, steps)
    arrimg = cv2.imread(path_img)

    #[4] Initialize lists and dictionary
    list_path_img = []
    dic_rotated_images = {}
    
    #[5] Create a white array that rotates with the arrimg and use it as dummy later.
    arr_white = np.ones((h, w, 3), dtype=np.uint8) * 255
    arr_white_rot = arr_white.copy()

    #[6] Rotate the base image by {rot_degree} by {steps} times.
    for iter_steps in range(steps):
        #[8] Rotate the image
        if iter_steps == 0:     # No need to rotate the first image.
            arrimg_rot = arrimg
        else:                   # Rotate last image.
            cumulative_rot_angle  = iter_steps * rot_degree
            shift_xyr = [x_ctr_rot, y_ctr_rot, cumulative_rot_angle]
            arrimg_rot = ISL.rotate_image(arrimg, shift_xyr)
            arr_white_rot = ISL.rotate_image(arr_white, shift_xyr)  # Only the image in the last rotated step will be remained.
        arr_white_rot[(arr_white_rot[:, :, :] == [0, 0, 0]).all(axis=-1)] = [128, 128, 128] # Keep this line. It's for visual aid later.
        
        #[10] Add image to dictionary.
        dic_rotated_images[f'rotated_arrimg_{iter_steps:02d}'] = arrimg_rot
        last_arrimg_rot = arrimg_rot
                
    #[10] Check crop box.
    min_x, min_y, max_x, max_y = ISL.find_largest_inscribe_rectangle_2(arr_white_rot, square=True)
    print(f'\n[Original Image] {h}, {w}')
    print(f'[Crop box] X {min_x}, {max_x}')
    print(f'[Crop box] Y {min_y}, {max_y}\n')

    # [14] Save all the images in the directory.
    dir_img_folder = os.path.dirname(path_img)
    for idx, (key, rotated_img) in enumerate(dic_rotated_images.items()):
        rotated_img = rotated_img[min_y:max_y, min_x:max_x] # [13] Crop all rotated images to the minimum bounding rectangle and save.
        bsn_original = os.path.splitext(os.path.basename(path_img))[0]
        filename = f"{bsn_original}_step-{idx:02d}.jpg"
        path_save = os.path.join(dir_img_folder, filename)
        cv2.imwrite(path_save, rotated_img)
        list_path_img.append(path_save)
        
    #[18] Save white image.
    cv2.rectangle(arr_white_rot, (min_x, min_y), (max_x, max_y), (220,180,30), 20)
    box = min_x, min_y, max_x, max_y
    path_save = os.path.join(dir_img_folder, 'arr_white_rot.jpg')
    cv2.imwrite(path_save, arr_white_rot)
        
    # [20] Update with datetime.
    list_path_img = update_image_exif_datetime_yesterday(list_path_img)


    return list_path_img, box






def generate_rotated_example_images_2(path_img, x_ctr_rot, y_ctr_rot, rot_degree, steps):
    """
    This function rotates the original image by 1 step to have step-01, 
    and rotates step-01 by 1 step to have step-02, 
    and rotates step-02 by 1 step to have step-03.
    Then, crops every image together.
    """
    #[2] Read the base image.
    h, w = check_image_ang_if_total_rotation_distance_too_long(path_img, x_ctr_rot, y_ctr_rot, rot_degree, steps)
    arrimg = cv2.imread(path_img)

    #[4] Initialize lists and dictionary
    shift_xyr = [x_ctr_rot, y_ctr_rot, rot_degree]
    list_path_img = []
    dic_rotated_images = {}

    #[5] Create a white array that rotates with the arrimg and use it as dummy later.
    arr_white = np.ones((h, w, 3), dtype=np.uint8) * 255
    arr_white_rot = arr_white.copy()
    
    #[6] Iterate through steps.
    for iter_steps in range(steps):
        #[8] Rotate the image
        if iter_steps == 0:     # No need to rotate the first image.
            arrimg_rot = arrimg
        else:                   # Rotate last image.
            arrimg_rot = ISL.rotate_image(last_arrimg_rot, shift_xyr)
            arr_white_rot = ISL.rotate_image(arr_white_rot, shift_xyr)
        arr_white_rot[(arr_white_rot[:, :, :] == [0, 0, 0]).all(axis=-1)] = [128, 128, 128] # Keep this line. It's for visual aid later.

        #[10] Add image to dictionary.
        dic_rotated_images[f'rotated_arrimg_{iter_steps:02d}'] = arrimg_rot
        last_arrimg_rot = arrimg_rot
                
        #[12] Update mask intersection for cropping
    
    #[10] Check crop box.
    min_x, min_y, max_x, max_y = ISL.find_largest_inscribe_rectangle_2(arr_white_rot, square=True)
    print(f'\n[Original Image] {h}, {w}')
    print(f'[Crop box] X {min_x}, {max_x}')
    print(f'[Crop box] Y {min_y}, {max_y}\n')

    #[14] Save all the images in the directory.
    dir_img_folder = os.path.dirname(path_img)
    for idx, (key, rotated_img) in enumerate(dic_rotated_images.items()):
        #[15] Crop image
        cropped_img = rotated_img[min_y:max_y, min_x:max_x] 
        #[16] Save image
        bsn_original = os.path.splitext(os.path.basename(path_img))[0]
        filename = f"{bsn_original}_step-{idx:02d}.jpg"
        path_save = os.path.join(dir_img_folder, filename)
        cv2.imwrite(path_save, cropped_img)
        list_path_img.append(path_save)
    
    #[18] Save white image.
    cv2.rectangle(arr_white_rot, (min_x, min_y), (max_x, max_y), (220,180,30), 20)
    box = min_x, min_y, max_x, max_y
    path_save = os.path.join(dir_img_folder, 'arr_white_rot.jpg')
    cv2.imwrite(path_save, arr_white_rot)
        
    # [20] Update with datetime.
    list_path_img = update_image_exif_datetime_yesterday(list_path_img)

    return list_path_img, box
























def add_random_noise(image, pct=0.01, amt=5):
    """
    Randomly choose "amount" ratio of pixels, and adjust the original pixel values by
    adding a random value from -"range" to +"range" (not Gaussian).

    :param image: Input image as a NumPy array.
    :param pct: Fraction of pixels to modify.
    :param amt: The range of value adjustments.
    :return: Image with added random noise.
    """
    #[1] Create a copy of the image
    noisy_image = np.copy(image)

    #[2] Calculate the total number of pixels to modify
    num_pixels = int(pct * image.size / image.shape[2])  # adjust for color channels

    #[3] Randomly select pixel indices
    x_coords = np.random.randint(0, image.shape[0], num_pixels)
    y_coords = np.random.randint(0, image.shape[1], num_pixels)

    #[4] Adjust the pixel values within the specified range
    for x, y in zip(x_coords, y_coords):
        # Random adjustment value
        adjustment = np.random.randint(-amt, amt + 1)

        # Apply adjustment safely for each channel
        for c in range(image.shape[2]):  # Loop through color channels if it's a color image
            noisy_image[x, y, c] = np.clip(noisy_image[x, y, c] + adjustment, 0, 255)

    #[5] Return the noisy image
    return noisy_image





def add_random_noise(image, std=10):
    """
    Generate an arr_noise that has the same shape as the image.
    The values in arr_noise follow a Gaussian distribution centered at 0 with a standard deviation of "sigma".
    Add these two arrays together to create the noisy image.
    """   
    #[2] Generate noise array with the same shape as the image
    noise = np.random.normal(0, std, image.shape)
    
    #[3] Add the noise array to the original image
    noisy_image = image + noise
    
    #[4] Clip the values to ensure they are within the valid range [0, 255] and convert to integer
    noisy_image = np.clip(noisy_image, 0, 255).astype(np.uint8)
    
    #[5] Return the noisy image
    return noisy_image



















