import numpy as np 
import pandas as pd



class DataPreprocessing():
  def __init__(self, file_name):
    self.file = file_name
    print(self.file)
  
  def Map_Horiba(self, X_dim, Y_dim):
    ydata = np.loadtxt(self.file, skiprows=1)
    ydata= ydata[:, 2:]
    ydata = np.expand_dims(ydata, axis=1).reshape(X_dim, Y_dim, ydata.shape[-1])
    ydata = np.expand_dims(ydata, axis=2)
    xdata = np.loadtxt(self.file, max_rows=1)
    xdata = np.expand_dims(xdata, axis=[0,1])
    xdata = np.repeat(xdata, X_dim*Y_dim, axis=0).reshape(X_dim, Y_dim, xdata.shape[-1])
    xdata = np.expand_dims(xdata, axis=2)
    data = np.concatenate((xdata, ydata), axis=2)
    return data

