import numpy as np
import sys


class MappingData:
    def __init__(self, path_txt):
        with open(path_txt, 'r') as file:
            self.content = file.read()
        self.array_2d = None

    def get_counts(self):
        # count_char, count_tab, count_newline
        count_char = len(self.content)
        count_tab = self.content.count('\t')
        count_newline = self.content.count('\n')
        return count_char, count_tab, count_newline
    
    
    # In a row, every element is separated with \t, and every rows are separated with \n.
    # There exist some empty sites such as \t\t or \t\n or \n\t or \n\n.


    def to_2d_list(self):
        self.list_row_lengthes = []
        #[] For each row, split by tabs and replace empty values with None
        self.list_2D = []
        #[] Split the content by newlines to get rows
        list_rows = self.content.strip().split('\n')
        for row in list_rows:
            elements = row.split('\t')
            self.list_2D.append([elem if elem else None for elem in elements])
            self.list_row_lengthes.append(len(row))
        self.x_axis = self.list_2D[0]
        return self.list_2D

        
        
    def remove_xaxis_from_matrix(self):
        return np.delete(self.array_2d, 0, axis=0)

    def extract_x_info(self):
        if self.array_2d is None:
            raise RuntimeError('Please run the "to_2d_array" method before running "extract_x_info".')
        x_max = max(self.x_axis)
        x_min = min(self.x_axis)
        x_range = round(float(x_max) - float(x_min), 6)
        x_count = len(self.x_axis)
        x_spacing = round(x_range / (x_count - 1), 6)
        # For PL, it's in unit of eV. For Raman, it's in unit of cm^-1.
        return x_max, x_min, x_range, x_count, x_spacing

    def extract_x_axis(self):
        if self.array_2d is None:
            raise RuntimeError('Please run the "to_2d_array" method before running "extract_x_info".')
        # self.x_axis = self.array_2d[0] # Already processed in to_2d_array.
        # For PL, it's in unit of eV. For Raman, it's in unit of cm^-1.
        return self.x_axis
