def to_2d_array(self):
    # Split the content by newlines to get rows
    rows = self.content.strip().split('\n')
    # For each row, split by tabs and replace empty values with None
    array_2d_list = []
    for row in rows:
        elements = row.split('\t')
        array_2d_list.append([elem if elem else None for elem in elements])
    
    # Convert the list of lists into a NumPy array with dtype=object
    self.array_2d = np.array(array_2d_list, dtype=object)

    # Optional: Set the first row as the x-axis (ensure this is desired)
    self.x_axis = array_2d_list[0]

    return self.array_2d



