point = [122.47, 122.47, 0]                 # List
line_point, line_vector = (0,0,0), (1,1,1)

stretched_point = C05_ColorClustering.stretch_point_from_a_line(point, 2, (0,0,0), (1,1,1))

print(f'[stretched_point]:{stretched_point}')


#[1] Read array from csv
array_RGB_demo = F04_EXLDF.read_csv_as_array(path_csv)
print(f'[array_RGB_demo]: {array_RGB_demo[:10]}')


line_point, line_vector = (0,0,0), (1,1,1)

for cnt, iter_point in enumerate(array_RGB_demo):
    print(f'\n[{cnt}]')
    #[1] Original Point
    distance = C05_ColorClustering.distance_to_line(iter_point, line_point, line_vector)
    print(f'--Original Point: {iter_point}. Distance: {distance}.')
    
    #[2] Stretched Point
    stretched_point = C05_ColorClustering.stretch_point_from_a_line(iter_point, 2, line_point, line_vector)
    stretched_distance = C05_ColorClustering.distance_to_line(stretched_point, line_point, line_vector)
    print(f'--Stretched Point: {stretched_point}. Distance: {stretched_distance}.')
    if distance == 0:
        ratio = None
    else:
        ratio = round(stretched_distance / distance, 2)
    print(f'----Ratio: {ratio}')
    
    #[3] Recovered Point
    recovered_point = C05_ColorClustering.stretch_point_from_a_line(stretched_point, 0.5, line_point, line_vector)
    recovered_distance = C05_ColorClustering.distance_to_line(recovered_point, line_point, line_vector)
    print(f'--Recovered Point: {recovered_point}. Distance: {recovered_distance}.')
    recovery = np.round(recovered_point - iter_point, 2)
    print(f'----Recovery: {recovery}')


