def generate_circle_points_in3D(center, v_norm, radius, dens_theta, dens_r=5):
    """
    center = np.array([x, y, z])    # The center of the circle.
    v_norm = np.array([vx, vy, vz]) # The normal vector of the circle.
    radius = 10                     # The radius of the circle.
    dens_theta = 12                 # The number of angular divisions (theta).
    dens_r = 5                      # The number of radial divisions.
    The output shape should be (dens_r, dens_theta*3), where 3 comes from XYZ.
    """
    #[1] Normalize the normal vector.
    v_norm = v_norm / np.linalg.norm(v_norm)
    
    #[2] Generate two orthogonal vectors in the plane of the circle.
    if v_norm[0] != 0 or v_norm[1] != 0:        # Check if the normal vector is not parallel to the z-axis.
        v1 = np.array([-v_norm[1], v_norm[0], 0])
    else:                                       # If the normal vector is parallel to the z-axis.
        v1 = np.array([1, 0, 0])
    
    #[3] Normalize v1 and get the second orthogonal vector using the cross product.
    v1 = v1 / np.linalg.norm(v1) 
    v2 = np.cross(v_norm, v1) 
    
    #[4] Generate arr_theta and arr_r for theta and radial distance.
    arr_theta = np.linspace(0, 2 * np.pi, dens_theta)
    arr_r = np.linspace(0, radius, dens_r)

    #[5] Create a meshgrid for theta and radial distance.
    Theta, R = np.meshgrid(arr_theta, arr_r)
    
    #[6] Calculate the points on the circle's surface.
    circ_x = center[0] + R * (np.cos(Theta) * v1[0] + np.sin(Theta) * v2[0])
    circ_y = center[1] + R * (np.cos(Theta) * v1[1] + np.sin(Theta) * v2[1])
    circ_z = center[2] + R * (np.cos(Theta) * v1[2] + np.sin(Theta) * v2[2])

    return circ_x, circ_y, circ_z



def plot_a_circle(center, v_norm, radius, dens_theta, dens_r, text_title, path_save=None):
    """
    Plot a 3D circle given a center, normal vector, and radius.
    """

    #[1] Generate points on the circle's surface.
    circ_x, circ_y, circ_z = generate_circle_points_in3D(center, v_norm, radius, dens_theta, dens_r)

    #[2] Create figure and 3D axis.
    fig = plt.figure(figsize=(8, 8))
    ax = fig.add_subplot(111, projection='3d')
    fs_title = 20
    fs_axis = 14

    #[3] Plot the surface.
    ax.plot_surface(circ_x, circ_y, circ_z, color='green', alpha=0.5)
    
    #[4] Set axis limits.
    ax.set_xlim(0, 255)
    ax.set_ylim(0, 255)
    ax.set_zlim(0, 255)
    
    # [5] Set labels and title.
    ax.set_xlabel('X', fontsize=fs_axis)
    ax.set_ylabel('Y', fontsize=fs_axis)
    ax.set_zlabel('Z', fontsize=fs_axis)
    ax.set_title(text_title, fontsize=fs_title)
    
    #[6] Save or show the plot.
    if path_save:
        plt.savefig(path_save)
        print(f'Plot saved at {path_save}')
    else:
        plt.show()

    return fig, ax


#[5] Example of use.

