dens_r = 5
text_title = f'Circle_ctr{center}, v{v_norm}, r{radius}, dthe{dens_theta}'
path_save = os.path.join(dir_save, f'{text_title}.png')
fig, ax = plot_a_circle(center, v_norm, radius, dens_theta, dens_r, text_title, path_save)
