#[3] Math - start

def array_data_pca_extract_vector(arr_data):
    #[1] Input examination.
    if len(arr_data.shape) != 2:
        raise ValueError('The input arr_data should be a 2D array with every row as a datum and every column as a dimension.')
    print(f'\n[array_data_pca_extract_vector] \n The input arr_data has a shape of {arr_data.shape}.')

    #[2] Singular Value Decomposition (SVD)
    U, S, Vh = np.linalg.svd(arr_data, full_matrices=True) 
    rod_center = np.mean(arr_data, axis=0)
    rod_vector = Vh[0]
    print(f'rod_center = \t{rod_center}\nrod_vector = \t{rod_vector}')
    
    return rod_center, rod_vector
    

def check_if_a_point_is_within_the_rod_like_color_space(sample_color, 
                                                        rod_center, 
                                                        rod_vector, 
                                                        d_to_center=40, 
                                                        d_to_vector=6):
    """
    Along the XYZ vector of rod_vector, draw a line through rod_center.
    A rod-like shape is defined as points within d_to_vector to this line,
    and d_to_center to the rod_vector.
    If sample_color is within this region, return True, otherwise False.    
    """
    #[1] Calculate the vector from rod_center to sample_color
    vector_to_point = sample_color - rod_center
    
    #[2] Calculate the projection of vector_to_point onto rod_vector
    projection_length = np.dot(vector_to_point, rod_vector) / np.linalg.norm(rod_vector)
    
    #[3] Calculate the perpendicular distance to the rod_vector
    perpendicular_distance = np.linalg.norm(np.cross(vector_to_point, rod_vector)) / np.linalg.norm(rod_vector)
    
    #[4] Check if the point lies within the rod-like shape
    in_the_rod = (perpendicular_distance <= d_to_vector) and (np.abs(projection_length - d_to_center) <= d_to_center)
    
    return in_the_rod

def single_image_background_check(path_img,
                                  rod_center, 
                                  rod_vector, 
                                  d_to_center=40, 
                                  d_to_vector=6):
    
    #[1] Read image and get img_mean_color.
    arrimg_reduced = reduce_image_size(path_img, resize_ratio=0.01, path_save=None)
    h, w, c = arrimg_reduced.shape
    arr_2D = arrimg_reduced.reshape(-1, c)
    img_mean_color = np.mean(arr_2D, axis=0)  # Compute mean along columns (BGR channels)
    
    #[2] Check if within rod.
    in_the_rod = check_if_a_point_is_within_the_rod_like_color_space(img_mean_color, 
                                                                    rod_center, 
                                                                    rod_vector, 
                                                                    d_to_center, 
                                                                    d_to_vector)
    return in_the_rod

