def generate_circle_points_in3D(center, v_norm, radius, dens_theta=12, dens_r=5):
    """
    center = np.array([x, y, z])    # The center of the circle.
    v_norm = np.array([vx, vy, vz]) # The normal vector of the circle.
    radius = 10                     # The radius of the circle.
    dens_theta = 12                 # The number of angular divisions (theta).
    dens_r = 5                      # The number of radial divisions.
    The output shape should be (dens_r, dens_theta*3), where 3 comes from XYZ.
    """
    #[1] Normalize the normal vector.
    v_norm = v_norm / np.linalg.norm(v_norm)
    
    #[2] Generate two orthogonal vectors in the plane of the circle.
    if v_norm[0] != 0 or v_norm[1] != 0:        # Check if the normal vector is not parallel to the z-axis.
        v1 = np.array([-v_norm[1], v_norm[0], 0])
    else:                                       # If the normal vector is parallel to the z-axis.
        v1 = np.array([1, 0, 0])
    
    #[3] Normalize v1 and get the second orthogonal vector using the cross product.
    v1 = v1 / np.linalg.norm(v1) 
    v2 = np.cross(v_norm, v1) 
    
    #[4] Generate arr_theta and arr_r for theta and radial distance.
    arr_theta = np.linspace(0, 2 * np.pi, dens_theta)
    arr_r = np.linspace(0, radius, dens_r)

    #[5] Create a meshgrid for theta and radial distance.
    Theta, R = np.meshgrid(arr_theta, arr_r)
    
    #[6] Calculate the points on the circle's surface.
    circ_x = center[0] + R * (np.cos(Theta) * v1[0] + np.sin(Theta) * v2[0])
    circ_y = center[1] + R * (np.cos(Theta) * v1[1] + np.sin(Theta) * v2[1])
    circ_z = center[2] + R * (np.cos(Theta) * v1[2] + np.sin(Theta) * v2[2])

    return circ_x, circ_y, circ_z


def generate_cylinder_points_in3D(start, end, radius, dens_theta=12, dens_vec=50):
    """
    start = np.array([x1, y1, z1])  # The starting end coordinate of the cylinder.
    end = np.array([x2, y2, z2])    # The ending end coordinate of the cylinder.
    radius = 20                     # The radius of the cylinder.
    dens_theta = 12                 # Number of points around the cylinder circumference.
    dens_vec = 50                   # Number of points along the height of the cylinder.
    """
    #[1] Compute the vector along the cylinder's height and its magnitude.
    v = end - start
    mag = np.linalg.norm(v)
    
    #[2] Normalize the vector along the cylinder's height.
    v_norm = v / mag
    
    #[3] Generate two orthogonal vectors in the plane of the circle.
    if v_norm[0] != 0 or v_norm[1] != 0:  # Check if the normal vector is not parallel to the z-axis.
        n1 = np.array([-v_norm[1], v_norm[0], 0])
    else:  # If the normal vector is parallel to the z-axis.
        n1 = np.array([1, 0, 0])
    
    #[4] Normalize n1 and get the second orthogonal vector using the cross product.
    n1 = n1 / np.linalg.norm(n1)
    n2 = np.cross(v_norm, n1)

    #[5] Create grids for the cylinder's height and angle.
    t = np.linspace(0, mag, dens_vec)  # Linear spacing along the cylinder's height.
    theta = np.linspace(0, 2 * np.pi, dens_theta)  # Angular spacing around the cylinder.
    t, theta = np.meshgrid(t, theta)  # Generate mesh grids for t and theta.

    #[6] Compute x, y, and z coordinates of the cylinder's surface points.
    cyl_x = start[0] + v_norm[0] * t + radius * np.sin(theta) * n1[0] + radius * np.cos(theta) * n2[0]
    cyl_y = start[1] + v_norm[1] * t + radius * np.sin(theta) * n1[1] + radius * np.cos(theta) * n2[1]
    cyl_z = start[2] + v_norm[2] * t + radius * np.sin(theta) * n1[2] + radius * np.cos(theta) * n2[2]
    
    return cyl_x, cyl_y, cyl_z



def plot_a_rod_along_with_an_array_in3D(arr_colors_BGR, 
                                        rod_center, rod_vector, d_to_center, d_to_vector, 
                                        text_title, list_axis_title, path_save, XYZ2ZYX=True):
    """
    Plots a 3D scatter plot of an array of colors along with a rod.
    """
    print('\n[plot_a_rod_along_with_an_array_in3D]')
    
    # [1] Check if arr_colors_BGR is a colored image.
    if (len(arr_colors_BGR.shape) != 2) or (arr_colors_BGR.shape[1] != 3):
        raise ValueError(f'Please check the input {arr_colors_BGR}.')

    # [2] Size check.
    pixel_limit = 1e5
    l, c = arr_colors_BGR.shape
    if l >= pixel_limit:
        raise ValueError(f'The arr_colors_BGR has {l} data points, please reduce to less than {pixel_limit} pixels.')

    # [5] Plot settings.
    alpha_array = 0.1
    alpha_rod = 0.2
    line_ext = 1.2
    alpha_line = 0.7
    axis_limit_to_255 = True
    
    # [8] Generate a thick transparent line to simulate a cylinder.
    print(f'[rod_center]: {rod_center}')
    print(f'[rod_vector]: {rod_vector}')
    print(f'[d_to_center]: {d_to_center}')
    start = rod_center - rod_vector * d_to_center
    end = rod_center + rod_vector * d_to_center
    
    # [9] Generate points of the rod and cap the end of the rod with disks.
    rod_radius = d_to_vector
    cyl_x, cyl_y, cyl_z = generate_cylinder_points_in3D(start, end, rod_radius)
    disk1_x, disk1_y, disk1_z = generate_circle_points_in3D(start, rod_vector, rod_radius)
    disk2_x, disk2_y, disk2_z = generate_circle_points_in3D(end, rod_vector, rod_radius)

    # [10] If XYZ2ZYX is True, rearrange the color channels from BGR to RGB.
    if XYZ2ZYX:
        arr_colors_BGR = arr_colors_BGR[:, ::-1]  # Rearrange the color channels

    # [12] Create figure and 3D axis.
    fig = plt.figure(figsize=(8, 8))
    ax = fig.add_subplot(111, projection='3d')
    fs_title = 20
    fs_axis = 14

    # [13] Plot the colored points.
    xs, ys, zs = arr_colors_BGR[:, 2], arr_colors_BGR[:, 1], arr_colors_BGR[:, 0]  # Use BGR for plotting
    colors = arr_colors_BGR / 255.0
    xs = xs.flatten()
    ys = ys.flatten()
    zs = zs.flatten()
    ax.scatter(xs, ys, zs, c=colors, s=5, alpha=alpha_array)
    
    
    

    # [14] Plot the rod and cap disks.
    ax.plot_surface(cyl_x, cyl_y, cyl_z, color='gray', alpha=alpha_rod)
    ax.plot_surface(disk1_x, disk1_y, disk1_z, color='gray', alpha=alpha_rod)
    ax.plot_surface(disk2_x, disk2_y, disk2_z, color='green', alpha=alpha_rod)
    
    # [15] Draw a red line with alpha=alpha_line along the vector of rod_vector and passes through rod_center.
    line_start = rod_center - rod_vector * d_to_center * line_ext
    line_end = rod_center + rod_vector * d_to_center * line_ext
    ax.plot([line_start[0], line_end[0]], 
            [line_start[1], line_end[1]], 
            [line_start[2], line_end[2]], 
            color='red', alpha=alpha_line)
    
    # [16] Set the axis limits based on the broader range.
    if axis_limit_to_255:
        ax.set_xlim(0, 255)
        ax.set_ylim(0, 255)
        ax.set_zlim(0, 255)

    # [19] Set labels and title.
    title_X, title_Y, title_Z = list_axis_title
    ax.set_xlabel(title_X, fontsize=fs_axis)
    ax.set_ylabel(title_Y, fontsize=fs_axis)
    ax.set_zlabel(title_Z, fontsize=fs_axis)
    ax.set_title(text_title, fontsize=fs_title)

    # [20] Save or show the plot.
    if path_save:
        plt.savefig(path_save)
        print(f'Plot saved at {path_save}')
    else:
        plt.show()

    return fig, ax



