import os
import pandas as pd
from PIL import Image
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms

def save_df_as_excel_overwrite(df, path_xlsx, sheet_name):
    print('\n[save_df_as_excel_overwrite]')
    #[1] Make dir if not exist.
    dir_excel = os.path.dirname(path_xlsx)
    if not os.path.exists(dir_excel):
        os.makedirs(dir_excel)

    #[2] Use openpyxl to preserve existing sheets
    if os.path.exists(path_xlsx):
        with pd.ExcelWriter(path_xlsx, engine='openpyxl', mode='a', if_sheet_exists='replace') as writer:
            df.to_excel(writer, sheet_name=sheet_name, index=True)
    else:
        with pd.ExcelWriter(path_xlsx, engine='openpyxl') as writer:
            df.to_excel(writer, sheet_name=sheet_name, index=True)

    print(f'--Dataframe saved to {path_xlsx} in sheet {sheet_name}', end='\n\n')


#[11] Custom dataset loader
class Dataset_OM_Image(Dataset):
    def __init__(self, dir_data, path_excel_annotation, sheetname):
        self.dir_data = dir_data
        self.df_ant = pd.read_excel(path_excel_annotation, sheet_name=sheetname)
        self.transform = transforms.ToTensor()

    #[12] Return the length of the dataset
    def __len__(self):
        return len(self.df_ant)

    #[13] Retrieve a single data point
    def __getitem__(self, idx):
        row = self.df_ant.iloc[idx]
        path_img = os.path.join(self.dir_data, row['name'])
        try:
            image = Image.open(path_img).convert('RGB')

            #[14] Check image size and resize if necessary
            if image.size != (64, 64):
                print(f"Warning: Image {path_img} is not 64x64. Resizing.")
                image = image.resize((64, 64))

            image = self.transform(image)
        except FileNotFoundError:
            print(f"Warning: Image {path_img} not found. Skipping this file.")
            return None

        region = row['region']
        feature = int(row['feature'])

        #[15] Map region annotations to numeric labels
        region_map = {'background': 0, 'edge': 1, 'corner': 2, 'substrate': 3}
        region = region_map[region]

        return image, region, feature

    #[16] Access annotations
    def get_annotations(self):
        return self.df_ant

#[17] Define the CNN model
class CNN_OM_Image_Classifier(nn.Module):
    def __init__(self):
        super(CNN_OM_Image_Classifier, self).__init__()
        self.conv1 = nn.Conv2d(3, 16, 3, 1)
        self.conv2 = nn.Conv2d(16, 32, 3, 1)
        self.fc1 = nn.Linear(32 * 14 * 14, 128)
        self.fc2 = nn.Linear(128, 4)  # For region classification
        self.fc3 = nn.Linear(128, 1)  # For feature classification

    def forward(self, x):
        x = F.relu(self.conv1(x))
        x = F.max_pool2d(x, 2)
        x = F.relu(self.conv2(x))
        x = F.max_pool2d(x, 2)
        x = torch.flatten(x, 1)
        x = F.relu(self.fc1(x))

        region = self.fc2(x)
        feature = torch.sigmoid(self.fc3(x))

        return region, feature

#[18] Define the custom loss function
class CustomLoss(nn.Module):
    def __init__(self):
        super(CustomLoss, self).__init__()
        self.criterion_region = nn.CrossEntropyLoss()
        self.criterion_feature = nn.BCELoss()

    def forward(self, region_pred, feature_pred, region_true, feature_true):
        loss_region = self.criterion_region(region_pred, region_true)
        loss_feature = self.criterion_feature(feature_pred.squeeze(), feature_true.float())

        total_loss = loss_region + loss_feature
        return total_loss
import torch.optim as optim


#[21] Set training parameters
num_epochs = 100
batch_size = 16
lr = 0.001
list_loss = []

#[22] Prepare the data loader
transform = transforms.Compose([
    transforms.ToTensor()
])

#[23] Import data
train_dataset = Dataset_OM_Image(dir_S1_500, path_excel_S1_500, '01_Data')
train_dataloader = DataLoader(train_dataset, batch_size=batch_size, shuffle=True)

#[24] Instantiate the model, loss function, and optimizer
model = CNN_OM_Image_Classifier()
criterion = CustomLoss()
optimizer = torch.optim.Adam(model.parameters(), lr=lr)

#[25] Set device and move model to it
device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
model = model.to(device)

#[26] Training loop
for epoch in range(num_epochs):
    model.train()
    running_loss = 0.0

    for images, region, feature in train_dataloader:
        #[27] Move tensors to the configured device
        images = images.to(device)
        region = region.to(device)
        feature = feature.to(device).float()

        #[28] Forward pass and loss calculation
        optimizer.zero_grad()
        region_pred, feature_pred = model(images)
        loss = criterion(region_pred, feature_pred, region, feature)

        #[29] Backward pass and optimization
        loss.backward()
        optimizer.step()

        running_loss += loss.item()

    #[40] Print epoch loss
    epoch_loss = running_loss / len(train_dataloader)
    list_loss.append(epoch_loss)
    print(f'Epoch {epoch + 1}/{num_epochs}, Loss: {epoch_loss:.4f}')

print('\nTraining finished.\n\n')


def model_evaluation(model, val_dataloader, device, criterion, path_excel_output, sheet_name='02_Val'):
    #[50] Set the model to evaluation mode
    model.eval()
    val_loss = 0.0

    #[51] Initialize lists to store predictions
    region_preds = []
    feature_preds = []

    #[52] Evaluation loop
    with torch.no_grad():
        for i, (images, region, feature) in enumerate(val_dataloader, 1):
            images = images.to(device)
            region = region.to(device)
            feature = feature.to(device).float()

            #[53] Forward pass and loss calculation
            region_pred, feature_pred = model(images)
            loss = criterion(region_pred, feature_pred, region, feature)
            val_loss += loss.item()

            #[54] Store predictions
            region_preds.extend(torch.argmax(region_pred, dim=1).cpu().numpy())
            feature_preds.extend(feature_pred.squeeze().cpu().numpy())

            #[55] Print progress
            print(f'Batch {i}/{len(val_dataloader)}, Loss: {loss.item():.4f}')

    #[56] Calculate and print total validation loss
    val_loss = val_loss / len(val_dataloader)
    print(f'Validation Loss: {val_loss:.4f}')

    #[57] Create a DataFrame with predictions
    df_val = pd.DataFrame({
        'region_pred': region_preds,
        'feature_pred': feature_preds
    })

    #[58] Combine original annotations with predictions
    df_combined = pd.concat([val_dataloader.dataset.get_annotations(), df_val], axis=1)

    #[59] Save the combined DataFrame back to the Excel file
    save_df_as_excel_overwrite(df_combined, path_excel_output, sheet_name)

    print(f'Validation results saved to {path_excel_output}')

    return val_loss

