import os
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms
from PIL import Image

#[43] DataLoader for inference
class InferenceDataset(Dataset):
    def __init__(self, dir_images):
        self.dir_images = dir_images
        self.image_files = [f for f in os.listdir(dir_images) if f.lower().endswith(('.png', '.jpg', '.jpeg'))]
        self.transform = transforms.Compose([
            transforms.Resize((64, 64)),
            transforms.ToTensor(),
        ])

    def __len__(self):
        return len(self.image_files)

    def __getitem__(self, idx):
        img_name = self.image_files[idx]
        img_path = os.path.join(self.dir_images, img_name)
        image = Image.open(img_path).convert('RGB')
        image = self.transform(image)
        return image, img_name

def inference_data_loader(dir_images, batch_size=32):
    dataset = InferenceDataset(dir_images)
    return DataLoader(dataset, batch_size=batch_size, shuffle=False)


#[30] Function to inference data
def model_inference(model, inf_dataloader, device, path_excel_output, sheet_name='02_Inference'):
    #[31] Set the model to evaluation mode
    model.eval()

    #[32] Initialize lists to store predictions and image names
    list_image_names = []
    list_process_seq = []
    list_region_preds = []
    list_feature_preds = []

    #[33] Inference loop
    with torch.no_grad():
        for images, names in inf_dataloader:
            images = images.to(device)

            #[34] Forward pass
            region_pred, feature_pred = model(images)

            #[35] Store predictions and image names
            list_image_names.extend(names)
            list_process_seq.extend(range(len(names)))
            list_region_preds.extend(torch.argmax(region_pred, dim=1).cpu().numpy())
            list_feature_preds.extend(feature_pred.squeeze().cpu().numpy())

    #[36] Create a DataFrame with predictions
    df_inf = pd.DataFrame({
        'name': list_image_names,
        'process_seq': list_process_seq,
        'region_pred': list_region_preds,
        'feature_pred': list_feature_preds
    })
    df_inf = df_inf.sort_values(by='name')

    #[37] Map numeric region predictions back to string labels
    region_map_reverse = {0: 'background', 1: 'edge', 2: 'corner', 3: 'substrate'}
    df_inf['region_pred'] = df_inf['region_pred'].map(region_map_reverse)

    #[38] Round feature predictions to binary values
    df_inf['feature_pred'] = df_inf['feature_pred'].round().astype(int)

    #[39] Create excel and save the dataframe as a sheet.
    with pd.ExcelWriter(path_excel_output, engine='openpyxl', mode='w') as writer:
        df_inf.to_excel(writer, sheet_name=sheet_name, index=False)

    print(f'Inference results saved to {path_excel_output}')



