def inference_on_single_image(model, path_img, device):
    # [44] Load and preprocess the image
    transform = transforms.Compose([
        transforms.Resize((64, 64)),
        transforms.ToTensor(),
    ])

    image = Image.open(path_img).convert('RGB')
    image = transform(image).unsqueeze(0).to(device)

    # [45] Set model to evaluation mode and perform inference
    model.eval()
    with torch.no_grad():
        region_pred, feature_pred = model(image)

    # [46] Process predictions
    region_pred = torch.argmax(region_pred, dim=1).item()
    feature_pred = feature_pred.squeeze().item()

    # [47] Map region prediction to string label
    region_map_reverse = {0: 'background', 1: 'edge', 2: 'corner', 3: 'substrate'}
    region_pred_str = region_map_reverse[region_pred]

    # [48] Round feature prediction to binary value
    feature_pred_int = round(feature_pred)

    # [49] Create new filename with inference results
    bsn_ext = os.path.basename(path_img)
    bsn, ext = os.path.splitext(bsn_ext)
    bsn = bsn.split('_RP-')[0]
    new_name = f'{bsn}_RP-{region_pred_str}_FP-{feature_pred_int}{ext}'
    path_img_new = os.path.join(os.path.dirname(path_img), new_name)

    # [50] Rename the image with inference result
    os.rename(path_img, path_img_new)

    print(f'Image processe: {bsn_ext} \t Region: {region_pred_str} \t Feature: {feature_pred_int}')

    return region_pred_str, feature_pred_int, path_img_new


