def model_evaluation(model, val_dataloader, device, criterion, path_excel_output, sheet_name='02_Val'):
    #[50] Set the model to evaluation mode
    model.eval()
    val_loss = 0.0

    #[51] Initialize lists to store predictions
    region_preds = []
    feature_preds = []

    #[52] Evaluation loop
    with torch.no_grad():
        for i, (images, region, feature) in enumerate(val_dataloader, 1):
            images = images.to(device)
            region = region.to(device)
            feature = feature.to(device).float()

            #[53] Forward pass and loss calculation
            region_pred, feature_pred = model(images)
            loss = criterion(region_pred, feature_pred, region, feature)
            val_loss += loss.item()

            #[54] Store predictions
            region_preds.extend(torch.argmax(region_pred, dim=1).cpu().numpy())
            feature_preds.extend(feature_pred.squeeze().cpu().numpy())

            #[55] Print progress
            print(f'Batch {i}/{len(val_dataloader)}, Loss: {loss.item():.4f}')

    #[56] Calculate and print total validation loss
    val_loss = val_loss / len(val_dataloader)
    print(f'Validation Loss: {val_loss:.4f}')

    #[57] Create a DataFrame with predictions
    df_val = pd.DataFrame({
        'region_pred': region_preds,
        'feature_pred': feature_preds
    })

    #[58] Combine original annotations with predictions
    df_combined = pd.concat([val_dataloader.dataset.get_annotations(), df_val], axis=1)

    #[59] Save the combined DataFrame back to the Excel file
    save_df_as_excel_overwrite(df_combined, path_excel_output, sheet_name)

    print(f'Validation results saved to {path_excel_output}')

    return val_loss

