from PIL import Image, ImageDraw
import pandas as pd
from tabulate import tabulate



def extract_annotation_info_from_filename(bsnext, prefix='T'):
    """
    File name pattern:
    `T0001_R0-bkgd_F0-F.png`: the region is background; there is no feature (False).
    `T0002_R1-edge_F1-T.png`: the region is edge; there is feature (True).
    `T0003_R2-corn_F0-F.png`: the region is corner, there is no feature.
    `T0004_R3-subs_F1-T.png`: the region is substrate; there is feature.
    More file name examples: 
    T0081_R1-edge_F0-F.png, T0097_R2-corn_F0-F.png, T0120_R3-sub_F1-T.png, T0138_R3-sub_F1-T.png, T0087_R2-corn_F1-T.png.
    T0005_R0-bkgd_F0-F_rot(+40)_2V.png, T0919_R2-corn_F1-T_rot(+20)_3HV_exp(-30).png
    T0286_R1-edge_F_F1-T_rot(+00)_0O.png, T1655_R3-subs_F0-F_rot(+40)_0O.png
    
    File name examples: 
    T0919_R2-corn_F1-T_rot(+20)_3HV_exp(-30).png
    T0286_R1-edge_F1-T_rot(+00)_0O.png
    T1655_R3-subs_F0-F_rot(+40)_0O.png
    """
    #[1] Extract pattern from file name.
    base_name = os.path.splitext(bsnext)[0]  # Remove extension, e.g., 'T0001_R0-bkgd_F0-F'

    #[2] String manipulation to extract numbering, region, and feature
    fn_numbering = base_name.split('_')[0][len(prefix):]  # Extract numbering, e.g., '0001'
    
    #[5] Extract region, e.g., 'bkgd'
    region_info = base_name.split('_')[1]
    fn_region = region_info.split('-')[1]     # Extract region name after the hyphen
    
    #[7] Construct region key, e.g., '_R0-bkgd'
    region_key = f'_R{region_info[1]}-{fn_region}'
    
    #[8] Extract feature information, True if 'T', False if 'F'
    feature_info = base_name.split('_')[2]
    if '-' not in feature_info:
        raise ValueError(f"Feature information in filename '{bsnext}' is not formatted correctly.")
    fn_feature = feature_info.split('-')[1] == 'T'  # 'T' indicates True, 'F' indicates False
    
    #[9] Construct feature key, e.g., '_F1-T' or '_F0-F'
    feature_key = f'_F{int(fn_feature)}-{"T" if fn_feature else "F"}'

    return fn_numbering, region_key, feature_key

def convert_keys_to_names(region_key, feature_key):
    region_dict = {
        '_R0-bkgd': 'background',
        '_R1-edge': 'edge',
        '_R2-corn': 'corner',
        '_R3-subs': 'substrate'
    }
    
    feature_dict = {
        '_F0-F': 0,
        '_F1-T': 0
    }
    
    region_name = region_dict.get(region_key, 'unknown_region')
    feature_name = feature_dict.get(feature_key, 'unknown_feature')
    
    return region_name, feature_name


def OMIC_dataset_table_and_statistice(dir_dataset):
    print(f'\n[OMIC_dataset_statistice] dir_dataset: {dir_dataset}')
    
    #[1] Initialize a dictionary to hold the counts for each combination of region and feature
    count_dict = {
        '_R0-bkgd': {'_F0-F': 0, '_F1-T': 0},
        '_R1-edge': {'_F0-F': 0, '_F1-T': 0},
        '_R2-corn': {'_F0-F': 0, '_F1-T': 0},
        '_R3-subs': {'_F0-F': 0, '_F1-T': 0}
    }
    
    #[2] Create a list to hold the rows for the DataFrame
    table_rows = []

    #[3] List all files in the dataset directory
    for i_path in os.listdir(dir_dataset):
        if i_path.endswith('.png'):  # Assuming all files of interest are PNG images
            fn_numbering, region_key, feature_key = extract_annotation_info_from_filename(i_path)
            bsnext = os.path.basename(i_path)
            
            #[5] Add the row to the list
            region_name, feature_name = convert_keys_to_names(region_key, feature_key)
            table_rows.append({'bsnext': bsnext, 'region': region_name, 'feature': feature_name})

            #[7] Update counts in the dictionary
            if region_key in count_dict and feature_key in count_dict[region_key]:
                count_dict[region_key][feature_key] += 1

    #[8] Convert the list of rows to a DataFrame
    df_table = pd.DataFrame(table_rows, columns=['bsnext', 'region', 'feature'])

    #[10] Convert the count dictionary to a pandas DataFrame
    df_stat = pd.DataFrame(count_dict).T

    #[12] Compute row sums, column sums, and total
    df_stat['(row sum)'] = df_stat.sum(axis=1)  # Calculate the sum of each row
    col_sum = df_stat.sum(axis=0)  # Calculate the sum of each column
    df_stat.loc['(col sum)'] = col_sum  # Add a new row with the column sums

    #[15] Tabulate and print the DataFrame
    cnt_items = len(os.listdir(dir_dataset))
    print(f'{tabulate(df_stat, headers="keys", tablefmt="orgtbl")}\nTotal items in the directory: {cnt_items}')

    return df_stat, df_table



def move_all_files_to_the_surface(dir_main, print_status=False):
    """
    Moves all files in the subdirectories into the main directory and removes empty folders.

    Parameters:
    dir_main (str): The main directory path.
    print_status (bool): Whether to print status messages. Default is False.
    """
    print('\n[move_all_files_to_the_surface]')
    
    #[1] Ensure the main directory exists
    if not os.path.isdir(dir_main):
        print(f'Provided path is not a directory: {dir_main}')
        return
    
    #[2] Traverse through all subdirectories
    for root, dirs, files in os.walk(dir_main, topdown=False):
        if root == dir_main:
            continue  # Skip the main directory itself

        #[3] Move files to the main directory
        for sub_item in files:
            sub_item_full_path = os.path.join(root, sub_item)
            new_item_path = os.path.join(dir_main, sub_item)

            try:
                os.rename(sub_item_full_path, new_item_path)
                if print_status:
                    print(f'-- Moved: {sub_item} to {os.path.basename(dir_main)}')
            except FileExistsError:
                if print_status:
                    print(f'-- File already exists: {new_item_path}. Skipping.')
            except FileNotFoundError:
                if print_status:
                    print(f'-- File not found: {sub_item_full_path}. Skipping.')
            except Exception as e:
                if print_status:
                    print(f'-- Error moving file {sub_item_full_path}: {e}')

        #[4] Remove empty directories
        try:
            os.rmdir(root)
            if print_status:
                print(f'-- Removed empty folder: {root}')
        except OSError:
            if print_status:
                print(f'-- Folder not empty or cannot be removed: {root}')









def OMIC_save_df_as_excel_overwrite(df, path_xlsx, sheet_name):
    print('\n[save_df_as_excel_overwrite]')
    #[1] Make dir if not exist.
    dir_excel = os.path.dirname(path_xlsx)
    if not os.path.exists(dir_excel):
        os.makedirs(dir_excel)

    #[2] Use openpyxl to preserve existing sheets
    if os.path.exists(path_xlsx):
        with pd.ExcelWriter(path_xlsx, engine='openpyxl', mode='a', if_sheet_exists='replace') as writer:
            df.to_excel(writer, sheet_name=sheet_name, index=True)
    else:
        with pd.ExcelWriter(path_xlsx, engine='openpyxl') as writer:
            df.to_excel(writer, sheet_name=sheet_name, index=True)
            
    print(f'--Dataframe saved to {path_xlsx} in sheet {sheet_name}', end='\n\n')

def OMIC_adjust_multiple_column_widths(path_xlsx, sheet_name, list_column_letters, list_column_widths):
    print('\n[adjust_multiple_column_widths]')
    #[1] Check if list_column_letters and list_column_widths have the same length
    if len(list_column_letters) != len(list_column_widths):
        raise TypeError('The length of list_column_letters and list_column_widths are different, please check.')
    workbook = openpyxl.load_workbook(path_xlsx)
    
    #[2] Check if sheet_name exist
    if sheet_name not in workbook.sheetnames:
        print(f"--Sheet '{sheet_name}' does not exist in the workbook.")
        return
    worksheet = workbook[sheet_name]
    
    #[3] Adjust column width
    for col_letter, col_width in zip(list_column_letters, list_column_widths):
        worksheet.column_dimensions[col_letter].width = col_width
        print(f"--Column '{col_letter}' in sheet '{sheet_name}' has been adjusted to width {col_width}.")
    workbook.save(path_xlsx)
    print("--All specified columns have been adjusted.", end='\n\n')
