#[5] Fitting - Start

def double_lorentzian(x
                      , x01, gamma1, a1
                      , x02, gamma2, a2
                      , bl):
    # [1] Define the double Lorentzian function
    Lorentzian1 = a1 * gamma1**2 / ((x - x01)**2 + gamma1**2)
    Lorentzian2 = a2 * gamma2**2 / ((x - x02)**2 + gamma2**2)
    double_L = Lorentzian1 + Lorentzian2 + bl
    return double_L

def fit_two_peaks(list_possible_peaks, x_wavenumber, y_intensity):
    """
    Fits Raman data with two Lorentzian profiles for specified peak locations.
    possible_peaks: List of two possible peak locations.
    x_wavenumber: Array of wavenumber values.
    y_intensity: Array of intensity values.
    """
    
    #[1] Use the average value in the range lower than 350 wavenumber as base line.
    baseline = np.mean(y_intensity[x_wavenumber < 350])
    
    # [3] Initial guess for the parameters: [location1, FWHM1, intensity1, location2, FWHM2, intensity2]
    initial_guess = [list_possible_peaks[0], 10, max(y_intensity)
                     , list_possible_peaks[1], 10, max(y_intensity)
                     , baseline]
    
    try:
        # [5] Curve fitting with the double Lorentzian function
        popt, _ = curve_fit(double_lorentzian, x_wavenumber, y_intensity, p0=initial_guess)
        fit_loc1, fit_gamma1, fit_int1, fit_loc2, fit_gamma2, fit_int2, fit_bl = map(try_convert_float, popt)
        fit_FWHM1 = 2 * fit_gamma1
        fit_FWHM2 = 2 * fit_gamma2
        return np.array([fit_loc1, fit_int1, fit_FWHM1, fit_loc2, fit_int2, fit_FWHM2, fit_bl])
    except RuntimeError:
        return np.array([None, None, None, None, None, None, None])


def fit_the_spectrum_of_every_pixel_with_Lorentzian(array_data, list_possible_peaks=[385, 405]):
    """
    For MoS2, The E2g peak at around 385 cm-1 is the in-plane vibrations 
    with sulfur and molybdenum in opposite directions. 
    The A1g peak at around 405 cm-1 is the out-of-plane vibration 
    with only sulfur atom.
    """
    print(f'\n[fit_the_spectrum_of_every_pixel_with_Lorentzian] \tfit_loc1, fit_int1, fit_FWHM1, \tfit_loc2, fit_int2, fit_FWHM2, \tfit_bl')
    #[2] Get the number of data sets from the shape of the array
    num_data_sets = array_data.shape[1] - 1

    #[3] Extract the x-axis (wavenumber) from the first column
    x_wavenumber = array_data[:, 0]
    
    # [4] Initialize an empty array to store fitting results
    array_fitting_result = np.empty((7, 0))

    # [5] Iterate over each data set and fit the E2g and A1g Raman peak.
    for i in range(num_data_sets):
        iter_y_intensity = array_data[:, i + 1]
        iter_fitting_result = fit_two_peaks(list_possible_peaks, x_wavenumber, iter_y_intensity)
        array_fitting_result = np.hstack([array_fitting_result, iter_fitting_result.reshape(-1, 1)])

    return array_fitting_result
    

 
