def make_dir_if_not_exist(dir_to_make=None):
    #[1] If dir_to_make is not provided, make a dir at current directory with timestamp as folder name.
    if dir_to_make is None:
        dir_current = os.path.dirname(os.path.abspath(__file__))
        timestamp = datetime.now().strftime("%Y-%m%d-%H%M%S")
        dir_to_make = os.path.join(dir_current, f'{timestamp}_dir_name')
        
    #[2] Make dir.
    try:
        os.mkdir(dir_to_make)
        print("--Directory wasn't exists. Just made one.")
    except FileExistsError:
        print("--Directory already exists. Skipping directory creation.")




def save_2d_array_to_existing_excel(path_xlsx, array_2d, sheetname):
    """
    Saves a 2D array to a specified sheet in an existing Excel workbook.
    
    Args:
        path_xlsx (str): Path to the existing Excel file.
        array_2d (numpy.ndarray): 2D array to be saved.
        sheetname (str): Name of the sheet where the data will be saved.
    """
    print(f'\n[save_2d_array_to_existing_excel] {os.path.basename(path_xlsx)}')
    
    try:
        #[1] Open the existing Excel workbook
        workbook = openpyxl.load_workbook(path_xlsx)
        
        #[2] Check if the sheet exists, if not, create it
        if sheetname in workbook.sheetnames:
            sheet = workbook[sheetname]
        else:
            sheet = workbook.create_sheet(title=sheetname)
        
        #[3] Iterate over the 2D array and write data to the sheet
        for row_index, row_data in enumerate(array_2d, start=1):
            for col_index, cell_value in enumerate(row_data, start=1):
                sheet.cell(row=row_index, column=col_index, value=cell_value)
        
        #[4] Save the workbook with the updated data
        workbook.save(path_xlsx)
        
        #[5] Debug output for confirmation
        print(f'Data successfully saved to sheet "{sheetname}" in "{path_xlsx}".')
    
    except Exception as e:
        print(f"Error: {e}")
    



def read_excel_sheet_into_2d_array(path_xlsx, sheetname):
    
    #[1] Open the Excel sheet.
    workbook = openpyxl.load_workbook(path_xlsx)
    sheet = workbook[sheetname]
    
    #[3] Initialize an empty list to store rows.
    data = []
    
    #[4] Iterate over the rows in the sheet and append them to the list.
    for row in sheet.iter_rows(values_only=True):
        data.append(list(row))
    
    #[5] Convert the list of lists to a NumPy array.
    array_data = np.array(data)
    
    #[6] Debug output for array shape.
    print(f'\tarray_data.shape = {array_data.shape}')
    
    #[7] Return the NumPy array.
    return array_data


def read_text_from_txt(path_txt, char_preview=None):
    try:
        # [1] Open the file in read mode ('r') and read its content.
        with open(path_txt, 'r') as file:
            content = file.read()
            # [2] Print a preview of the content based on char_preview.
            if char_preview is not None:
                print('[read_txt] content quick view:\n', content[:char_preview])
        
        return content
    except FileNotFoundError:
        # [4] Handle the case where the file is not found.
        print(f'[read_txt] File not found:\n {path_txt}')
        sys.exit()
    except Exception as e:
        # [6] Handle any other exceptions that may occur while reading the file.
        print(f'[read_txt] An error occurred while reading the file:\n {str(e)}')
        sys.exit()



