def try_convert_float(value):
    try:
        return float(value)
    except ValueError:
        return value

def extract_raman_mapping_data_in_ASCII_txt_from_WITec(path_txt
                                                       , path_xlsx
                                                       , path_structure_info
                                                       , sheetname_01_Info='01_Info'
                                                       , sheetname_02_Data='02_Raw Data'):
    print(f'\n[remove_unnecessary_part_in_the_front_of_txt] \t working on {os.path.basename(path_txt)} ...')
    
    #[1] Open the text file with 'latin-1' encoding to handle non-UTF-8 characters.
    with open(path_txt, 'r', encoding='latin-1') as file:
        lines = file.readlines()

    #[2] Initialize start_index to None.
    start_index = None
    
    #[3] Find the line that ends with '\tCCD cts\n' and get the index of the line after it.
    for i, line in enumerate(lines):
        if line.endswith('\tCCD cts\n'):
            start_index = i + 1  # Set start_index to the next line
            break
        
    #[4] Extract part I list info.
    bsn_txt = os.path.basename(path_txt)
    partI_list_info = [bsn_txt] + lines[:start_index]

    #[10] Proceed if start_index is found
    if start_index is not None:
        
        #[11] Slice the list of lines from the start_index to the end
        partII_lines = lines[start_index:]
        
    #[13] In case there is no info in the first part.
    else:
        partI_list_info = [bsn_txt]
        partII_lines = lines
    
    #[15] Read 01_Data Structure Info.txt from path_structure_info and append it.
    list_structure_info = read_text_from_txt(path_structure_info, char_preview=None).split('\n')
    partI_list_info.extend(['', '', '', '', '', *list_structure_info])
    print(f'\t Size of partI_list_info = {len(partI_list_info)}')
        
    #[17] Convert list of lists to a NumPy array, and elements to float, and transpose for readability
    partII_array_data = np.array([i_lp2.split('\t') for i_lp2 in partII_lines if i_lp2.strip()])
    partII_array_data = np.array([[try_convert_float(cell) for cell in row] for row in partII_array_data])
    partII_array_data = partII_array_data.T
    print(f'\t Size of partII_array_data = {partII_array_data.shape}')

    #[24] Create a new Excel workbook. Write partI_list_info to the first sheet
    workbook = openpyxl.Workbook()
    sheet_info = workbook.active
    sheet_info.title = sheetname_01_Info
    for row_index, line in enumerate(partI_list_info, start=1):
        sheet_info.cell(row=row_index, column=1, value=line.strip())
    
    #[27] Create a new sheet for partII_array_data
    sheet_data = workbook.create_sheet(title=sheetname_02_Data)
    for row_index, row_data in enumerate(partII_array_data, start=1):
        for col_index, cell_value in enumerate(row_data, start=1):
            sheet_data.cell(row=row_index, column=col_index, value=cell_value)
    
    #[28] Save the workbook to the specified path
    workbook.save(path_xlsx)
    
    return partI_list_info, partII_array_data

    

def smooth_raman_data_with_Savitzky_Golay_filter_data_downward(path_xlsx
                                                                , window_length=11, polyorder=3
                                                                , sheetname_input='02_Raw Data'
                                                                , sheetname_output='03_Filtered Data'):
    """
    The first row is the x-axis, 
    the second row is the y-intensity of the first data, 
    the third row is the y-intensity of the second data, 
    and so on.
    Do Savitzky-Golay filtering on each column except the first column.
    Save the smoothed data as sheetname_output.
    
    """
    print(f'\n[smooth_raman_data_with_Savitzky_Golay_filter_data_downward]  \t working on {os.path.basename(path_xlsx)} ...')
    #[1] Open the Excel sheet.
    workbook = openpyxl.load_workbook(path_xlsx)
    sheet_input = workbook[sheetname_input]
    
    # [2] Read data from the input sheet
    data = []
    for row in sheet_input.iter_rows(values_only=True):
        data.append(row)
    
    # Convert data to a numpy array for easier manipulation
    array_data = np.array(data)
    
    # [3] Extract the x-axis (wavenumber) from the first column
    x_wavenumber = array_data[0, :]
    y_intensities = array_data[ 1:, :]
    
    # [4] Apply Savitzky-Golay filter to each column except the first
    smoothed_y_intensities = np.apply_along_axis(
        lambda y: savgol_filter(y, window_length, polyorder), axis=1, arr=y_intensities)
    
    # [5] Combine the x-axis and smoothed y-intensities back into one array
    smoothed_data = np.row_stack((x_wavenumber, smoothed_y_intensities))
    
    # [6] Check if the output sheet exists, if so, remove it
    if sheetname_output in workbook.sheetnames:
        del workbook[sheetname_output]
    
    # [7] Create a new sheet for the filtered data
    sheet_output = workbook.create_sheet(title=sheetname_output)
    
    # [8] Write the smoothed data to the output sheet
    for row in smoothed_data:
        sheet_output.append(row.tolist())
    
    # [9] Save the workbook with the updated data
    workbook.save(path_xlsx)
    
    # [10] Debug output for confirmation
    print(f'Data successfully saved to sheet "{sheetname_output}" in "{path_xlsx}".')


#[2] Raman Data Processing - End


















#[5] Fitting - Start

def double_lorentzian(x 
                      , x01, gamma1, a1
                      , x02, gamma2, a2
                      , bl):
    """
    x: the variable on X-axis.
    x01: the place of first peak.
    gamma1: the width of first peak.
    a1: the intensity of first peak.
    x02: the place of second peak.
    gamma2: the width of second peak.
    a2: the intensity of second peak.
    bl: the baseline intensity.
    """
    
    # [1] Define the double Lorentzian function
    Lorentzian1 = a1 * gamma1**2 / ((x - x01)**2 + gamma1**2)
    Lorentzian2 = a2 * gamma2**2 / ((x - x02)**2 + gamma2**2)
    double_L = Lorentzian1 + Lorentzian2 + bl
    return double_L

def fit_two_peaks(list_possible_peaks, x_wavenumber, y_intensity):
    """
    Fits Raman data with two Lorentzian profiles for specified peak locations.
    possible_peaks: List of two possible peak locations.
    x_wavenumber: Array of wavenumber values.
    y_intensity: Array of intensity values.
    fit_loss: the difference between the fitting result and the real curve.
    """
    
    #[1] Use the average value in the range lower than 350 wavenumber as base line.
    baseline = np.mean(y_intensity[x_wavenumber < 350])
    
    # [3] Initial guess for the parameters: [location1, FWHM1, intensity1, location2, FWHM2, intensity2]
    initial_guess = [list_possible_peaks[0], 10, max(y_intensity)
                     , list_possible_peaks[1], 10, max(y_intensity)
                     , baseline]
    
    try:
        # [3] Curve fitting with the double Lorentzian function
        popt, _ = curve_fit(double_lorentzian, x_wavenumber, y_intensity, p0=initial_guess)
        fit_loc1, fit_gamma1, fit_int1, fit_loc2, fit_gamma2, fit_int2, fit_bl = map(try_convert_float, popt)
        fit_FWHM1 = 2 * fit_gamma1
        fit_FWHM2 = 2 * fit_gamma2
        
        # [4] Calculate the fitted curve
        fitted_curve = double_lorentzian(x_wavenumber, fit_loc1, fit_gamma1, fit_int1, fit_loc2, fit_gamma2, fit_int2, fit_bl)
        
        # [5] Calculate the loss as the sum of squared residuals
        fit_loss = np.sum((y_intensity - fitted_curve) ** 2)
        
        return np.array([fit_loc1, fit_int1, fit_FWHM1, fit_loc2, fit_int2, fit_FWHM2, fit_bl, fit_loss])
    except RuntimeError:
        return np.array([None, None, None, None, None, None, None, None])


def fit_the_spectrum_of_every_pixel_with_Lorentzian(array_data, list_possible_peaks=[385, 405]):
    """
    For MoS2, The E2g peak at around 385 cm-1 is the in-plane vibrations 
    with sulfur and molybdenum in opposite directions. 
    The A1g peak at around 405 cm-1 is the out-of-plane vibration 
    with only sulfur atom.
    """
    print(f'\n[fit_the_spectrum_of_every_pixel_with_Lorentzian] \tfit_loc1, fit_int1, fit_FWHM1, \tfit_loc2, fit_int2, fit_FWHM2, \tfit_bl')
    #[2] Get the number of data sets from the shape of the array
    num_data_sets = array_data.shape[0] - 1

    #[3] Extract the x-axis (wavenumber) from the first column
    x_wavenumber = array_data[0, :]
    
    # [4] Initialize an empty array to store fitting results
    array_fitting_result = np.empty((0, 8))

    # [5] Iterate over each data set and fit the E2g and A1g Raman peak.
    for i in range(num_data_sets):
        iter_y_intensity = array_data[i + 1, :]
        iter_fitting_result = fit_two_peaks(list_possible_peaks, x_wavenumber, iter_y_intensity)
        array_fitting_result = np.vstack([array_fitting_result, iter_fitting_result.reshape(1, -1)])
        
        #[7] Fitting process.
        if i%10 == 0:
            print(f'[{i:04d}/{num_data_sets:04d}] iter_fitting_result: {iter_fitting_result}')

    return array_fitting_result



