def find_the_peak_among_top_n_points_data_downward(array_data, path_xlsx, sheetname='04_Top n', show_top=5, list_possible_peaks=[385, 405]):
    """
    In array_data, the first row is the x-axis, 
    the second row is the y-intensity of the first data, 
    the third row is the y-intensity of the second data, 
    and so on.    
    """
    print(f'\n[find_the_peak_among_top_n_points_data_downward] \t Size of data: {array_data.shape}, show top {show_top} of points.')
    
    #[2] Check if there is only two peaks.
    if len(list_possible_peaks) != 2:
        raise ValueError(f'list_possible_peaks should have a length of 2, it\'s now {list_possible_peaks}.')
    
    #[3] Extract the x-axis (wavenumber) from the first column
    x_wavenumber = array_data[0, :]
    y_intensities = array_data[1:, :]
    
    # [4] Calculate the max in each row in y_intensities, and find the index of top (show_top=5).
    max_int_in_each_point = np.max(y_intensities, axis=1)
    indices_of_top_n_point = np.argsort(max_int_in_each_point)[-show_top:][::-1]
    y_int_of_top_n_point = y_intensities[indices_of_top_n_point, :]
    array_data_top_n = np.vstack((x_wavenumber, y_int_of_top_n_point))
    print(f'[array_data_top_n.shape] {array_data_top_n.shape}')
    save_2d_array_to_existing_excel(path_xlsx, array_data_top_n, sheetname)
    
    # [5] Calculate the sum in each row in y_intensities, and find the index of the peak.
    sum_int_by_x_wn = np.sum(y_int_of_top_n_point, axis=1)
    indices_of_top_x_wn = np.argsort(sum_int_by_x_wn)[::-1][:50]
    print(f'[indices_of_top_x_wn] {indices_of_top_x_wn.tolist()}')
    
    #[5] Generate a new array of x_wavenumber from array of index indices_of_top_x_wn
    #top_x_wavenumbers = x_wavenumber[indices_of_top_x_wn]
    
    #[6] Start sorting.
    list_peak_E2g, list_peak_A1g = [], []
    k_wn = 8
    for i in indices_of_top_x_wn:
        
        #[7] Check the range of x_wn.
        i_x_wn = x_wavenumber[i]
        #print(f'[{i}] i_x_wn: {i_x_wn}\t', end='')
        if  abs(i_x_wn-list_possible_peaks[0]) < k_wn:
            if len(list_peak_E2g) <= 5:
                list_peak_E2g.append(i_x_wn)
        elif  abs(i_x_wn-list_possible_peaks[1]) < k_wn:
            if len(list_peak_A1g) <= 5:
                list_peak_A1g.append(i_x_wn)
                
    #[8] Average the peaks.
    peak_E2g = np.round(np.mean(list_peak_E2g), 3)
    peak_A1g = np.round(np.mean(list_peak_A1g), 3)
    diff_E2g_A1g = np.round(np.mean(list_peak_A1g) - np.mean(list_peak_E2g), 3)
    print(f'\t [peak_E2g]{peak_E2g:.3f}, \t list_peak_E2g: {list_peak_E2g}')      
    print(f'\t [peak_A1g]{peak_A1g:.3f}, \t list_peak_A1g: {list_peak_A1g}')
    print(f'\t\t A1g - E2g = {diff_E2g_A1g:.3f} (1/cm).')

    return peak_E2g, peak_A1g, diff_E2g_A1g
    
    
    
    
def plot_the_spectrum_of_top_n_points_at_once_to_check_data_downward(array_data, plot_title, path_save, plot_text=None, show_top=5):
    """
    The first column is the x-axis, 
    the second column is the y-intensity of the first data, 
    the third column is the y-intensity of the second data, 
    and so on.
    Plot the top 5 data on a single plot, with legend with the index of data.
    
    """
    print(f'\n[plot_the_spectrum_of_top_pixels_at_once_to_check] \t Size of data: {array_data.shape}, show top {show_top} of points.')
    #[1] Set plot
    fig, ax1 = plt.subplots(figsize=(16, 8))
    fs_axis = 16
    fs_title = 20
    fs_info = 12

    #[3] Extract the x-axis (wavenumber) from the first column
    x_wavenumber = array_data[0, :]
    y_intensities = array_data[1:, :]
    
    #[4] Calculate the max in each column in y_intensities, and find the index of top (show_top=5)).
    max_int_in_each_point = np.max(y_intensities, axis=1)
    indices_of_top_n_point = np.argsort(max_int_in_each_point)[-show_top:][::-1]

    #[4] Iterate over top_indices and plot it on the same axis
    for idx in indices_of_top_n_point:
        iter_y_intensity = y_intensities[idx, :]
        ax1.plot(x_wavenumber, iter_y_intensity, label=f'Mapping Point {idx + 1}', linewidth=0.5)

    #[5] Set axis labels and title
    ax1.set_xlabel('Wavenumber (1/cm)', fontsize=fs_axis)
    ax1.set_ylabel('Intensity', fontsize=fs_axis)    
    ax1.set_title(plot_title, fontsize=fs_title)
    ax1.legend(fontsize=fs_info)

    #[7] Save the figure
    if plot_text is not None:
        plt.figtext(0.15, 0.85, plot_text, fontsize=fs_info, va="top", ha="left", fontfamily='Consolas')
    plt.savefig(path_save)
    
#[7] Visualize - End

# End of [Module_1_Raman_Data_Processing.py]




