def gauss_kernel(k_size, sigma, a, b):
    print('\n[gauss_kernel]')
    ax = np.arange(-k_size // 2 + 1., k_size // 2 + 1.)
    xx, yy = np.meshgrid(ax, ax)
    kernel = np.exp(-(xx**2 + yy**2) / (2. * sigma**2))
    kernel = a * kernel + b
    return kernel


def filter_image(image, kernel, stride):
    if len(image.shape) == 2:  # Grayscale image
        H, W = image.shape
        filtered = np.zeros_like(image)
        filtered = convolve2d(image, kernel, mode='same')
    else: # BGR image
        H, W, channels = image.shape
        filtered = np.zeros_like(image)
        for i in range(channels):
            filtered[:, :, i] = convolve2d(image[:, :, i], kernel, mode='same')
    return filtered



def filter_image_with_stride(image, kernel, stride=1):
    kernel_height, kernel_width = kernel.shape
    if len(image.shape) == 2:  # Grayscale image
        H, W = image.shape
        output_height = (H - kernel_height) // stride + 1
        output_width = (W - kernel_width) // stride + 1
        filtered = np.zeros((output_height, output_width))
        for y in range(0, H - kernel_height + 1, stride):
            for x in range(0, W - kernel_width + 1, stride):
                filtered[y//stride, x//stride] = np.sum(image[y:y+kernel_height, x:x+kernel_width] * kernel)
    else:  # BGR image
        H, W, channels = image.shape
        output_height = (H - kernel_height) // stride + 1
        output_width = (W - kernel_width) // stride + 1
        filtered = np.zeros((output_height, output_width, channels))
        for i in range(channels):
            for y in range(0, H - kernel_height + 1, stride):
                for x in range(0, W - kernel_width + 1, stride):
                    filtered[y//stride, x//stride, i] = np.sum(image[y:y+kernel_height, x:x+kernel_width, i] * kernel)
    return filtered




def visualize_matrix(matrix, dpi=300):
    print('\n[visualize_matrix]')
    nrows, ncols = matrix.shape
    fig_size = (max(nrows, 5) * 0.5, max(ncols, 5) * 0.5)
    fig, ax = plt.subplots(figsize=fig_size, dpi=dpi)
    max_abs_val = np.max(np.abs(matrix))  # Find maximum of absolute value.
    im = ax.imshow(matrix, cmap='seismic_r', vmin=-max_abs_val, vmax=max_abs_val)
    # Optionally add gridlines for very small matrices
    if nrows <= 5 and ncols <= 5:
        ax.grid(which='major', color='black', linestyle='-', linewidth=2)
    # Matrix statistics
    stat_max, stat_min, stat_mean, stat_med = np.max(matrix), np.min(matrix), np.mean(matrix), np.median(matrix)
    stats_text = f'Shape: {nrows} × {ncols}\nMax: {stat_max:.3f}, Min: {stat_min:.3f}\nMean: {stat_mean:.3f}, Median: {stat_med:.3f}'
    print(f'{stats_text}\n\n')
    ax.text(0, -ncols//10, stats_text, fontsize=16, color='white', bbox=dict(facecolor='black', alpha=0.5))
    ax.axis('off')
    # Save the plot to a buffer
    buf = io.BytesIO()
    plt.savefig(buf, format='png', bbox_inches='tight', pad_inches=0.1)
    buf.seek(0)  # Rewind the buffer
    img_arr = np.array(Image.open(buf))
    buf.close()
    plt.close(fig)  # Close the plot to free up memory
    return img_arr


def increase_brightness_hsv(image, value=30):
    if len(image.shape) == 2:  # Grayscale image, single channel
        # Directly increase brightness with clipping to avoid overflow
        img_bright = cv2.add(image, value)
        img_bright = np.clip(img_bright, 0, 255)
    else:  # RGB image, three channels
        # Ref: https://stackoverflow.com/questions/32609098/how-to-fast-change-image-brightness-with-python-opencv
        hsv = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)  # Convert to HSV
        h, s, v = cv2.split(hsv)

        lim = 255 - value
        v[v > lim] = 255
        v[v <= lim] += value

        final_hsv = cv2.merge((h, s, v))
        img_bright = cv2.cvtColor(final_hsv, cv2.COLOR_HSV2BGR)  # Convert back to BGR

    return img_bright





def grayscale_blur_binarize(input_img, k, b, c):
    print('\n[grayscale_blur_binarize]')
    #[1] Handle different types of input (file path, PIL image, or NumPy array)
    if isinstance(input_img, str):  # if input is a file path
        arrimg_0_BGR = cv2.imread(input_img)
    elif isinstance(input_img, Image.Image):  # if input is a PIL image
        arrimg_0_BGR = np.array(input_img.convert('RGB'))[..., ::-1]  # Convert to BGR
    elif isinstance(input_img, np.ndarray):  # if input is already a NumPy array
        arrimg_0_BGR = input_img
    else:
        raise ValueError("Input type not supported. Provide a file path, PIL image, or NumPy array.")
    #[2] Process image
    print(f'--[arrimg_0_BGR] (Max, min, avg, std) = {arrimg_0_BGR.max()}, {arrimg_0_BGR.min()}, {round(arrimg_0_BGR.mean(),2)}, {round(np.std(arrimg_0_BGR),2)}')
    arrimg_1_gray = cv2.cvtColor(arrimg_0_BGR, cv2.COLOR_BGR2GRAY) 
    print(f'--[arrimg_1_gray] (Max, min, avg, std) = {arrimg_1_gray.max()}, {arrimg_1_gray.min()}, {round(arrimg_1_gray.mean(),2)}, {round(np.std(arrimg_1_gray),2)}')
    arrimg_2_blur = cv2.medianBlur(arrimg_1_gray, ksize=k)
    print(f'--[arrimg_2_blur] (Max, min, avg, std) = {arrimg_2_blur.max()}, {arrimg_2_blur.min()}, {round(arrimg_2_blur.mean(),2)}, {round(np.std(arrimg_2_blur),2)}')
    arrimg_3_binary = cv2.adaptiveThreshold(arrimg_2_blur
                                           , 255
                                           , cv2.ADAPTIVE_THRESH_GAUSSIAN_C
                                           , cv2.THRESH_BINARY
                                           , blockSize = b
                                           , C = c)
    print(f'--[arrimg_3_binary] (Max, min, avg, std) = {arrimg_3_binary.max()}, {arrimg_3_binary.min()}, {round(arrimg_3_binary.mean(),2)}, {round(np.std(arrimg_3_binary),2)}')
    return arrimg_3_binary




def array_image_stat(arrimg_1_gray, k, s):
    """
    A kernel of size k move across the arrimg_1_gray with stride s,
    calculate the max, min, and std within the kernal, 
    and return the result in a new array by
    storing max, min, and std at [:, :, 0], [:, :, 1], and [:, :, 2], respectively.
    If the input image has a img_W of 100, and (k, s) are set as (7, 5),
    the output out_W should be (img_W - k + 1)//s.
    """
    #[1] Check if is grayscale image.
    if len(arrimg_1_gray.shape) != 2:
        raise ValueError("Input array must be a grayscale image.")
    print(f'--[arrimg_1_gray.shape]{arrimg_1_gray.shape}')
    #[2] Scan across image.
    img_H, img_W = arrimg_1_gray.shape
    out_H, out_W = (img_H - k + 1)//s, (img_W - k + 1)//s
    arrimg_stat = np.zeros((out_H, out_W, 4), dtype=np.float32)
    for iter_oH in range(out_H):
        for iter_oW in range(out_W):
            window = arrimg_1_gray[iter_oH : iter_oH + k, iter_oW : iter_oW + k]
            arrimg_stat[iter_oH, iter_oW, 0] = window.max()
            arrimg_stat[iter_oH, iter_oW, 1] = window.min()
            arrimg_stat[iter_oH, iter_oW, 2] = window.mean()
            arrimg_stat[iter_oH, iter_oW, 3] = window.std()
    print(f'--[arrimg_max_min_std.shape]{arrimg_stat.shape}')
    return arrimg_stat




def save_3D_array_as_excel(array, dir_excel, bsn_excel):
    #[1] Check if the input is a 2D array and adjust it to 3D by adding an additional dimension
    if len(array.shape) == 2:
        array = array[:, :, np.newaxis]  # Convert 2D to 3D array with 1 channel
    elif len(array.shape) > 3:
        raise ValueError(f'Input array must be equal or less than 3D. Receiving shape of {array.shape}.')
    
    Channel = array.shape[2] if len(array.shape) > 2 else 1
    
    #[2] Put [:, :, 0], [:, :, 1], and [:, :, 2] at sheet1, sheet2, and sheet3, respectively.
    path_excel = os.path.join(dir_excel, f'{bsn_excel}.xlsx')
    with pd.ExcelWriter(path_excel) as writer:
        for iter_C in range(Channel):
            df = pd.DataFrame(array[:, :, iter_C])
            df.to_excel(writer, sheet_name=f'Channel {iter_C}', index=False, header=False)
    
    #[3] Apply conditional formatting with color scale
    workbook = openpyxl.load_workbook(path_excel)
    color_scale_rule = ColorScaleRule(start_type='min', start_color=Color('FF0000'),
                                      mid_type='percentile', mid_value=50, mid_color=Color('FFFFFF'),
                                      end_type='max', end_color=Color('0000FF'))
    for sheet in workbook.sheetnames:
        worksheet = workbook[sheet]
        worksheet.conditional_formatting.add(f'A1:{openpyxl.utils.get_column_letter(worksheet.max_column)}{worksheet.max_row}', color_scale_rule)
        # Set specific width for all columns (example: column width of 4)
        for col in worksheet.columns:
            worksheet.column_dimensions[openpyxl.utils.get_column_letter(col[0].column)].width = 4
        # Set height for all rows (example: row height of 20)
        for row in range(1, worksheet.max_row + 1):
            worksheet.row_dimensions[row].height = 20
    workbook.save(path_excel)
    print(f'--path_excel: {path_excel}')

    #[4] Normalize and save each channel as an image
    for iter_C in range(Channel):
        print(f'--iter_C: {iter_C}')
        array_2D = array[:, :, iter_C]
        normalized_array = normalize_2D_array_between_range(array_2D)
        bsn_image = f'{bsn_excel}_{iter_C}.png'
        print(f'--bsn_image: {bsn_image}')
        path_img = os.path.join(dir_excel, bsn_image)
        cv2.imwrite(path_img, normalized_array)
        
    return path_excel


def normalize_2D_array_between_range_from_Maxmin(array_2D, min = 0, max = 255):
    max_val, min_val = np.max(array_2D), np.min(array_2D)
    # Avoid division by zero
    array_2D_normalized = (((array_2D - min_val) / (max_val - min_val)) * max + min) if max_val != min_val else np.zeros_like(array_2D) * max + min
    array_2D_normalized = array_2D_normalized.astype(np.uint8)
    return array_2D_normalized


def normalize_2D_array_between_range_from_std(array_2D, std = 1, min = 0, max = 255):
    mean_val, std_val = np.mean(array_2D), np.std(array_2D)
    max_val, min_val = mean_val + std*std_val, mean_val - std*std_val
    # Avoid division by zero
    array_2D_normalized = (((array_2D - min_val) / (max_val - min_val)) * max + min) if max_val != min_val else np.zeros_like(array_2D) * max + min
    array_2D_normalized = array_2D_normalized.astype(np.uint8)
    return array_2D_normalized



