# Already import necessary libraries.


def inspect_glyph(font, unicode_char):
    print('\n[inspect_glyph]')
    cmap = font.getBestCmap()
    glyph_index = cmap[ord(unicode_char)]
    glyph = font['glyf'][glyph_index]

    # Access the horizontal metrics for the glyph
    hmtx = font['hmtx']
    advance_width, lsb = hmtx[glyph_index]

    print(f"Glyph Index: {glyph_index}")
    print(f"Advance Width: {advance_width}")
    print(f"Left Side Bearing: {lsb}")

    if glyph.isComposite():
        print("Composite Glyph. Components:")
        glyph.expand(font['glyf'])  # Decompose the glyph
        for component in glyph.components:
            print(f"  Base Glyph: {component.glyphName}")
            #print(f"  Transformation: {component.transform}")
    elif hasattr(glyph, 'coordinates'):
        print("Simple Glyph. Outlines:")
        coordinates = glyph.coordinates
        end_pts = glyph.endPtsOfContours
        start = 0
        for end in end_pts:
            contour = coordinates[start:end+1]
            print(f"  Contour: {contour}")
            start = end + 1
    else:
        print("Glyph has no outlines.")




def plot_glyph_from_unicode(font, unicode_char):
    print('\n[plot_glyph_from_unicode]')
    # Find the glyph index for the given unicode character
    cmap = font.getBestCmap()
    glyph_index = cmap[ord(unicode_char)]
    glyph = font['glyf'][glyph_index]
    
    print("unicode_char", '\n', glyph)

    if glyph.isComposite():
        # If the glyph is composite, decompose it to simple glyphs
        glyph.expand(font['glyf'])
        print('glyph.expand:', glyph)
    
    # Check if the glyph has contours
    if hasattr(glyph, 'coordinates'):
        coordinates = glyph.coordinates
        max_x = max(x for x, _ in coordinates)
        max_y = max(y for _, y in coordinates)
        
        # Start point for the first contour
        start = 0
        for end in glyph.endPtsOfContours:
            # The end index is inclusive, so we need to add 1
            contour = coordinates[start:end+1]
            
            # Separate x and y coordinates and convert them to lists
            xs, ys = zip(*contour)
            xs = list(xs)
            ys = list(ys)
            
            # Flip the y-coordinates and mirror the x-coordinates
            ys = [y for y in ys]
            xs = [x for x in xs]
            
            # Append the first point at the end to close the contour for plotting
            xs.append(xs[0])
            ys.append(ys[0])
            
            # Plot the contour
            plt.plot(xs, ys, marker='o')
            
            # Update the start point for the next contour
            start = end + 1
        
        # Set aspect ratio to be equal to avoid distortion
        plt.gca().set_aspect('equal', adjustable='box')
        
        plt.show()
    else:
        print("Glyph has no outlines.")

def inspect_bitmap_glyph(font, unicode_char):
    print('\n[inspect_bitmap_glyph]')
    glyph_index = font.getBestCmap().get(ord(unicode_char))
    
    # Check for bitmap data
    for table in ['EBDT', 'EBLC', 'CBDT', 'CBLC']:
        print('table:', table)
        if table in font:
            bitmap_data = font[table].getBitmap(glyph_index)
            print(f'--bitmap_data: {bitmap_data}')
            if bitmap_data:
                # If bitmap data is found, it can be shown using PIL
                stream = io.BytesIO(bitmap_data.data)
                image = Image.open(stream)
                image.show()
                return
            else:
                print(f"No bitmap glyph found for {unicode_char} in {table} table.")

    print(f"No bitmap glyph found for {unicode_char}.")
    
