plt.show()
import numpy as np
import matplotlib.pyplot as plt

def binomial_coefficient(upper, lower):
    """Return the binomial coefficient."""
    return factorial(upper) / (factorial(lower) * factorial(upper - lower))
    #If we use the above approach, it will overflow at n = 7.

def approximate_binomial_coefficient_upper(n):
    """Return the approximate binomial coefficient using Stirling's approximation."""
    numerator = upper_bound_stirling(2*n)
    denominator = lower_bound_stirling(n) * lower_bound_stirling(n)
    return numerator / denominator

def approximate_binomial_coefficient_lower(n):
    """Return the approximate binomial coefficient using Stirling's approximation."""
    numerator = lower_bound_stirling(2*n)
    denominator = upper_bound_stirling(n) * upper_bound_stirling(n)
    return numerator / denominator



max_n = 10

# Values of n
n_values = np.arange(1, max_n)  # Sample values up to 20 for a clearer plot

# Exact ratio values
ratios_upper = [approximate_binomial_coefficient_upper(n) / 2**(2*n) for n in n_values]
ratios_lower = [approximate_binomial_coefficient_lower(n) / 2**(2*n) for n in n_values]


#[] Approches that overflows
overflow_approach = [binomial_coefficient(2*n, n) / 2**(2*n) for n in n_values]


# Plotting
plt.figure(figsize=(10, 6))
plt.plot(n_values, ratios_upper, label='ratios_upper', linestyle='-', marker='o')
plt.plot(n_values, ratios_lower, label='ratios_lower', linestyle='-', marker='o')
plt.plot(n_values, overflow_approach, label='overflow_approach', linestyle='--', marker='x')


# Labelling the graph
plt.title("Exact and Approximated Ratio for Binomial Coefficient and Random Walk")
plt.xlabel('n')
plt.ylabel('Value')
plt.legend()

plt.grid(True)
plt.tight_layout()
plt.show()

