def Top_5(LRModel, ifPositive):
  LRCoef = LRModel.coef_.ravel()
  sortedCoef = np.sort(LRCoef)
  sortedIndices = np.argsort(LRCoef)
  if ifPositive:
    Top5Weights = np.flipud(sortedCoef[-5:])
    Top5Indices = np.flipud(sortedIndices[-5:])
  else:
    Top5Weights = sortedCoef[:5]
    Top5Indices = sortedIndices[:5]
  Top5Words = [vectorizer.tokenizer.token_to_word[idx] for idx in Top5Indices]
  for idx in range(5):
    print(Top5Weights[idx], Top5Words[idx])
  return Top5Words, Top5Weights

