def add_text_to_image(img, text):
    if len(img.shape) == 2:  # Grayscale 
        H, W = img.shape
        channel = 1
    else:  # Color 
        H, W, channel = img.shape
    position = (20, H + 35)
    font = cv2.FONT_HERSHEY_SIMPLEX
    font_scale = 0.8
    color = (32, 32, 32)
    thickness = 2
    line_type = cv2.LINE_AA
    line_spacing = 50
    lines = text.split('\n')
    if len(lines) >= 1:
        text_height = len(lines) * line_spacing
        if channel == 1:
            new_img = 255 * np.ones((H + text_height, W), dtype=np.uint8)
        else:
            new_img = 255 * np.ones((H + text_height, W, channel), dtype=np.uint8)
        if channel == 1:
            new_img[:H, :] = img if len(img.shape) == 2 else img[:, :, np.newaxis]
        else:
            new_img[:H, :, :] = img
    else:
        new_img = img
    for i, line in enumerate(lines):
        line_position = (position[0], position[1] + i * line_spacing)
        cv2.putText(new_img, line, line_position, font, font_scale, color, thickness, line_type)
    return new_img


def time_string():
    now = datetime.now()
    return now.strftime('%H%M%S')


def image_normalization(img, s=3, d=0):
    mean = np.mean(img)
    std = np.std(img)
    normalized_img = ((img - (mean - s*std)) * 255) / ((mean + s*std) - (mean - s*std))
    normalized_img = normalized_img - d
    normalized_img = np.clip(normalized_img, 0, 255)
    normalized_img = normalized_img.astype(np.uint8)
    return normalized_img



