def avi_to_jpg(path_avi, cnt_limit_frame):
    # Check if the video file exists
    if not os.path.exists(path_avi):
        print("Video file does not exist")
        return
    
    # Extract the directory and the base name of the AVI file
    dir_avi = os.path.dirname(path_avi)
    avi_basename = os.path.basename(path_avi).split('.')[0]
    
    # Create a new directory for the JPG frames
    jpg_frames_dir = os.path.join(dir_avi, f"{avi_basename}_jpg_frames")
    if not os.path.exists(jpg_frames_dir):
        os.makedirs(jpg_frames_dir)
    
    # Start converting the video
    vidcap = cv2.VideoCapture(path_avi)
    success, image = vidcap.read()
    count = 0
    
    while success and count < cnt_limit_frame:
        # Format the frame count with leading zeros
        framecount = "{:06d}".format(count)
        
        # Construct the filename and save the frame as a JPEG file
        jpg_filename = os.path.join(jpg_frames_dir, f"{framecount}.jpg")
        cv2.imwrite(jpg_filename, image)
        
        # Read the next frame
        success, image = vidcap.read()
        count += 1
        print(f"Saved frame {count}: ", success)
    
    # Release the video capture object
    vidcap.release()
    print("Conversion completed.")

